                const nextBtn = document.getElementById('feature-guide-next');
                prevBtn.style.visibility = currentFeatureGuide === 0 ? 'hidden' : 'visible';
                if (currentFeatureGuide === FEATURE_GUIDES.length - 1) {
                    nextBtn.textContent = 'Got it →';
                    nextBtn.onclick = () => closeModal('feature-guide-modal');
                } else {
                    nextBtn.textContent = 'Next →';
