        <?php endif; ?>

        <!-- ── TOAST ── -->
        <div id="toast-wrap"></div>

        <!-- ══════════════════════════════════════════
     JAVASCRIPT — ALL FUNCTIONS GLOBAL SCOPE
══════════════════════════════════════════ -->
        <script>
            const API_BASE = '?api=';
            const CSRF_TOKEN = '<?= htmlspecialchars(CSRF_TOKEN, ENT_QUOTES) ?>';
            const cur_page = '<?= $page ?>';
            // Default product photo (no-photo placeholder + broken-photo fallback
            // everywhere a product image is rendered). Resolved server-side so the
            // cache-buster query string matches the actual file on disk.
            const DEFAULT_PRODUCT_IMG = <?= json_encode(defaultProductImageUrl()) ?>;
            // Builds a product-photo URL with a cache-busting version token (the
            // product's updated_at). Without it, browsers pinned the OLD photo for
            // 30 days (the image endpoint's long cache) even after the owner replaced
            // the photo — making it look like the new upload "didn't save".
            function prodImgUrl(id, v) {
                return '?api=get_product_image&id=' + id + (v ? '&v=' + encodeURIComponent(v) : '');
            }
            const USER_ROLE = '<?= htmlspecialchars($currentUser['role'] ?? '') ?>';
            // Mirrors $storeSettings['shop_name'] server-side so printed receipts show
            // whatever the owner actually named their shop, instead of a hardcoded brand.
            const SHOP_NAME = <?= json_encode($storeSettings['shop_name']) ?>;
            // New, purely additive settings used only by the redesigned printed receipt
            // header — same pattern as SHOP_NAME above. Empty string means "not
            // configured yet", and the receipt template skips that line entirely rather
            // than printing a blank/undefined row.
            const SHOP_ADDRESS = <?= json_encode($storeSettings['shop_address']) ?>;
            const SHOP_TIN = <?= json_encode($storeSettings['shop_tin']) ?>;
            const TERMINAL_ID = <?= json_encode($storeSettings['terminal_id']) ?>;
            // Cash-drawer-via-QZ-Tray config. QZ_DRAWER_ENABLED gates the automatic
            // post-payment kick; QZ_DRAWER_PRINTER is the exact OS printer name the
            // drawer is physically wired to (leave blank until Settings is configured
            // — never guess/fall back to "the first printer found", since that could
            // pulse the wrong device). Both re-read live from Settings if changed
            // there (see saveDrawerConfig()), these are just the page-load values.
            let QZ_DRAWER_ENABLED = <?= json_encode(!empty($storeSettings['qz_drawer_enabled'])) ?>;
            let QZ_DRAWER_PRINTER = <?= json_encode($storeSettings['qz_drawer_printer'] ?? '') ?>;
            const CASHIER_NAME = <?= json_encode($currentUser['full_name'] ?? '') ?>;
            const SHOW_SHIFT_LOCK_ON_LOAD = <?= $showShiftLockOnLoad ? 'true' : 'false' ?>;

            // ── API ──
            const API_TIMEOUT_MS = 20000; // generous for slow/free hosting, but finite — requests never hang forever

            // A raw network failure (offline / DNS / connection reset) never reached the
            // server at all, so it's safe to silently retry once — nothing could have
            // been double-processed server-side either way. Our OWN timeout (AbortError)
            // is deliberately NOT retried — surface it right away instead of making the
            // cashier wait twice as long for the same likely outcome.
            async function apiFetch(url, opts = {}, _retried = false) {
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), API_TIMEOUT_MS);
                try {
                    // cache:'no-store' — belt-and-suspenders alongside the server's
                    // Cache-Control:no-store header, so a phone's browser cache can never
                    // hand back a stale API response (e.g. a deleted category reappearing)
                    // after a hard refresh.
                    const r = await fetch(url, {
                        ...opts,
                        cache: 'no-store',
                        signal: ctrl.signal
                    });
                    clearTimeout(timer);
                    return r;
                } catch (e) {
                    clearTimeout(timer);
                    if (!_retried && e.name !== 'AbortError' && navigator.onLine !== false) {
                        await new Promise(res => setTimeout(res, 1200));
                        return apiFetch(url, opts, true);
                    }
                    throw e;
                }
            }

            function apiErrorMessage(e) {
                if (e && e.name === 'AbortError') return '⏱️ Server is taking too long to respond — please try again.';
                if (navigator.onLine === false) return '📶 You appear to be offline — check your connection and try again.';
                return '⚠️ Could not reach the server — check your connection and try again.';
            }
            async function apiGet(action, params = {}) {
                const qs = new URLSearchParams(params).toString();
                const url = API_BASE + action + (qs ? '&' + qs : '');
                try {
                    const r = await apiFetch(url);
                    if (r.status === 401) {
                        location.href = '?page=login';
                        return null;
                    }
                    if (!r.ok) {
                        toast('⚠️ Server error (' + r.status + ') — please try again', 'error');
                        return null;
                    }
                    return await r.json(); // must await inside try/catch, or a malformed response silently fails with no toast at all
                } catch (e) {
                    toast(apiErrorMessage(e), 'error');
                    return null;
                }
            }
            async function apiPost(action, body = {}) {
                try {
                    const r = await apiFetch(API_BASE + action, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRF-Token': CSRF_TOKEN
                        },
                        body: JSON.stringify(body)
                    });
                    if (r.status === 401) {
                        location.href = '?page=login';
                        return null;
                    }
                    if (!r.ok) {
                        toast('⚠️ Server error (' + r.status + ') — please try again', 'error');
                        return null;
                    }
                    return await r.json();
                } catch (e) {
                    toast(apiErrorMessage(e), 'error');
                    return null;
                }
            }

            // ── LIGHT/DARK APP THEME ──
            // Toggles the html.theme-light class (see the CSS override block
            // near --nav in the <style>), persists the choice in
            // localStorage so it survives reloads and applies instantly on
            // next page load (see the tiny inline script in <head>), and
            // keeps every "current theme" UI control in sync — the nav icon
            // button plus the Settings → Appearance switch, if present on
            // this page.
            function applyTheme(theme, persist) {
                const isLight = theme === 'light';
                document.documentElement.classList.toggle('theme-light', isLight);
                if (persist) localStorage.setItem('pos_theme', isLight ? 'light' : 'dark');

                const navBtn = document.getElementById('theme-toggle-btn');
                if (navBtn) {
                    navBtn.textContent = isLight ? '☀️' : '🌙';
                    navBtn.title = isLight ? 'Switch to dark mode' : 'Switch to light mode';
                }
                const settingsToggle = document.getElementById('appearance-theme-toggle');
                if (settingsToggle) settingsToggle.checked = isLight;
                const settingsLabel = document.getElementById('appearance-theme-label');
                if (settingsLabel) settingsLabel.textContent = isLight ? 'Light mode' : 'Dark mode';
            }

            function toggleTheme() {
                const nowLight = !document.documentElement.classList.contains('theme-light');
                applyTheme(nowLight ? 'light' : 'dark', true);
            }

            // Sync every theme control to whatever the inline <head> script
            // already applied before paint (it only adds the CSS class —
            // it doesn't know about these UI controls, which don't exist
            // yet at that point in <head>).
            applyTheme(document.documentElement.classList.contains('theme-light') ? 'light' : 'dark', false);

            // ── MODALS ──
            // ── BACK BUTTON / EDGE-SWIPE GUARD ──
            // On mobile, an accidental back press or edge-swipe used to exit the
            // whole web app — which felt exactly like being logged out. Trap the
            // history instead: back does nothing while the app is open. Leaving
            // is always deliberate — the Logout button is a real navigation and
            // is not affected by this guard.
            history.replaceState({ posApp: 1 }, '', location.href);
            window.addEventListener('popstate', function () {
                history.pushState({ posApp: 1 }, '', location.href);
            });

            function openModal(id) {
                const e = document.getElementById(id);
                if (e) {
                    e.classList.add('open');
                    e.querySelector('.modal')?.scrollTo(0, 0);
                    // The Cart modal has its own purpose-built keyboard system
                    // (initCartKeyboardNav, further down) plus the global HID barcode-
                    // scanner listener that must be free to route a scan to "add 1 unit"
                    // rather than land in whichever field happens to be focused. Auto-
                    // focusing a qty input here used to do exactly that: a second scan of
                    // the same product would type its digits straight into the focused qty
                    // box, which the app correctly-but-unluckily reads as "set quantity to
                    // this typed number" and clamps to available stock — showing the whole
                    // stock count instead of incrementing by 1. So Cart is excluded from
                    // both generic behaviors below; every other modal (Add Product, Start/
                    // End Shift, Void Order, etc.) still gets them.
                    if (id !== 'cart-modal') {
                        enableEnterNav(id);
                        // Keyboard-only navigation: whenever a non-Cart modal opens, focus
                        // jumps straight to its first field so typing/Enter can drive the
                        // whole form without ever touching the mouse. A tiny delay lets
                        // display:flex/open transitions finish first — focusing mid-
                        // transition on some browsers silently fails.
                        setTimeout(() => focusFirstField(e), 60);
                    }
                }
            }

            function closeModal(id) {
                const e = document.getElementById(id);
                if (e) e.classList.remove('open');
            }

            // Focuses the first visible, enabled, non-hidden input/select/textarea inside
            // a modal (or any container). "Visible" is required because many modals keep
            // later steps in the DOM with display:none until earlier steps are done.
            function focusFirstField(container) {
                const field = Array.from(container.querySelectorAll(
                    'input:not([type=hidden]):not([disabled]), select:not([disabled]), textarea:not([disabled])'
                )).find(f => f.offsetParent !== null);
                if (field) {
                    field.focus();
                    if (field.select) field.select();
                }
            }

            // Generic "Enter behaves like Tab" navigation for keyboard-only use: press
            // Enter in any field to jump to the next visible field, all the way down to
            // the submit button, with no mouse required. Skips textareas (Enter should
            // insert a newline there) and any field that already defines its own
            // onkeydown behavior (e.g. barcode fields that verify on Enter) so this
            // never overrides more specific existing logic.
            function enableEnterNav(modalId) {
                const modal = document.getElementById(modalId);
                if (!modal || modal.dataset.enterNavBound) return;
                modal.dataset.enterNavBound = '1';
                modal.addEventListener('keydown', function(e) {
                    if (e.key !== 'Enter') return;
                    const el = e.target;
                    if (el.tagName === 'TEXTAREA' || el.tagName === 'BUTTON') return;
                    if (el.type === 'checkbox' || el.type === 'radio') return;
                    if (el.hasAttribute('onkeydown')) return;
                    const focusables = Array.from(modal.querySelectorAll(
                        'input:not([type=hidden]):not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled])'
                    )).filter(f => f.offsetParent !== null);
                    const idx = focusables.indexOf(el);
                    if (idx === -1) return;
                    e.preventDefault();
                    if (idx < focusables.length - 1) {
                        const next = focusables[idx + 1];
                        next.focus();
                        if (next.select) next.select();
                    } else {
                        el.blur(); // last field — nothing further to advance to
                    }
                });
            }
            // NOTE: tapping the dark backdrop outside a modal deliberately does
            // NOTHING. On phones an accidental tap while scrolling used to throw
            // away whatever the user was doing (a half-filled Add Product form,
            // the open Cart). Every modal is closed ONLY by its own buttons —
            // Cancel / ✕ / Save — never by the backdrop.

            // Global keyboard shortcuts for mouse-free / keyboard-only operation:
            // - Ctrl+Enter is the Add/Edit Product modal's "Save Product" shortcut,
            //   so the cashier/admin never has to reach for the mouse to finish a
            //   long form. (Esc no longer closes modals — same reason as the
            //   backdrop above: popups close only via their own buttons.)
            document.addEventListener('keydown', e => {
                if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                    const prodModal = document.getElementById('prod-modal');
                    if (prodModal && prodModal.classList.contains('open')) {
                        e.preventDefault();
                        saveProduct();
                    }
                }
                // Payment Receipt shortcuts — Enter = Done, P = Print. Skipped while
                // typing in a field (there aren't any on this modal, but this keeps
                // the pattern safe if one's ever added) and while a modifier key is
                // held, so Ctrl/Cmd+P still opens the browser's own print shortcut.
                const successModal = document.getElementById('success-modal');
                if (successModal && successModal.classList.contains('open') && !e.ctrlKey && !e.metaKey && !e.altKey) {
                    const tag = (e.target.tagName || '').toLowerCase();
                    if (tag === 'input' || tag === 'textarea') return;
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        closeModal('success-modal');
                    } else if (e.key === 'p' || e.key === 'P') {
                        e.preventDefault();
                        printSaleReceipt();
                    }
                }
            });

            // ── TOAST ──
            function toast(msg, type = 'default') {
                const wrap = document.getElementById('toast-wrap');
                const el = document.createElement('div');
                el.className = 'toast ' + type;
                const icons = {
                    success: '✓',
                    error: '✗',
                    warning: '⚠',
                    default: 'ℹ'
                };
                el.innerHTML = '<span>' + (icons[type] || 'ℹ') + '</span> ' + msg;
                wrap.appendChild(el);
                setTimeout(() => el.remove(), type === 'error' ? 5000 : 3200);
            }

            // ── FORMATTING ──
            let CUR = '₱';
            let VAT_RATE = 0;
            let TAX_RATE = 0;

            function fmt(n) {
                return CUR + parseFloat(n || 0).toFixed(2);
            }

            // A product photo's DB record can outlive the actual file on disk (e.g. an
            // upload that predates a server restart without a properly persisted disk
            // — see get_product_image's disk-then-DB-blob fallback). Rather than the
            // browser's ugly native "broken image" icon, swap in the same default
            // product photo (DEFAULT_PRODUCT_IMG) used for products with no photo
            // at all. The product id is passed as a data attribute, not interpolated
            // into an onerror string (which would fight HTML-attribute quoting).
            function imgFallback(el) {
                const kind = el.dataset.fallback || 'emoji';
                if (kind === 'div') {
                    const div = document.createElement('div');
                    div.className = 'product-card-ph';
                    div.innerHTML = '<img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt="">';
                    el.replaceWith(div);
                } else if (kind === 'cart') {
                    const div = document.createElement('div');
                    div.className = 'cart-line-img';
                    div.innerHTML = '<img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt="">';
                    el.replaceWith(div);
                } else if (kind === 'blank') {
                    el.remove();
                } else {
                    const ph = document.createElement('img');
                    ph.src = DEFAULT_PRODUCT_IMG;
                    ph.className = 'default-prod-img';
                    ph.alt = '';
                    el.replaceWith(ph);
                }
            }

            function escapeHtml(s) {
                return String(s ?? '').replace(/[&<>"']/g, c => ({
                    '&': '&amp;',
                    '<': '&lt;',
                    '>': '&gt;',
                    '"': '&quot;',
                    "'": '&#39;'
                } [c]));
            }

            // JSON.stringify a value for embedding as an ARGUMENT inside an inline
            // on* handler that itself sits inside a double-quoted HTML attribute —
            // e.g. onmousedown="selectThing(VALUE)". JSON.stringify on its own wraps
            // strings in double quotes, which collide with the attribute's own
            // double-quote delimiters: the browser's HTML parser ends the attribute
            // at that first embedded ", leaving everything after it as broken
            // markup and the handler itself as truncated, invalid JavaScript that
            // silently does nothing when clicked. Escaping those quotes to &quot;
            // keeps the attribute well-formed; the browser un-escapes &quot; back to
            // a literal " before the JS ever runs, so the value still parses
            // correctly on the other end.
            function jsAttr(value) {
                return JSON.stringify(value).replace(/"/g, '&quot;');
            }

            // "230 (ml)", "XXL – 15kg & up (size)" — a single consistent rendering of
            // unit_type + unit_size for the product-detail summaries in Cart, the
            // Dashboard product cards, and Sales History, matching the format already
            // used in the Warehouse product-details modal.
            function formatUnitSizeLabel(unitType, unitSize) {
                if (!unitType) return '';
                return unitType + (unitSize ? ' (' + unitSize + ')' : '');
            }

            // Ranks autocomplete matches so the most relevant ones lead: entries
            // whose text STARTS WITH what was typed come first (alphabetical among
            // themselves), then entries that merely CONTAIN it elsewhere (also
            // alphabetical) — instead of raw list order, which could put an
            // unrelated match (e.g. "555 SARDINES", matching only because the word
            // "Sardines" happens to contain the letter typed) ahead of an obviously
            // closer one (e.g. "Alaska").
            function rankAutocompleteMatches(items, query, getText) {
                const q = (query || '').toLowerCase();
                const starts = [],
                    contains = [];
                for (const item of items) {
                    const text = getText(item).toLowerCase();
                    if (!q || text.startsWith(q)) starts.push(item);
                    else if (text.includes(q)) contains.push(item);
                }
                const byText = (a, b) => getText(a).localeCompare(getText(b));
                starts.sort(byText);
                contains.sort(byText);
                return [...starts, ...contains];
            }

            function cartTotals() {
                const subtotal = cart.reduce((s, c) => s + computeUnitBreakdown(c).subtotal, 0);
                const vat = subtotal * VAT_RATE / 100;
                const tax = subtotal * TAX_RATE / 100;
                return { subtotal, vat, tax, total: subtotal + vat + tax };
            }

            function fmtDate(iso) {
                return new Date(iso).toLocaleString('en', {
                    month: 'short',
                    day: 'numeric',
                    year: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit'
                });
            }

            // ════════════════════════════════════════════════
            // SHIFT LIFECYCLE — "No Count, No Transaction"
            // Handles: mandatory opening float count (clock-in lock),
            // live active-shift tracking, and mandatory closing count
            // (clock-out lock) with variance + Z-Read receipt.
            // ════════════════════════════════════════════════
            const SHIFT_DENOMS = [{
                    key: 'b1000',
                    label: '₱1,000',
                    value: 1000
                },
                {
                    key: 'b500',
                    label: '₱500',
                    value: 500
                },
                {
                    key: 'b200',
                    label: '₱200',
                    value: 200
                },
                {
                    key: 'b100',
                    label: '₱100',
                    value: 100
                },
                {
                    key: 'b50',
                    label: '₱50',
                    value: 50
                },
                {
                    key: 'b20',
                    label: '₱20',
                    value: 20
                },
                {
                    key: 'c20',
                    label: '₱20 (coin)',
                    value: 20
                },
                {
                    key: 'c10',
                    label: '₱10 (coin)',
                    value: 10
                },
                {
                    key: 'c5',
                    label: '₱5 (coin)',
                    value: 5
                },
                {
                    key: 'c1',
                    label: '₱1 (coin)',
                    value: 1
                },
                {
                    key: 'c025',
                    label: '25¢ (coin)',
                    value: 0.25
                },
            ];
            let shiftMode = null; // 'open' | 'close'
            let shiftLoggingOut = false; // true when the close-count was triggered by a logout attempt

            function renderShiftDenomGrid() {
                const wrap = document.getElementById('shift-denom-grid');
                if (!wrap) return;
                wrap.innerHTML = SHIFT_DENOMS.map(d =>
                    '<div class="shift-denom-row">' +
                    '<span class="shift-denom-label">' + d.label + '</span>' +
                    '<input type="number" inputmode="numeric" min="0" step="1" class="shift-denom-input" data-value="' + d.value + '" oninput="updateShiftTotal()" placeholder="0"/>' +
                    '<span class="shift-denom-total" id="sdt-' + d.key + '">' + fmt(0) + '</span>' +
                    '</div>'
                ).join('');
            }

            function updateShiftTotal() {
                let total = 0;
                const inputs = document.querySelectorAll('.shift-denom-input');
                inputs.forEach((inp, idx) => {
                    const val = parseFloat(inp.dataset.value);
                    const qty = parseInt(inp.value) || 0;
                    const sub = val * qty;
                    total += sub;
                    const d = SHIFT_DENOMS[idx];
                    const totEl = document.getElementById('sdt-' + d.key);
                    if (totEl) totEl.textContent = fmt(sub);
                });
                const curEl = document.getElementById('shift-current-total');
                if (curEl) curEl.textContent = fmt(total);
                const btn = document.getElementById('shift-save-btn');
                if (btn) btn.disabled = total <= 0;
                // NOTE: no expected-cash or variance calculation happens here on purpose —
                // BLIND COUNT ENFORCEMENT means the cashier only ever sees their own physical
                // count while counting, both at open and close. Variance is computed
                // server-side in close_shift and only surfaces afterward on the printed receipt.
                return total;
            }

            // Runs on every protected page load — the "No Count, No Transaction" gate.
            // ADMIN/OWNER BYPASS: owners never see this, regardless of any shift data.
            function checkShiftLock() {
                if (cur_page === 'login' || USER_ROLE === 'owner') {
                    document.body.classList.remove('shift-locked');
                    return;
                }
                // Server already determined on render that this cashier has no open shift —
                // paint the modal immediately so there's zero flash of the unlocked POS.
                if (SHOW_SHIFT_LOCK_ON_LOAD) openShiftOpenModal();

                apiGet('check_cash_float').then(r => {
                    if (!r?.success) return;
                    const d = r.data;
                    if (!d.initialized) {
                        openShiftOpenModal();
                    } else {
                        document.body.classList.remove('shift-locked');
                        closeModal('shift-modal');
                    }
                });
            }

            function openShiftOpenModal() {
                shiftMode = 'open';
                shiftLoggingOut = false;
                document.body.classList.add('shift-locked');
                document.getElementById('shift-modal-title').textContent = '💰 Start of Shift — Cash Count';
                document.getElementById('shift-modal-sub').textContent = 'Count the physical cash in the drawer and enter each denomination below. The Sales screen stays locked until this is saved.';
                document.getElementById('shift-cancel-wrap').style.display = 'none';
                document.getElementById('shift-save-btn').textContent = '✅ Save & Open Shift';
                renderShiftDenomGrid();
                updateShiftTotal();
                openModal('shift-modal');
            }

            // BLIND COUNT ENFORCEMENT: the expected cash and any live variance are
            // intentionally never fetched or rendered here — only the physical count
            // the cashier enters is shown, to prevent them reverse-engineering the
            // expected total and covering up a shortage. Variance is only revealed
            // afterward, on the printed Z-Read receipt.
            function openShiftCloseModal(loggingOut) {
                apiGet('check_cash_float').then(r => {
                    if (!r?.success || !r.data.initialized) {
                        if (loggingOut) {
                            location.href = '?page=logout';
                        } else toast('No active shift to close', 'warning');
                        return;
                    }
                    shiftMode = 'close';
                    shiftLoggingOut = !!loggingOut;
                    document.body.classList.add('shift-locked');
                    document.getElementById('shift-modal-title').textContent = '🔒 End of Shift — Blind Cash Count';
                    document.getElementById('shift-modal-sub').textContent = 'The drawer has popped open. Count every bill and coin currently inside and enter it below — the expected amount is hidden until your shift report prints.';
                    document.getElementById('shift-cancel-wrap').style.display = 'block';
                    document.getElementById('shift-save-btn').textContent = '🖨️ Submit & Close Shift';
                    renderShiftDenomGrid();
                    updateShiftTotal();
                    openModal('shift-modal');
                    toast('🔓 Cash drawer released — begin your closing count', 'default');
                });
            }

            function cancelShiftModal(e) {
                if (e) e.preventDefault();
                if (shiftMode === 'open') return; // opening count can never be skipped
                closeModal('shift-modal');
                document.body.classList.remove('shift-locked');
                shiftMode = null;
            }

            // Nav "🔚 End Shift" button
            function requestEndShift() {
                openShiftCloseModal(false);
            }

            // Intercepts the Logout link — forces a closing cash count first if a shift is open
            function attemptLogout(e) {
                e.preventDefault();
                if (USER_ROLE === 'owner') {
                    location.href = '?page=logout';
                    return false;
                }
                apiGet('check_cash_float').then(r => {
                    if (r?.success && r.data.initialized) {
                        openShiftCloseModal(true);
                    } else {
                        location.href = '?page=logout';
                    }
                });
                return false;
            }

            function submitShiftModal() {
                const total = updateShiftTotal();
                if (total <= 0) {
                    toast('Enter a valid, non-zero cash count', 'warning');
                    return;
                }
                const denoms = {};
                document.querySelectorAll('.shift-denom-input').forEach((inp, idx) => {
                    denoms[SHIFT_DENOMS[idx].key] = parseInt(inp.value) || 0;
                });
                const btn = document.getElementById('shift-save-btn');
                setLoading(btn, true);

                if (shiftMode === 'open') {
                    apiPost('start_shift', {
                        denoms,
                        total
                    }).then(r => {
                        setLoading(btn, false);
                        if (!r?.success) {
                            toast(r?.error || 'Could not start shift', 'error');
                            return;
                        }
                        toast('✅ Shift started! Opening float: ' + fmt(total), 'success');
                        document.body.classList.remove('shift-locked');
                        closeModal('shift-modal');
                        shiftMode = null;
                    });
                } else {
                    apiPost('close_shift', {
                        denoms,
                        total
                    }).then(r => {
                        setLoading(btn, false);
                        if (!r?.success) {
                            toast(r?.error || 'Could not close shift', 'error');
                            return;
                        }
                        printShiftReceipt(r.data);
                        closeModal('shift-modal');
                        // Wipe session only after the receipt has been handed to the printer
                        setTimeout(() => {
                            location.href = '?page=logout';
                        }, 600);
                    });
                }
            }

            // ── SHARED RECEIPT STYLING (Payment / Z-Read / Void) ──
            // The Payment Receipt (printSaleReceipt, below) is the canonical design.
            // These helpers are pulled out so the SF Mono look, dashed dividers, and
            // the shop address/TIN header are IDENTICAL across all three printed
            // documents — one CSS block, one header builder, one footer builder,
            // instead of three copies slowly drifting apart from each other.
            function receiptBaseCSS() {
                return '.receipt-container{width:290px;background:#fff;padding:10px 8px;font-family:"SF Mono","Menlo","Consolas","Courier New",monospace;font-size:12.5px;line-height:1.4;color:#000;margin:0 auto;}' +
                    '.receipt-header{text-align:center;margin-bottom:6px;}' +
                    '.receipt-header h1{font-size:22px;font-weight:800;margin:0 0 4px 0;letter-spacing:1px;}' +
                    '.receipt-header p{margin:1px 0;font-size:11px;}' +
                    '.receipt-header .doc-type{font-size:10.5px;font-weight:800;letter-spacing:.06em;color:#444;margin-top:4px;}' +
                    '.divider{border-top:1px dashed #000;margin:6px 0;}' +
                    '.receipt-row{display:flex;justify-content:space-between;width:100%;margin:1px 0;}' +
                    '.receipt-row.b{font-weight:800;}' +
                    '.receipt-row.void{color:#C0392B;font-weight:800;}' +
                    'table.items{width:100%;border-collapse:collapse;table-layout:fixed;}' +
                    'table.items th{font-size:10.5px;font-weight:800;text-align:left;padding:2px 2px;border-bottom:1px dashed #000;}' +
                    'table.items td{font-size:11.5px;padding:2px 2px;vertical-align:top;word-break:break-word;}' +
                    'table.items th.right, table.items td.right{text-align:right;}' +
                    'table.items col.qty{width:14%;} table.items col.desc{width:44%;} table.items col.price{width:21%;} table.items col.total{width:21%;}' +
                    '.total-band{background:#e4e4e4;font-weight:800;font-size:14.5px;padding:5px 4px;margin:4px 0;display:flex;justify-content:space-between;}' +
                    '.void-band{background:#fbe4e1;color:#C0392B;font-weight:800;font-size:13px;padding:5px 4px;margin:4px 0;display:flex;justify-content:space-between;}' +
                    'tr.voided-row td{color:#C0392B;text-decoration:line-through;}' +
                    '.void-tag{font-size:9.5px;font-weight:800;letter-spacing:.04em;text-decoration:none;}' +
                    'h3{font-size:10.5px;letter-spacing:.06em;color:#444;margin:8px 0 3px;}' +
                    '.receipt-footer{text-align:center;margin-top:10px;font-size:11px;}' +
                    '.receipt-footer .bold{font-weight:800;font-size:12px;}' +
                    '@media print{body *{visibility:hidden;}.receipt-container,.receipt-container *{visibility:visible;}' +
                    '.receipt-container{position:absolute;left:0;top:0;width:100%;padding:0;margin:0;}@page{margin:0;}}' +
                    '*{box-sizing:border-box;}body{margin:0;}';
            }

            function receiptEsc(s) {
                return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            }
            // docType e.g. "SHIFT SUMMARY — Z-READ RECEIPT" / "VOID RECEIPT" — omitted on the sale receipt.
            function receiptHeaderHTML(docType) {
                const addressLine = SHOP_ADDRESS ? '<p>' + receiptEsc(SHOP_ADDRESS) + '</p>' : '';
                const tinLine = SHOP_TIN ? '<p>TIN: ' + receiptEsc(SHOP_TIN) + '</p>' : '';
                return '<div class="receipt-header"><h1>' + receiptEsc(SHOP_NAME) + '</h1>' + addressLine + tinLine +
                    (docType ? '<div class="doc-type">' + receiptEsc(docType) + '</div>' : '') + '</div>';
            }

            function receiptFooterHTML(lines) {
                return '<div class="receipt-footer">' + (lines || []).map((l, i) => '<p' + (i === 0 ? ' class="bold"' : '') + '>' + receiptEsc(l) + '</p>').join('') + '</div>';
            }

            function printShiftReceipt(d) {
                const win = window.open('', '_blank', 'width=380,height=650');
                if (!win) {
                    toast('Pop-up blocked — allow pop-ups to print the Z-Read receipt', 'warning');
                    return;
                }
                const label = d.variance < 0 ? 'SHORT' : (d.variance > 0 ? 'OVER' : 'EXACT');
                const varColor = d.variance < 0 ? '#e5484d' : (d.variance > 0 ? '#3ba55c' : '#1A1208');
                const esc = receiptEsc;
                const fmtTime = iso => new Date(iso).toLocaleTimeString('en', {
                    hour: '2-digit',
                    minute: '2-digit'
                });

                const txList = d.transactions || [];
                const topItems = d.top_items || [];
                const voidLogs = d.void_logs || [];
                const voidCount = d.void_count || 0;
                const voidValue = d.void_value || 0;

                const txRows = txList.length ?
                    txList.map(t =>
                        '<div class="receipt-row" style="font-size:10.5px;"><span style="flex:0 0 42px;color:#666;">' + esc(fmtTime(t.created_at)) + '</span>' +
                        '<span style="flex:1;text-align:left;padding-left:4px;">#' + esc(t.order_ref) + '</span>' +
                        '<span>' + fmt(t.total) + '</span></div>'
                    ).join('') :
                    '<p style="text-align:center;font-size:10.5px;color:#777;padding:6px 0;">No transactions this shift</p>';

                const topRows = topItems.length ?
                    topItems.map((it, i) =>
                        '<div class="receipt-row"><span>' + (i + 1) + '. ' + esc(it.product_name) + ' &times;' + it.qty + '</span><span>' + fmt(it.revenue) + '</span></div>'
                    ).join('') :
                    '<p style="text-align:center;font-size:10.5px;color:#777;padding:6px 0;">No items sold this shift</p>';

                // PART 4 — post-sale voids & paybacks section, only shown when there were any this shift
                const voidSection = voidCount > 0 ?
                    '<div class="divider"></div>' +
                    '<h3>POST-SALE VOIDS &amp; PAYBACKS</h3>' +
                    '<div class="receipt-row"><span>Voided Items</span><span>' + voidCount + '</span></div>' +
                    '<div class="void-band"><span>TOTAL CASH PAID BACK</span><span>-' + fmt(voidValue) + '</span></div>' :
                    '';

                const voidAuditRows = voidLogs.length ?
                    voidLogs.map(v =>
                        '<div class="receipt-row"><span>Void #' + v.id + ' — ' + v.qty_voided + '&times; ' + esc(v.product_name) + '</span><span>-' + fmt(v.amount_voided) + '</span></div>' +
                        (v.reason ? '<div style="font-size:9.5px;color:#777;padding:0 0 3px 4px;">(' + esc(v.reason) + ')</div>' : '')
                    ).join('') :
                    '';

                const voidAuditSection = voidLogs.length ?
                    '<div class="divider"></div>' +
                    '<h3>SHIFT VOID AUDIT TRAIL</h3>' +
                    voidAuditRows :
                    '';

                win.document.write(
                    '<!DOCTYPE html><html><head><style>' +
                    receiptBaseCSS() +
                    '.var-row{font-weight:800;color:' + varColor + ';font-size:13px;}' +
                    '</style></head><body>' +
                    '<div class="receipt-container">' +
                    receiptHeaderHTML('SHIFT SUMMARY — Z-READ RECEIPT') +
                    '<div class="divider"></div>' +
                    '<div class="receipt-row"><span>Cashier</span><span>' + esc(d.cashier_name) + '</span></div>' +
                    '<div class="receipt-row"><span>Login Time</span><span>' + esc(fmtDate(d.login_time)) + '</span></div>' +
                    '<div class="receipt-row"><span>Logout Time</span><span>' + esc(fmtDate(d.logout_time)) + '</span></div>' +
                    '<div class="divider"></div>' +
                    '<div class="receipt-row"><span>Opening Float</span><span>' + fmt(d.opening_float) + '</span></div>' +
                    '<div class="receipt-row"><span>Gross Cash Sales</span><span>' + fmt(d.cash_sales) + '</span></div>' +
                    voidSection +
                    '<div class="receipt-row b"><span>Expected Cash in Drawer</span><span>' + fmt(d.expected_cash) + '</span></div>' +
                    '<div class="receipt-row b"><span>Actual Cash Counted</span><span>' + fmt(d.closing_cash) + '</span></div>' +
                    '<div class="divider"></div>' +
                    '<div class="receipt-row var-row"><span>VARIANCE</span><span>' + (d.variance > 0 ? '+' : '') + fmt(d.variance) + ' (' + label + ')</span></div>' +
                    '<div class="divider"></div>' +
                    '<h3>TRANSACTION SUMMARY</h3>' +
                    '<div class="receipt-row"><span>Transactions</span><span>' + (d.transaction_count ?? txList.length) + '</span></div>' +
                    '<div class="receipt-row"><span>Items Sold</span><span>' + (d.items_sold ?? '—') + '</span></div>' +
                    '<div class="divider"></div>' +
                    '<h3>TOP ITEMS THIS SHIFT</h3>' +
                    topRows +
                    '<div class="divider"></div>' +
                    '<h3>TRANSACTION LOG</h3>' +
                    txRows +
                    voidAuditSection +
                    '<div class="divider"></div>' +
                    receiptFooterHTML(['Generated ' + fmtDate(new Date().toISOString()), 'Thank you — session closed.']) +
                    '</div>' +
                    '<script>window.onload=function(){window.print();}<\/script>' +
                    '</body></html>'
                );
                win.document.close();
            }

            // ── IMAGE HELPERS ──
            const fileToB64 = f => new Promise((res, rej) => {
                const r = new FileReader();
                r.onload = e => res(e.target.result);
                r.onerror = () => rej('Read error');
                r.readAsDataURL(f);
            });

            function compressImg(b64, maxW = 480, q = 0.82) {
                return new Promise(res => {
                    const img = new Image();
                    img.onload = () => {
                        const c = document.createElement('canvas');
                        let w = img.width,
                            h = img.height;
                        if (w > maxW) {
                            h = Math.round(h * maxW / w);
                            w = maxW;
                        }
                        c.width = w;
                        c.height = h;
                        c.getContext('2d').drawImage(img, 0, 0, w, h);
                        res(c.toDataURL('image/jpeg', q));
                    };
                    img.src = b64;
                });
            }

            // ── LOADING BUTTON ──
            function setLoading(btn, on) {
                if (!btn) return;
                clearTimeout(btn._slowTimer);
                if (on) {
                    btn.dataset.orig = btn.innerHTML;
                    btn.innerHTML = '<span class="spinner"></span>';
                    btn.disabled = true;
                    // If a save is still going after 6s, say so — a bare spinner with no
                    // change for that long reads as "frozen" on slow/free hosting, which is
                    // exactly what prompted people to tap Save again or give up.
                    btn._slowTimer = setTimeout(() => {
                        if (btn.disabled) btn.innerHTML = '<span class="spinner"></span> <span style="font-size:.72rem;">still working…</span>';
                    }, 6000);
                } else {
                    btn.innerHTML = btn.dataset.orig || btn.innerHTML;
                    btn.disabled = false;
                }
            }

            // ════════════════════════════════
            // IMAGE UPLOAD (used on products page)
            // ════════════════════════════════
            let imgB64 = null;

            function previewImg(e) {
                const file = e.target.files[0];
                if (!file) return;
                fileToB64(file).then(b64 => compressImg(b64)).then(b64 => {
                    imgB64 = b64;
                    const preview = document.getElementById('img-preview');
                    const placeholder = document.getElementById('img-placeholder');
                    const removeBtn = document.getElementById('img-remove-btn');
                    if (preview) {
                        preview.src = b64;
                        preview.style.display = 'block';
                    }
                    if (placeholder) placeholder.style.display = 'none';
                    if (removeBtn) removeBtn.style.display = '';
                }).catch(() => toast('Failed to load image', 'error'));
            }

            function removeImg() {
                imgB64 = null;
                const preview = document.getElementById('img-preview');
                const placeholder = document.getElementById('img-placeholder');
                const removeBtn = document.getElementById('img-remove-btn');
                const gallery = document.getElementById('img-input-gallery');
                const camera = document.getElementById('img-input-camera');
                if (preview) {
                    preview.src = '';
                    preview.style.display = 'none';
                }
                if (placeholder) placeholder.style.display = 'block';
                if (removeBtn) removeBtn.style.display = 'none';
                if (gallery) gallery.value = '';
                if (camera) camera.value = '';
            }

            // ════════════════════════════════
            // DASHBOARD
            // ════════════════════════════════
            let cart = [],
                allProds = [],
                allCats = [],
                activeCat = 'All';
            // Keyboard-nav: index of the cart row currently highlighted via ↑/↓.
            let focusedCartIdx = -1;
            // Held Carts: transactions parked mid-sale so the cashier can start a fresh
            // one and come back later. Kept in memory only (cleared on page reload) —
            // there's no backend table for this since a shift's held carts are meant to
            // be resolved before close-out anyway.
            let heldCarts = [];

            // ══════════════════════════════════════════════════════════════════
            // OFFLINE / POWER-LOSS RESILIENCE
            // Two separate protections:
            //  1. CART AUTOSAVE — the in-progress cart + cash tendered is mirrored to
            //     localStorage on every change (see updateCartUI/calcChange above). If
            //     the PC loses power or the tab closes mid-sale, reopening the Cashier
            //     page offers to restore exactly what was there.
            //  2. PENDING SALE QUEUE — if "Process Payment" is clicked while offline (or
            //     the request to the server fails to reach it at all), the sale is NOT
            //     lost or blocked: it's saved locally, the receipt still prints with a
            //     clearly-marked local reference, and it auto-syncs to the server the
            //     moment connectivity returns (via the browser's 'online' event, a
            //     periodic retry timer, and a check on every page load).
            // ══════════════════════════════════════════════════════════════════
            const CART_AUTOSAVE_KEY = 'pangga_cart_autosave_v1';
            const PENDING_SALES_KEY = 'pangga_pending_sales_v1';

            // A connectivity failure can surface two different ways here:
            //  - apiPost/apiGet return null (fetch itself threw — no service worker,
            //    or the request wasn't intercepted).
            //  - the inline service worker (see bottom of file) intercepts 'action='
            //    requests while offline and resolves them with a normal 200 response
            //    body of {success:false,error:'Offline'} instead of letting fetch
            //    reject — so a plain `!r.success` check alone would misread this as a
            //    real server-side rejection instead of "can't reach the server".
            function isOfflineResult(r) {
                return r === null || (r && r.success === false && r.error === 'Offline');
            }

            function saveCartAutosave() {
                try {
                    const cashVal = document.getElementById('cash-input')?.value || '';
                    if (!cart.length) {
                        localStorage.removeItem(CART_AUTOSAVE_KEY);
                        return;
                    }
                    localStorage.setItem(CART_AUTOSAVE_KEY, JSON.stringify({
                        cart,
                        cash: cashVal,
                        savedAt: Date.now()
                    }));
                } catch (e) {
                    /* localStorage unavailable/full — autosave is best-effort, never blocks the sale */ }
            }

            function clearCartAutosave() {
                try {
                    localStorage.removeItem(CART_AUTOSAVE_KEY);
                } catch (e) {}
            }

            // Called once from dashInit(). If a previous session left an unfinished
            // cart behind (crash, power loss, accidental tab close), offer to bring it
            // back instead of silently discarding it.
            function restoreCartIfAny() {
                let saved = null;
                try {
                    saved = JSON.parse(localStorage.getItem(CART_AUTOSAVE_KEY) || 'null');
                } catch (e) {
                    saved = null;
                }
                if (!saved || !Array.isArray(saved.cart) || !saved.cart.length) return;
                if (cart.length) return; // don't clobber a cart already in progress this session

                const ageMin = Math.round((Date.now() - (saved.savedAt || 0)) / 60000);
                const ok = confirm(
                    '🔌 An unfinished sale was found (from ' + (ageMin <= 1 ? 'less than a minute ago' : ageMin + ' minute(s) ago') + '), ' +
                    'likely left over from a power loss, crash, or closed tab.\n\n' +
                    'Restore it (' + saved.cart.length + ' item line(s)) and continue the sale?'
                );
                if (!ok) {
                    clearCartAutosave();
                    return;
                }
                cart = saved.cart;
                updateCartUI();
                renderGrid();
                const cashInp = document.getElementById('cash-input');
                if (cashInp && saved.cash) {
                    cashInp.value = saved.cash;
                    calcChange();
                }
                openModal('cart-modal');
                toast('🔌 Previous cart restored', 'success');
            }

            function pendingSalesList() {
                try {
                    return JSON.parse(localStorage.getItem(PENDING_SALES_KEY) || '[]');
                } catch (e) {
                    return [];
                }
            }

            function savePendingSalesList(list) {
                try {
                    localStorage.setItem(PENDING_SALES_KEY, JSON.stringify(list));
                } catch (e) {}
            }

            // Queues a completed sale locally when the server can't be reached right
            // now (offline / mid power-blip). Returns the local pending reference used
            // on the receipt in the meantime — e.g. "PEND-8F3K2A".
            function queuePendingSale(payload) {
                const localRef = 'PEND-' + Date.now().toString(36).toUpperCase().slice(-6) + Math.random().toString(36).slice(2, 4).toUpperCase();
                const list = pendingSalesList();
                list.push({
                    localRef,
                    payload,
                    createdAt: Date.now()
                });
                savePendingSalesList(list);
                renderPendingSyncBadge();
                return localRef;
            }

            // Retries every queued offline sale against the server. Safe to call
            // repeatedly/aggressively — each entry is only removed from the queue once
            // the server confirms it was actually recorded, so a sale can never be lost
            // even if this fires several times back-to-back (e.g. 'online' event AND
            // the periodic timer both firing around the same moment).
            let _flushingPendingSales = false;
            async function flushPendingSales() {
                if (_flushingPendingSales) return;
                const list = pendingSalesList();
                if (!list.length) {
                    renderPendingSyncBadge();
                    return;
                }
                if (navigator.onLine === false) {
                    renderPendingSyncBadge();
                    return;
                }
                _flushingPendingSales = true;
                let syncedCount = 0;
                const remaining = [];
                for (const entry of list) {
                    const r = await apiPost('add_transaction', entry.payload);
                    if (r?.success) {
                        syncedCount++;
                    } else if (isOfflineResult(r)) {
                        // Still can't reach the server — keep this and every entry after it
                        // queued, and stop trying for now rather than hammering repeatedly.
                        remaining.push(entry);
                        const idx = list.indexOf(entry);
                        remaining.push(...list.slice(idx + 1));
                        break;
                    } else {
                        // Server reachable but rejected it (e.g. stock validation) — surface
                        // it instead of retrying forever on a sale that will never succeed.
                        toast('⚠️ Offline sale ' + entry.localRef + ' failed to sync: ' + (r?.error || 'unknown error') + ' — please review manually', 'error');
                    }
                }
                savePendingSalesList(remaining);
                _flushingPendingSales = false;
                renderPendingSyncBadge();
                if (syncedCount > 0) {
                    toast('✅ Synced ' + syncedCount + ' offline sale(s) to the server', 'success');
                    loadStats();
                    loadAllProds();
                    loadTopSellers();
                }
            }

            // Small persistent badge (auto-injected, no HTML markup needed) showing how
            // many sales are still waiting to sync — tap it to retry immediately.
            function renderPendingSyncBadge() {
                const list = pendingSalesList();
                let badge = document.getElementById('pending-sync-badge');
                if (!list.length) {
                    if (badge) badge.remove();
                    return;
                }
                if (!badge) {
                    badge = document.createElement('div');
                    badge.id = 'pending-sync-badge';
                    badge.style.cssText = 'position:fixed;bottom:90px;right:20px;z-index:500;background:#e67e22;color:#fff;font-weight:700;font-size:.82rem;padding:10px 16px;border-radius:99px;box-shadow:var(--shadow-lg);cursor:pointer;display:flex;align-items:center;gap:8px;';
                    badge.onclick = () => {
                        toast('Retrying sync…', 'default');
                        flushPendingSales();
                    };
                    document.body.appendChild(badge);
                }
                badge.innerHTML = '⏳ ' + list.length + ' sale(s) pending sync — tap to retry';
            }

            // Retry whenever the browser regains connectivity, plus a periodic sweep
            // every 20s in case the 'online' event doesn't fire reliably on this
            // device, and once immediately on page load in case sales were queued
            // during a previous, now-closed session.
            window.addEventListener('online', flushPendingSales);
            setInterval(flushPendingSales, 20000);



            function dashInit() {
                if (cur_page !== 'dashboard') return;
                const h = new Date().getHours();
                document.getElementById('greet').textContent = h < 12 ? 'Morning' : h < 17 ? 'Afternoon' : 'Evening';
                apiGet('get_settings').then(s => {
                    CUR = s?.data?.currency || '₱';
                    VAT_RATE = Math.max(0, parseFloat(s?.data?.vat_rate || 0));
                    TAX_RATE = Math.max(0, parseFloat(s?.data?.tax_rate || 0));
                    document.getElementById('shop-name').textContent = s?.data?.shop_name || 'Welcome to PANGGA STORE';
                    updateCartUI();
                });
                loadStats();
                loadAllProds();
                loadTopSellers();
                if (USER_ROLE !== 'staff') loadAIHighlights();
                // Offline/power-loss protections: offer to restore any cart left over
                // from a crash/power loss, and try syncing any sales that were queued
                // locally while the server was unreachable.
                restoreCartIfAny();
                renderPendingSyncBadge();
                flushPendingSales();
            }

            // Lightweight preview pull for the dashboard highlight cards —
            // reuses the same endpoints as the Forecast page but only reads
            // counts, so it stays fast even on a slow connection.
            function loadAIHighlights() {
                apiGet('get_all_forecasts', {
                    period: 'daily'
                }).then(r => {
                    const cntEl = document.getElementById('dash-fc-count');
                    const rstEl = document.getElementById('dash-fc-restock');
                    if (!r?.success) {
                        if (cntEl) cntEl.textContent = '—';
                        if (rstEl) rstEl.textContent = '—';
                        return;
                    }
                    const forecasts = r.data.forecasts || [];
                    const needRestock = forecasts.filter(f => (f.restock_suggest || 0) > 0).length;
                    if (cntEl) cntEl.textContent = forecasts.length;
                    if (rstEl) rstEl.textContent = needRestock;
                });
                apiGet('get_combo_recommendations', {
                    limit: 10
                }).then(r => {
                    const cEl = document.getElementById('dash-combo-count');
                    if (!r?.success) {
                        if (cEl) cEl.textContent = '—';
                        return;
                    }
                    const combos = (r.data.combos && r.data.combos.length) ? r.data.combos : (r.data.recommendations || []);
                    if (cEl) cEl.textContent = combos.length;
                });
            }

            // Which window the Revenue/Profit cards show — 'week' (7-day) to match
            // the dashboard's long-standing default, switchable to Today/30-Day/All
            // (All replaces what used to be a separate fixed "All-Time Revenue"
            // card). Both cards always read the SAME period so they describe one
            // window, and both render their own copy of the same toggle buttons —
            // clicking either copy moves both cards together.
            let dashStatsData = null;
            let dashPeriod = 'week';
            const DASH_PERIODS = [
                ['today', 'Today'],
                ['week', '7D'],
                ['month', '30D'],
                ['all', 'All']
            ];

            function renderDashPeriodButtons() {
                // Reuses the exact same .period-btn / .period-btn.active classes as
                // the Daily/Weekly/Monthly toggle on Sales History — light pill when
                // inactive, solid accent-blue pill when active — just sized down to
                // fit a compact stat-card header instead of a full toolbar.
                const html = DASH_PERIODS.map(([val, label]) =>
                    '<button type="button" class="btn period-btn' + (val === dashPeriod ? ' active' : '') + '" ' +
                    'onclick="setDashPeriod(\'' + val + '\')" ' +
                    'style="font-size:.62rem;padding:3px 8px;">' + label + '</button>'
                ).join('');
                document.querySelectorAll('.stat-period-group').forEach(g => g.innerHTML = html);
            }

            function setDashPeriod(period) {
                dashPeriod = period;
                renderDashPeriodButtons();
                renderPeriodStats();
            }

            function renderPeriodStats() {
                if (!dashStatsData) return;
                const d = dashStatsData;
                const revKey = { today: 'today_revenue', week: 'week_revenue', month: 'month_revenue', all: 'total_revenue' }[dashPeriod];
                const profitKey = { today: 'today_profit', week: 'week_profit', month: 'month_profit', all: 'total_profit' }[dashPeriod];
                const txKey = { today: 'today_sales', week: 'week_sales', month: 'month_sales', all: 'total_tx' }[dashPeriod];
                const label = { today: "today's", week: '7-day', month: '30-day', all: 'all-time' }[dashPeriod];
                document.getElementById('s-week').textContent = fmt(d[revKey]);
                document.getElementById('s-week-label').textContent = label + ' revenue · ' + (d[txKey] || 0) + ' orders';
                document.getElementById('s-profit').textContent = fmt(d[profitKey]);
                document.getElementById('s-profit-label').textContent = label + ' profit';
            }

            function loadStats() {
                apiGet('get_stats').then(r => {
                    // Previously a silent return here — if this call ever failed, every
                    // dashboard card just sat on its "—" placeholder forever with no
                    // indication anything was wrong. Now it says so, so a real backend
                    // issue is visible instead of looking like the app is just slow.
                    if (!r?.success) {
                        toast(r?.error ? ('⚠️ Dashboard stats: ' + r.error) : '⚠️ Could not load dashboard stats', 'error');
                        return;
                    }
                    const d = r.data;
                    dashStatsData = d;
                    document.getElementById('s-today-rev').textContent = fmt(d.today_revenue);
                    document.getElementById('s-today-cnt').textContent = d.today_sales + ' transactions';
                    document.getElementById('s-prods').textContent = d.product_count;
                    document.getElementById('s-lowstock').textContent = d.low_stock + ' low stock';
                    renderDashPeriodButtons();
                    renderPeriodStats();
                });
            }

            function loadAllProds() {
                Promise.all([apiGet('get_products'), apiGet('get_categories')]).then(([pr, cr]) => {
                    if (pr?.success) allProds = pr.data;
                    if (cr?.success) allCats = cr.data;
                    renderCatPills();
                    renderGrid();
                });
            }

            function filterProds() {
                renderGrid();
            }

            function renderCatPills() {
                const el = document.getElementById('cat-pills');
                if (!el) return;
                const cats = ['All', ...allCats.map(c => c.name)];
                el.innerHTML = cats.map(c =>
                    '<button class="cat-pill ' + (c === activeCat ? 'active' : '') + '" onclick="setActiveCat(\'' + c + '\')">' + c + '</button>'
                ).join('');
            }

            function setActiveCat(c) {
                activeCat = c;
                renderCatPills();
                renderGrid();
            }

            // Resolves whether a product currently has an active promo/discount price —
            // valid only when promo_price is a positive number strictly lower than the
            // regular price. Used by the Sales grid, Products grid, Cart, and Receipt so
            // they all agree on what counts as "on promo".
            function getPromoInfo(p) {
                const price = parseFloat(p.price) || 0;
                const promo = (p.promo_price !== null && p.promo_price !== undefined && p.promo_price !== '') ? parseFloat(p.promo_price) : null;
                const active = promo !== null && !isNaN(promo) && promo > 0 && promo < price;
                return {
                    active,
                    price,
                    promo: active ? promo : null
                };
            }

            function renderGrid() {
                const q = (document.getElementById('search-inp')?.value || '').toLowerCase();
                const prods = allProds.filter(p => {
                    const mc = activeCat === 'All' || p.category_name === activeCat;
                    const mq = !q || p.name.toLowerCase().includes(q) || (p.category_name || '').toLowerCase().includes(q);
                    return mc && mq;
                });
                const grid = document.getElementById('prods-grid');
                if (!grid) return;
                if (!prods.length) {
                    grid.innerHTML = '<div style="grid-column:1/-1"><div class="empty-state"><div class="empty-icon">🍽️</div><div class="empty-text">No products found</div></div></div>';
                    return;
                }
                grid.innerHTML = prods.map(p => {
                    const inCart = cart.find(c => c.product_id === p.id);
                    const isOut = p.quantity == 0;
                    const isLow = p.quantity > 0 && p.quantity <= (p.low_stock_threshold ?? 5);
                    const promoInfo = getPromoInfo(p);
                    const img = p.has_image == 1 ?
                        '<img src="' + prodImgUrl(p.id, p.updated_at) + '" class="product-card-img" loading="lazy" data-fallback="div" onerror="imgFallback(this)"/>' :
                        '<div class="product-card-ph"><img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt=""></div>';
                    const clickHandler = isOut ? '' : 'onclick="addToCart(' + p.id + ')"';
                    const priceHTML = promoInfo.active ?
                        '<span class="promo-strike">' + fmt(promoInfo.price) + '</span><span class="promo-now">' + fmt(promoInfo.promo) + '</span>' :
                        fmt(p.price);
                    // Add-Product description snippet, shown right on the tile — kept as
                    // a second, smaller meta line. (The Brand/Supplier/Size/SKU line that
                    // used to sit here was removed per request — too cluttered on the
                    // Dashboard's compact tiles; that full detail set still lives in Cart
                    // and the Sales History "View" modal.)
                    const descLine = p.description ?
                        '<div class="product-card-meta" style="opacity:.7;font-style:italic;">' + escapeHtml(p.description.length > 60 ? p.description.slice(0, 60) + '…' : p.description) + '</div>' : '';
                    return '<div class="product-card" ' + clickHandler + (isOut ? ' style="opacity:.55;cursor:not-allowed;"' : '') + '>' +
                        img +
                        (isLow && !isOut ? '<span class="low-badge">Low</span>' : '') +
                        (isOut ? '<span class="low-badge">Out</span>' : '') +
                        (promoInfo.active && !isOut ? '<span class="sale-badge">🏷️ SALE</span>' : '') +
                        (inCart ? '<span class="qty-badge">' + inCart.qty + '</span>' : '') +
                        '<div class="product-card-body">' +
                        '<div class="product-card-name">' + p.name + '</div>' +
                        '<div class="product-card-price">' + priceHTML + '</div>' +
                        '<div class="product-card-meta">' + (p.category_name || 'Uncategorized') + ' · Stock: ' + p.quantity + '</div>' +
                        descLine +
                        '</div></div>';
                }).join('');
            }

            function loadTopSellers() {
                apiGet('get_top_products', {
                    limit: 8
                }).then(r => {
                    if (!r?.success) return;
                    const tops = r.data;
                    const el = document.getElementById('top-sellers');
                    if (!el) return;
                    if (!tops.length) {
                        el.innerHTML = '<div style="text-align:center;padding:16px;color:var(--text3);font-size:.83rem;">No sales yet</div>';
                        return;
                    }
                    el.innerHTML = tops.map((p, i) => {
                        const rc = i === 0 ? 'gold' : i === 1 ? 'silver' : i === 2 ? 'bronze' : '';
                        const imgEl = p.has_image ? '<img src="' + prodImgUrl(p.id, p.updated_at) + '" loading="lazy" style="width:100%;height:100%;object-fit:cover;" onerror="imgFallback(this)"/>' : '<img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt="">';
                        return '<div class="top-row">' +
                            '<div class="top-rank ' + rc + '">' + (i + 1) + '</div>' +
                            '<div class="top-img">' + imgEl + '</div>' +
                            '<div class="top-info"><div class="top-name">' + p.name + '</div><div class="top-sales">' + p.total_sold + ' sold</div></div>' +
                            '<div class="top-rev">' + fmt(p.total_revenue) + '</div>' +
                            '</div>';
                    }).join('');
                });
            }

            // ── CART FUNCTIONS ──
            // ── SMART BUNDLE/CASE-AWARE SALE PRICING ──
            // When a product has a Case and/or Bundle configured (Multi-Unit Configuration
            // in Add Product), selling more pieces than one of those thresholds should
            // price the covered portion at the Case/Bundle rate and only the leftover at
            // the piece rate — e.g. Bundle = 12 pcs @ ₱1,000; buyer takes 13 pcs → 1
            // bundle (₱1,000) + 1 loose piece at the piece price, not 13x piece price.
            // Greedy breakdown, largest unit first: Case, then Bundle, then Piece.
            function computeUnitBreakdown(item) {
                const price = +item.price || 0;
                const qty = +item.qty || 0;
                const caseQty = +item.case_qty || 0;
                const casePrice = +item.case_price || 0;
                const packQty = +item.pack_qty || 0;
                const packPrice = +item.pack_price || 0;

                let remaining = qty;
                let subtotal = 0;
                const parts = [];

                if (caseQty > 0 && casePrice > 0) {
                    const cases = Math.floor(remaining / caseQty);
                    if (cases > 0) {
                        subtotal += cases * casePrice;
                        remaining -= cases * caseQty;
                        parts.push({
                            unit: 'case',
                            count: cases
                        });
                    }
                }
                if (packQty > 0 && packPrice > 0) {
                    const bundles = Math.floor(remaining / packQty);
                    if (bundles > 0) {
                        subtotal += bundles * packPrice;
                        remaining -= bundles * packQty;
                        parts.push({
                            unit: 'bundle',
                            count: bundles
                        });
                    }
                }
                if (remaining > 0) {
                    subtotal += remaining * price;
                    parts.push({
                        unit: 'piece',
                        count: remaining
                    });
                }

                const breakdownText = parts.length > 1 ?
                    parts.map(p => p.count + ' ' + (p.unit === 'piece' ? ('pc' + (p.count !== 1 ? 's' : '')) : (p.unit + (p.count !== 1 ? 's' : '')))).join(' + ') :
                    '';
                return {
                    subtotal,
                    parts,
                    breakdownText
                };
            }

            // A barcode lookup that matched a product's Bundle or Case barcode (instead
            // of its base Piece barcode) returns matched_unit='pack'/'case'. Scanning
            // that barcode should add the whole bundle/case worth of pieces at once.
            function scanUnitQty(p) {
                if (p?.matched_unit === 'case' && p.case_qty) return parseInt(p.case_qty) || 1;
                if (p?.matched_unit === 'pack' && p.pack_qty) return parseInt(p.pack_qty) || 1;
                return 1;
            }

            function addToCart(pid, qtyOverride) {
                const p = allProds.find(x => x.id == pid);
                if (!p || p.quantity <= 0) {
                    toast('Out of stock!', 'error');
                    return;
                }
                const addQty = Math.max(1, parseInt(qtyOverride) || 1);
                const ex = cart.find(c => c.product_id === pid);
                if (ex) {
                    if (ex.qty + addQty > p.quantity) {
                        toast('Not enough stock!', 'warning');
                        return;
                    }
                    ex.qty += addQty;
                } else {
                    if (addQty > p.quantity) {
                        toast('Not enough stock!', 'warning');
                        return;
                    }
                    // Price chain per line item:
                    //   regular_price  → the shelf/catalog price, always kept as reference
                    //   catalog_price  → regular_price, or the catalog Promo Price if one is active
                    //   price          → what's actually charged (starts equal to catalog_price;
                    //                     a cashier-applied manual_discount, added later in the
                    //                     Cart via the 🏷️ button, can markdown it further for
                    //                     this sale only — it never touches the stored product)
                    const promoInfo = getPromoInfo(p);
                    const catalogPrice = promoInfo.active ? promoInfo.promo : parseFloat(p.price);
                    // Bundle/Case tiers each resolve their own promo independently, same rule
                    // as the piece tier: only active when promo < regular and > 0.
                    const packRegular = p.pack_price ? parseFloat(p.pack_price) : 0;
                    const packPromo = (p.promo_pack_price !== null && p.promo_pack_price !== undefined && p.promo_pack_price !== '') ? parseFloat(p.promo_pack_price) : null;
                    const packPromoActive = packPromo !== null && !isNaN(packPromo) && packPromo > 0 && packRegular > 0 && packPromo < packRegular;
                    const caseRegular = p.case_price ? parseFloat(p.case_price) : 0;
                    const casePromo = (p.promo_case_price !== null && p.promo_case_price !== undefined && p.promo_case_price !== '') ? parseFloat(p.promo_case_price) : null;
                    const casePromoActive = casePromo !== null && !isNaN(casePromo) && casePromo > 0 && caseRegular > 0 && casePromo < caseRegular;
                    cart.push({
                        product_id: pid,
                        name: p.name,
                        price: catalogPrice,
                        qty: addQty,
                        is_promo: promoInfo.active,
                        regular_price: parseFloat(p.price),
                        catalog_price: catalogPrice,
                        manual_discount: null,
                        has_image: p.has_image == 1,
                        img_v: p.updated_at || '',
                        category_name: p.category_name || '',
                        description: p.description || '',
                        barcode: p.barcode || '',
                        brand: p.brand || '',
                        supplier: p.supplier || '',
                        unit_type: p.unit_type || '',
                        unit_size: p.unit_size || '',
                        pack_qty: p.pack_qty ? parseInt(p.pack_qty) : 0,
                        pack_price: packPromoActive ? packPromo : packRegular,
                        pack_regular_price: packRegular,
                        is_pack_promo: packPromoActive,
                        case_qty: p.case_qty ? parseInt(p.case_qty) : 0,
                        case_price: casePromoActive ? casePromo : caseRegular,
                        case_regular_price: caseRegular,
                        is_case_promo: casePromoActive
                    });
                }
                toast(p.name + (addQty > 1 ? ' ×' + addQty : '') + ' added', 'success');
                updateCartUI();
                renderGrid();
            }

            function removeFromCart(pid) {
                cart = cart.filter(c => c.product_id !== pid);
                updateCartUI();
                renderGrid();
            }

            function changeQty(pid, d) {
                const item = cart.find(c => c.product_id === pid);
                const prod = allProds.find(p => p.id == pid);
                if (!item) return;
                item.qty = Math.max(1, Math.min(item.qty + d, prod?.quantity || 999));
                updateCartUI();
                renderGrid();
                // Keep keyboard focus (and the highlighted-row outline) on this same row's
                // qty box after the ± click, so Left/Right arrow-key stepping still works
                // immediately afterward without re-selecting the row.
                focusCartQtyInput(pid);
            }

            // Called when a cart row's qty <input> is edited directly — either by typing
            // (keyboard nav "type a number to set qty") or by the browser's native number
            // spinner. Clamps to available stock and re-renders.
            function setQtyDirect(pid, val) {
                const item = cart.find(c => c.product_id === pid);
                const prod = allProds.find(p => p.id == pid);
                if (!item) return;
                let n = parseInt(val);
                if (isNaN(n) || n < 1) n = 1;
                const max = prod?.quantity || 999;
                if (n > max) {
                    n = max;
                    toast('Only ' + max + ' in stock', 'warning');
                }
                item.qty = n;
                updateCartUI();
                renderGrid();
                focusCartQtyInput(pid);
            }

            function focusCartQtyInput(pid) {
                const inp = document.getElementById('cart-qty-' + pid);
                if (inp) {
                    inp.focus();
                    inp.select();
                }
            }

            // Resolves what the cart line's "PRICE" column should show. Previously this
            // always showed the plain piece price (item.price), even when the qty sold
            // entirely at the Bundle or Case rate — e.g. a product with Bundle = 12 pcs
            // @₱1,000 sold at qty 12 would show "₱1,000 ÷ 12 = ₱83.33/pc" worth of
            // pieces but the column displayed the raw piece price instead, which didn't
            // match what was actually charged. Now: single-tier sales show that tier's
            // real unit price with a small "/bundle" or "/case" tag; mixed-tier sales
            // (see the bulk breakdown card below the row) show the piece price with a
            // "mixed" tag since one column can't show two different tier prices at once.
            function cartPriceColHTML(item, bd) {
                // Piece tier: strike through the regular price whenever the charged price
                // is lower than it — whether that's from a catalog Promo, a cashier's
                // manual Discount, or both stacked together.
                const pieceStrike = (item.regular_price && item.price < item.regular_price && bd.parts.length === 1 && bd.parts[0].unit === 'piece') ?
                    '<div style="font-size:.65rem;color:var(--text3);text-decoration:line-through;">' + fmt(item.regular_price) + '</div>' :
                    '';
                if (bd.parts.length === 1 && bd.parts[0].unit !== 'piece') {
                    const p = bd.parts[0];
                    const isCase = p.unit === 'case';
                    const unitPrice = isCase ? item.case_price : item.pack_price;
                    const regular = isCase ? item.case_regular_price : item.pack_regular_price;
                    const tierPromo = isCase ? item.is_case_promo : item.is_pack_promo;
                    const strike = (tierPromo && regular) ? '<div style="font-size:.62rem;color:var(--text3);text-decoration:line-through;">' + fmt(regular) + '</div>' : '';
                    return strike + fmt(unitPrice) + '<div style="font-size:.65rem;color:var(--text3);">/' + p.unit + '</div>';
                }
                if (bd.parts.length > 1) {
                    return fmt(item.price) + '<div style="font-size:.65rem;color:var(--text3);">mixed</div>';
                }
                return pieceStrike + fmt(item.price);
            }

            // ── CART LINE DISCOUNT (ad-hoc, cashier-applied) ──
            // For a product nobody set a Promo Price on ahead of time (e.g. it turns out
            // to expire tomorrow), the cashier/admin can mark it down right here in the
            // Cart for this sale only. This never edits the stored product — it just
            // adjusts item.price for this one line, on top of whatever price was
            // already showing (regular or catalog-promo).
            let cartDiscountTargetId = null;
            let cartDiscountType = 'percent';

            // productId is optional: when set (clicked from a specific cart line's 🏷️
            // button) that product is preselected; when omitted (clicked from the "Give
            // a Discount on a Product" button that appears once Cash Tendered is
            // entered) the cashier picks the product from the dropdown themselves.
            function openCartDiscountModal(productId) {
                if (!cart.length) {
                    toast('Cart is empty', 'warning');
                    return;
                }
                const select = document.getElementById('cd-product-select');
                if (select) {
                    select.innerHTML = cart.map(c =>
                        '<option value="' + c.product_id + '">' + escapeHtml(c.name) + ' (' + c.qty + ' pc' + (c.qty !== 1 ? 's' : '') + ' @ ' + fmt(c.price) + ')' + (c.manual_discount ? ' — Discounted' : '') + '</option>'
                    ).join('');
                    select.value = (productId != null && cart.some(c => c.product_id === productId)) ? productId : cart[0].product_id;
                }
                cartDiscountTargetId = select ? parseInt(select.value) : (productId ?? cart[0].product_id);
                loadCartDiscountFieldsForTarget();
                openModal('cart-discount-modal');
            }

            function onCartDiscountProductChange() {
                const select = document.getElementById('cd-product-select');
                if (!select) return;
                cartDiscountTargetId = parseInt(select.value);
                loadCartDiscountFieldsForTarget();
            }

            function loadCartDiscountFieldsForTarget() {
                const item = cart.find(c => c.product_id === cartDiscountTargetId);
                if (!item) return;
                document.getElementById('cd-current-price').textContent = fmt(item.price);
                const removeBtn = document.getElementById('cd-remove-btn');
                if (item.manual_discount) {
                    cartDiscountType = item.manual_discount.type;
                    document.getElementById('cd-value').value = item.manual_discount.value;
                    document.getElementById('cd-reason').value = item.manual_discount.reason || '';
                    if (removeBtn) removeBtn.style.display = '';
                } else {
                    cartDiscountType = 'percent';
                    document.getElementById('cd-value').value = '';
                    document.getElementById('cd-reason').value = '';
                    if (removeBtn) removeBtn.style.display = 'none';
                }
                setCartDiscountType(cartDiscountType);
            }

            function setCartDiscountType(type) {
                cartDiscountType = type;
                const pctBtn = document.getElementById('cd-type-percent');
                const amtBtn = document.getElementById('cd-type-amount');
                const label = document.getElementById('cd-value-label');
                if (pctBtn) pctBtn.className = 'btn btn-sm ' + (type === 'percent' ? 'btn-primary' : 'btn-secondary');
                if (amtBtn) amtBtn.className = 'btn btn-sm ' + (type === 'amount' ? 'btn-primary' : 'btn-secondary');
                if (label) label.textContent = type === 'percent' ? 'Percent Off (%)' : 'Amount Off (₱)';
                updateCartDiscountPreview();
            }

            // Discounts stack from whatever price the line is *currently* charging
            // (item.catalog_price — the regular price, or a catalog Promo price if one
            // was already active) rather than from item.price, so re-opening this modal
            // to edit a discount doesn't compound on top of the previous discount.
            function updateCartDiscountPreview() {
                const preview = document.getElementById('cd-preview');
                if (!preview || cartDiscountTargetId === null) return;
                const item = cart.find(c => c.product_id === cartDiscountTargetId);
                if (!item) return;
                const base = item.catalog_price ?? item.regular_price ?? item.price;
                const val = parseFloat(document.getElementById('cd-value')?.value);
                if (isNaN(val) || val <= 0) {
                    preview.textContent = 'Enter a discount amount to see the new price.';
                    return;
                }
                let newPrice = cartDiscountType === 'percent' ? base * (1 - val / 100) : base - val;
                newPrice = Math.max(0, Math.round(newPrice * 100) / 100);
                if (newPrice >= base) {
                    preview.innerHTML = '<span style="color:var(--danger);">⚠️ That doesn\'t lower the price below ' + fmt(base) + '.</span>';
                    return;
                }
                preview.innerHTML = 'New price: <strong style="color:#e74c3c;">' + fmt(newPrice) + '</strong> <span style="color:var(--text3);text-decoration:line-through;">' + fmt(base) + '</span> / piece';
            }

            function applyCartDiscount() {
                if (cartDiscountTargetId === null) return;
                const item = cart.find(c => c.product_id === cartDiscountTargetId);
                if (!item) return;
                const val = parseFloat(document.getElementById('cd-value')?.value);
                if (isNaN(val) || val <= 0) {
                    toast('Enter a valid discount amount', 'error');
                    return;
                }
                const base = item.catalog_price ?? item.regular_price ?? item.price;
                let newPrice = cartDiscountType === 'percent' ? base * (1 - val / 100) : base - val;
                newPrice = Math.max(0, Math.round(newPrice * 100) / 100);
                if (newPrice >= base) {
                    toast('Discount must lower the price', 'error');
                    return;
                }
                const reason = document.getElementById('cd-reason')?.value.trim() || '';
                item.manual_discount = {
                    type: cartDiscountType,
                    value: val,
                    reason
                };
                item.price = newPrice;
                closeModal('cart-discount-modal');
                updateCartUI();
                toast('Discount applied to ' + item.name, 'success');
            }

            function removeCartDiscount() {
                if (cartDiscountTargetId === null) return;
                const item = cart.find(c => c.product_id === cartDiscountTargetId);
                if (!item) return;
                item.manual_discount = null;
                item.price = item.catalog_price ?? item.regular_price;
                closeModal('cart-discount-modal');
                updateCartUI();
                toast('Discount removed', 'success');
            }

            function clearCart() {
                cart = [];
                updateCartUI();
                renderGrid();
            }

            function setCash(v) {
                document.getElementById('cash-input').value = v;
                calcChange();
            }

            function updateCartUI() {
                // ── CART AUTOSAVE (crash/power-loss protection) ──
                // Persisted on every cart change, not just at checkout, so if the PC loses
                // power or the browser closes mid-sale, reopening the Cashier page can
                // restore exactly what was in the cart instead of losing it. See
                // restoreCartIfAny() (called from dashInit) for the recovery prompt.
                saveCartAutosave();

                const totals = cartTotals();
                const total = totals.total;
                const count = cart.reduce((s, c) => s + c.qty, 0);

                const badge = document.getElementById('cart-badge');
                const fabCnt = document.getElementById('cart-fab-cnt');
                const emptyEl = document.getElementById('cart-empty');
                const summaryEl = document.getElementById('cart-summary');
                const itemsEl = document.getElementById('cart-items');
                const colHeaderEl = document.getElementById('cart-col-header');

                if (badge) badge.textContent = count;
                if (fabCnt) fabCnt.textContent = count;
                if (emptyEl) emptyEl.style.display = cart.length ? 'none' : 'block';
                if (summaryEl) summaryEl.style.display = cart.length ? 'block' : 'none';
                if (colHeaderEl) colHeaderEl.style.display = cart.length ? 'grid' : 'none';

                if (itemsEl) {
                    itemsEl.innerHTML = cart.map((item, idx) => {
                        const bd = computeUnitBreakdown(item);
                        const imgEl = item.has_image ?
                            '<img class="cart-line-img" src="' + prodImgUrl(item.product_id, item.img_v) + '" data-fallback="cart" onerror="imgFallback(this)"/>' :
                            '<div class="cart-line-img"><img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt=""></div>';

                        // Meta line: Category, a short description snippet, and the active barcode.
                        const metaParts = [];
                        if (item.manual_discount) {
                            const md = item.manual_discount;
                            const tagLabel = md.type === 'percent' ? md.value + '% OFF' : fmt(md.value) + ' OFF';
                            metaParts.push('<span style="color:#e74c3c;font-weight:700;">🏷️ DISCOUNT (' + tagLabel + ')' + (md.reason ? ' — ' + escapeHtml(md.reason) : '') + '</span>');
                        } else if (item.is_promo) {
                            metaParts.push('<span style="color:#e74c3c;font-weight:700;">🏷️ PROMO</span>');
                        }
                        if (item.category_name) metaParts.push('Category: ' + escapeHtml(item.category_name));
                        if (item.brand) metaParts.push('Brand: ' + escapeHtml(item.brand));
                        if (item.supplier) metaParts.push('Supplier: ' + escapeHtml(item.supplier));
                        if (item.unit_type) metaParts.push('Size: ' + escapeHtml(formatUnitSizeLabel(item.unit_type, item.unit_size)));
                        if (item.description) metaParts.push(escapeHtml(item.description.length > 42 ? item.description.slice(0, 42) + '…' : item.description));
                        if (item.barcode) metaParts.push('SKU: ' + escapeHtml(item.barcode));
                        const metaLine = metaParts.length ? '<div class="cart-line-meta">' + metaParts.join(' | ') + '</div>' : '';

                        // Whenever ANY part of the breakdown used a Bundle or Case tier (not
                        // just when it's mixed with loose pieces), show a nested itemized card
                        // so the cashier always sees the bundle/case rate right alongside the
                        // per-piece rate — plus how much was saved vs. pricing every piece at
                        // the plain per-piece rate. (Fixed: this used to check `p.unit ===
                        // 'pack'`, but computeUnitBreakdown() actually labels that tier
                        // 'bundle' — so the bundle line never matched and silently fell
                        // through to the "Pieces" line, showing the wrong per-unit price.)
                        let bulkCard = '';
                        const hasBulkTier = bd.parts.some(p => p.unit === 'case' || p.unit === 'bundle');
                        if (hasBulkTier) {
                            const naive = item.qty * item.price;
                            const savings = naive - bd.subtotal;
                            const lines = bd.parts.map(p => {
                                if (p.unit === 'case') return '<div class="cart-bulk-line"><span>📦📦 ' + p.count + 'x Case (' + item.case_qty + ' Pcs)</span><span>' + fmt(item.case_price) + '</span></div>';
                                if (p.unit === 'bundle') return '<div class="cart-bulk-line"><span>📦 ' + p.count + 'x Bundle (' + item.pack_qty + ' Pcs)</span><span>' + fmt(item.pack_price) + '</span></div>';
                                return '<div class="cart-bulk-line"><span>🔹 ' + p.count + 'x Pieces</span><span>' + fmt(item.price) + ' each</span></div>';
                            }).join('');
                            bulkCard = '<div class="cart-bulk-card">' + lines +
                                (savings > 0.004 ? '<span class="cart-savings-badge">✨ Auto-optimized (Saved ' + fmt(savings) + ')</span>' : '') +
                                '</div>';
                        }

                        return '<div class="cart-line' + (idx === focusedCartIdx ? ' kbd-focused' : '') + '" data-pid="' + item.product_id + '">' +
                            imgEl +
                            '<div><div class="cart-line-name">' + escapeHtml(item.name) + '</div></div>' +
                            '<div class="cart-qty-box">' +
                            '<button type="button" class="qty-btn" onclick="changeQty(' + item.product_id + ',-1)">−</button>' +
                            '<input type="number" class="cart-qty-input" id="cart-qty-' + item.product_id + '" value="' + item.qty + '" min="1" ' +
                            'onfocus="focusedCartIdx=' + idx + ';renderCartFocusHighlight();" ' +
                            'onchange="setQtyDirect(' + item.product_id + ',this.value)"/>' +
                            '<button type="button" class="qty-btn" onclick="changeQty(' + item.product_id + ',1)">+</button>' +
                            '</div>' +
                            '<div class="cart-price-col">' + cartPriceColHTML(item, bd) + '</div>' +
                            '<div class="cart-sub-col">' + fmt(bd.subtotal) + '</div>' +
                            '<div style="display:flex;flex-direction:column;gap:4px;">' +
                            '<button type="button" class="cart-del-btn" onclick="removeFromCart(' + item.product_id + ')" title="Remove">✕</button>' +
                            '<button type="button" class="cart-del-btn" style="color:#e74c3c;" onclick="openCartDiscountModal(' + item.product_id + ')" title="Discount this item">🏷️</button>' +
                            '</div>' +
                            metaLine + bulkCard +
                            '</div>';
                    }).join('');
                }

                const subEl = document.getElementById('cart-sub');
                const totalEl = document.getElementById('cart-total');
                const presetsEl = document.getElementById('presets');
                if (subEl) subEl.textContent = fmt(total);
                const vatEl = document.getElementById('cart-vat');
                const taxEl = document.getElementById('cart-tax');
                const vatRateEl = document.getElementById('cart-vat-rate');
                const taxRateEl = document.getElementById('cart-tax-rate');
                if (vatEl) vatEl.textContent = fmt(totals.vat);
                if (taxEl) taxEl.textContent = fmt(totals.tax);
                if (vatRateEl) vatRateEl.textContent = VAT_RATE.toFixed(2).replace(/\.00$/, '');
                if (taxRateEl) taxRateEl.textContent = TAX_RATE.toFixed(2).replace(/\.00$/, '');
                if (totalEl) totalEl.textContent = fmt(total);

                if (presetsEl) {
                    const presets = [...new Set([
                        Math.ceil(total / 50) * 50,
                        Math.ceil(total / 100) * 100,
                        Math.ceil(total / 500) * 500,
                        1000
                    ].filter(v => v >= total))].slice(0, 4);
                    presetsEl.innerHTML = presets.map(p =>
                        '<button type="button" class="preset-btn" onclick="setCash(' + p + ')">' + fmt(p) + '</button>'
                    ).join('');
                }
                if (focusedCartIdx >= cart.length) focusedCartIdx = cart.length - 1;
                updateHeldCartsBadge();
                calcChange();
            }

            // Toggles the .kbd-focused outline onto whichever row matches focusedCartIdx
            // without rebuilding the row HTML — rebuilding on every focus event would
            // yank keyboard focus back out of the <input> the browser just focused.
            function renderCartFocusHighlight() {
                document.querySelectorAll('#cart-items .cart-line').forEach((row, idx) => {
                    row.classList.toggle('kbd-focused', idx === focusedCartIdx);
                });
            }

            // ── HELD CARTS ──
            function holdCurrentCart() {
                if (!cart.length) {
                    toast('Cart is empty — nothing to hold', 'warning');
                    return;
                }
                heldCarts.push({
                    id: Date.now(),
                    cart: cart.map(c => ({
                        ...c
                    })),
                    heldAt: new Date()
                });
                cart = [];
                focusedCartIdx = -1;
                updateCartUI();
                renderGrid();
                toast('Transaction held', 'success');
            }

            function resumeHeldCart(id) {
                const idx = heldCarts.findIndex(h => h.id === id);
                if (idx === -1) return;
                if (cart.length && !confirm('Resuming this held cart will replace your current cart items. Continue?')) return;
                cart = heldCarts[idx].cart.map(c => ({
                    ...c
                }));
                heldCarts.splice(idx, 1);
                focusedCartIdx = -1;
                document.getElementById('held-carts-menu').style.display = 'none';
                updateCartUI();
                renderGrid();
                toast('Held cart resumed', 'success');
            }

            function deleteHeldCart(id, evt) {
                if (evt) evt.stopPropagation();
                heldCarts = heldCarts.filter(h => h.id !== id);
                renderHeldCartsMenu();
                updateHeldCartsBadge();
            }

            function updateHeldCartsBadge() {
                const el = document.getElementById('held-carts-count');
                if (el) el.textContent = heldCarts.length;
            }

            function toggleHeldCartsMenu() {
                const menu = document.getElementById('held-carts-menu');
                if (!menu) return;
                const show = menu.style.display === 'none';
                if (show) {
                    renderHeldCartsMenu();
                    menu.style.display = 'block';
                } else {
                    menu.style.display = 'none';
                }
            }

            function renderHeldCartsMenu() {
                const menu = document.getElementById('held-carts-menu');
                if (!menu) return;
                if (!heldCarts.length) {
                    menu.innerHTML = '<div style="padding:14px;text-align:center;font-size:.78rem;color:var(--text3);">No held carts</div>';
                    return;
                }
                menu.innerHTML = heldCarts.map(h => {
                    const itemCount = h.cart.reduce((s, c) => s + c.qty, 0);
                    const total = h.cart.reduce((s, c) => s + computeUnitBreakdown(c).subtotal, 0);
                    return '<div class="held-cart-row" onclick="resumeHeldCart(' + h.id + ')">' +
                        '<div class="hc-info">' + itemCount + ' items · ' + fmt(total) + '<div class="hc-time">' + h.heldAt.toLocaleTimeString() + '</div></div>' +
                        '<button type="button" class="hc-del" onclick="deleteHeldCart(' + h.id + ',event)" title="Discard">✕</button>' +
                        '</div>';
                }).join('');
            }

            function calcChange() {
                const total = cartTotals().total;
                const cashInp = document.getElementById('cash-input');
                const box = document.getElementById('change-display');
                const btn = document.getElementById('pay-btn');
                if (!cashInp || !box || !btn) return;
                saveCartAutosave();
                const cash = parseFloat(cashInp.value) || 0;
                // The "Give Discount" button only appears once the cashier has entered a
                // cash tendered amount — before that there's no active sale to discount.
                const discBtn = document.getElementById('cart-discount-trigger-btn');
                if (discBtn) discBtn.style.display = (cash > 0 && cart.length) ? 'flex' : 'none';
                const chg = cash - total;
                if (cash <= 0) {
                    box.innerHTML = '';
                    btn.disabled = true;
                    return;
                }
                if (chg < 0) {
                    box.innerHTML = '<div class="change-box neg"><div class="change-label">Amount Short</div><div class="change-amount" style="color:var(--danger);">' + fmt(Math.abs(chg)) + '</div></div>';
                    btn.disabled = true;
                } else {
                    box.innerHTML = '<div class="change-box"><div class="change-label">Change to Give</div><div class="change-amount">' + fmt(chg) + '</div></div>';
                    btn.disabled = false;
                }
            }

            function processPayment() {
                if (!cart.length) return;
                const btn = document.getElementById('pay-btn');
                const totals = cartTotals();
                const total = totals.total;
                const cash = parseFloat(document.getElementById('cash-input').value) || 0;
                const chg = cash - total;
                if (chg < 0) {
                    toast('Insufficient cash!', 'error');
                    return;
                }
                setLoading(btn, true);
                // The backend stores subtotal as price*qty, so we send the *effective*
                // blended unit price (smart subtotal ÷ qty) rather than the plain piece
                // price — that keeps recorded revenue correct even when part of the
                // line sold at the Bundle/Case rate.
                const txPayload = {
                    items: cart.map(c => {
                        const bd = computeUnitBreakdown(c);
                        const effPrice = c.qty > 0 ? bd.subtotal / c.qty : c.price;
                        return {
                            product_id: c.product_id,
                            name: c.name,
                            price: effPrice,
                            qty: c.qty,
                            category_name: c.category_name
                        };
                    }),
                    subtotal: totals.subtotal,
                    vat_rate: VAT_RATE,
                    vat_amount: totals.vat,
                    tax_rate: TAX_RATE,
                    tax_amount: totals.tax,
                    total,
                    cash,
                    change: chg
                };
                apiPost('add_transaction', txPayload).then(r => {
                    setLoading(btn, false);

                    // Real server-side rejection (e.g. stock validation) — NOT a connectivity
                    // issue, so the sale must not be queued or completed; let the cashier fix
                    // it and retry.
                    if (r && !r.success && !isOfflineResult(r)) {
                        toast(r.error || 'Payment failed', 'error');
                        return;
                    }

                    let ref, isOffline = false;
                    if (isOfflineResult(r)) {
                        // Server unreachable (offline / power blip) — don't block the sale.
                        // Queue it locally with a temporary reference; it auto-syncs to a real
                        // Order # the moment connectivity returns (see flushPendingSales).
                        ref = queuePendingSale(txPayload);
                        isOffline = true;
                        toast('📴 No connection — sale saved offline, will sync automatically', 'warning');
                    } else {
                        ref = r.data.order_ref;
                    }

                    const now = new Date();
                    const refLabel = isOffline ? ref + ' (Offline — pending sync)' : ref;
                    let receipt = SHOP_NAME + '\n' + '─'.repeat(26) + '\n' + now.toLocaleString() + '\nOrder #' + refLabel + '\n' + '─'.repeat(26) + '\n';
                    cart.forEach(it => {
                        const bd = computeUnitBreakdown(it);
                        const tag = bd.breakdownText ? ' [' + bd.breakdownText + ']' : (' ' + it.qty + 'x' + CUR + it.price.toFixed(2));
                        receipt += it.name + '\n  ' + tag + ' = ' + CUR + bd.subtotal.toFixed(2) + '\n';
                    });
                    const receiptTotals = cartTotals();
                    receipt += '─'.repeat(26) + '\n' + 'SUBTOTAL'.padEnd(18) + (CUR + receiptTotals.subtotal.toFixed(2)).padStart(8) + '\n' + ('VAT ' + VAT_RATE.toFixed(2) + '%').padEnd(18) + (CUR + receiptTotals.vat.toFixed(2)).padStart(8) + '\n' + ('TAX ' + TAX_RATE.toFixed(2) + '%').padEnd(18) + (CUR + receiptTotals.tax.toFixed(2)).padStart(8) + '\n' + 'TOTAL'.padEnd(18) + (CUR + total.toFixed(2)).padStart(8) + '\n' + 'CASH'.padEnd(18) + (CUR + cash.toFixed(2)).padStart(8) + '\n' + 'CHANGE'.padEnd(18) + (CUR + chg.toFixed(2)).padStart(8) + '\n' + '─'.repeat(26) + '\n  Thank you! Come again!\n' + (isOffline ? '  (Offline sale — will sync automatically)\n' : '');
                    document.getElementById('receipt-display').textContent = receipt;
                    document.getElementById('final-change').textContent = fmt(chg);
                    // Saved separately from the plain-text preview above so the print
                    // window can render a proper itemized layout instead of a text dump.
                    lastReceiptData = {
                        ref: refLabel,
                        date: now.toISOString(),
                        items: cart.map(c => ({
                            ...c
                        })),
                        total,
                        subtotal: receiptTotals.subtotal,
                        vat_rate: VAT_RATE,
                        vat_amount: receiptTotals.vat,
                        tax_rate: TAX_RATE,
                        tax_amount: receiptTotals.tax,
                        cash,
                        change: chg
                    };
                    closeModal('cart-modal');
                    cart = [];
                    clearCartAutosave();
                    document.getElementById('cash-input').value = '';
                    document.getElementById('change-display').innerHTML = '';
                    openModal('success-modal');
                    // Automatic print trigger (matches void_order_items and end-of-shift,
                    // which already auto-print their receipts) — the cashier no longer has
                    // to remember to click Print after every sale. The button in the
                    // success modal stays as a manual re-print option if the first copy
                    // jams or a pop-up blocker caught it.
                    printSaleReceipt();
                    // Best-effort only — see openCashDrawer()'s silent=true behavior. A
                    // missing/offline QZ Tray or misconfigured printer name must never
                    // interrupt a sale that has already been recorded and receipted.
                    if (QZ_DRAWER_ENABLED) openCashDrawer(true).catch(() => {});
                    if (!isOffline) {
                        loadStats();
                        loadAllProds();
                        loadTopSellers();
                    }
                    updateCartUI();
                });
            }

            // Holds the most recently completed sale so the Print button can rebuild a
            // full receipt in a dedicated window — see printSaleReceipt() below.
            let lastReceiptData = null;

            // ── PRINT SALE RECEIPT ──
            // Previously this button just called window.print() directly on the main
            // POS page. That collided with the global print stylesheet
            // (@media print{body>*:not(#bc-print-area){display:none!important;}...})
            // which is scoped to the barcode-label print feature — since the receipt
            // modal isn't #bc-print-area, EVERYTHING on the page got hidden from print,
            // producing a totally blank page/PDF. Opening a separate, isolated print
            // window (same pattern already used for the Z-Read and void receipts)
            // sidesteps that conflict entirely.
            //
            // Layout redesigned to a real 4-column table (QTY | ITEM DESCRIPTION | PRICE
            // | TOTAL) with a proper SUBTOTAL/TAX/TOTAL DUE breakdown and a bold
            // highlight band behind TOTAL DUE — no QR code or barcode. All header
            // fields (address, TIN, terminal ID) are optional Settings — left blank,
            // they're simply omitted instead of printing "undefined".
            function printSaleReceipt() {
                if (!lastReceiptData) {
                    toast('No receipt to print yet', 'warning');
                    return;
                }
                const d = lastReceiptData;
                const win = window.open('', '_blank', 'width=380,height=650');
                if (!win) {
                    toast('Pop-up blocked — allow pop-ups to print the receipt', 'warning');
                    return;
                }
                const esc = receiptEsc;

                const dt = new Date(d.date);
                const dateStr = String(dt.getMonth() + 1).padStart(2, '0') + '/' + String(dt.getDate()).padStart(2, '0') + '/' + dt.getFullYear();
                let hh = dt.getHours();
                const ampm = hh >= 12 ? 'PM' : 'AM';
                hh = hh % 12;
                if (hh === 0) hh = 12;
                const timeStr = String(hh).padStart(2, '0') + ':' + String(dt.getMinutes()).padStart(2, '0') + ' ' + ampm;

                const itemRows = d.items.map(it => {
                    const bd = computeUnitBreakdown(it);
                    // Multi-tier sale (e.g. 1 bundle + 1 loose pc): print one row per tier so
                    // the PRICE column always shows that tier's real price (bundle/case/pc)
                    // instead of a blended average across the whole line.
                    if (bd.parts.length > 1) {
                        return bd.parts.map((p, i) => {
                            const unitPrice = p.unit === 'case' ? it.case_price : p.unit === 'bundle' ? it.pack_price : it.price;
                            const lineTotal = p.count * unitPrice;
                            const unitLabel = p.unit === 'piece' ? ('pc' + (p.count !== 1 ? 's' : '')) : (p.unit + (p.count !== 1 ? 's' : ''));
                            const nameCell = i === 0 ?
                                esc(it.name) :
                                '<span style="color:#666;">&#8618; ' + esc(it.name) + '</span>';
                            return '<tr><td>' + p.count + ' ' + unitLabel + '</td><td>' + nameCell + '</td>' +
                                '<td class="right">' + CUR + unitPrice.toFixed(2) + '</td>' +
                                '<td class="right">' + CUR + lineTotal.toFixed(2) + '</td></tr>';
                        }).join('');
                    }
                    // Single tier — could be all loose pieces, or the whole qty exactly
                    // filling one Bundle/Case tier. Either way, show that tier's real price.
                    const soleUnit = bd.parts[0] ? bd.parts[0].unit : 'piece';
                    const unitPrice = soleUnit === 'case' ? it.case_price : soleUnit === 'bundle' ? it.pack_price : it.price;
                    const unitTag = soleUnit === 'piece' ? '' : ' <span style="font-size:.82em;color:#666;">/' + soleUnit + '</span>';
                    // Discounted sale — show the regular price struck through next to the
                    // name so whatever markdown was applied (catalog Promo, a cashier's
                    // manual Discount, or bundle/case promo) is visible on the printout.
                    let discountTag = '';
                    if (soleUnit === 'piece' && it.regular_price && unitPrice < it.regular_price) {
                        const label = it.manual_discount ? 'DISCOUNT' : 'PROMO';
                        discountTag = ' <span style="font-size:.78em;color:#666;text-decoration:line-through;">' + CUR + it.regular_price.toFixed(2) + '</span> <span style="font-size:.78em;color:#a02515;font-weight:700;">' + label + '</span>';
                    } else if (soleUnit === 'bundle' && it.is_pack_promo && it.pack_regular_price) {
                        discountTag = ' <span style="font-size:.78em;color:#666;text-decoration:line-through;">' + CUR + it.pack_regular_price.toFixed(2) + '</span> <span style="font-size:.78em;color:#a02515;font-weight:700;">PROMO</span>';
                    } else if (soleUnit === 'case' && it.is_case_promo && it.case_regular_price) {
                        discountTag = ' <span style="font-size:.78em;color:#666;text-decoration:line-through;">' + CUR + it.case_regular_price.toFixed(2) + '</span> <span style="font-size:.78em;color:#a02515;font-weight:700;">PROMO</span>';
                    }
                    return '<tr><td>' + it.qty + ' x</td><td>' + esc(it.name) + unitTag + discountTag + '</td>' +
                        '<td class="right">' + CUR + unitPrice.toFixed(2) + '</td>' +
                        '<td class="right">' + CUR + bd.subtotal.toFixed(2) + '</td></tr>';
                }).join('');

                const itemCount = d.items.reduce((s, it) => s + it.qty, 0);
                const receiptSubtotal = d.subtotal ?? d.items.reduce((s, it) => s + computeUnitBreakdown(it).subtotal, 0);
                const receiptVat = d.vat_amount ?? receiptSubtotal * (d.vat_rate || 0) / 100;
                const receiptTax = d.tax_amount ?? receiptSubtotal * (d.tax_rate || 0) / 100;

                // Barcode of the clean order ref (strip the "(Offline — pending sync)"
                // suffix used only for display) — lets a cashier void this exact order
                // later by scanning the printed receipt itself instead of retyping the
                // code; see routeHIDScan()'s "ORD-" pattern match.
                const cleanRef = String(d.ref).split(' (')[0];
                const writeReceiptDoc = (barcodeImgHtml) => {
                    win.document.write(
                        '<!DOCTYPE html><html><head><style>' +
                        receiptBaseCSS() +
                        '</style></head><body>' +
                        '<div class="receipt-container">' +
                        receiptHeaderHTML() +
                        '<div class="receipt-row"><span>OR#: ' + esc(d.ref) + '</span></div>' +
                        '<div class="divider"></div>' +
                        '<div class="receipt-row"><span>CASHIER: ' + esc(CASHIER_NAME) + '</span></div>' +
                        '<div class="receipt-row"><span>TERM: ' + esc(TERMINAL_ID) + '</span><span>' + dateStr + ' ' + timeStr + '</span></div>' +
                        '<div class="divider"></div>' +
                        '<table class="items">' +
                        '<colgroup><col class="qty"><col class="desc"><col class="price"><col class="total"></colgroup>' +
                        '<thead><tr><th>QTY</th><th>ITEM DESCRIPTION</th><th class="right">PRICE</th><th class="right">TOTAL</th></tr></thead>' +
                        '<tbody>' + itemRows + '</tbody>' +
                        '</table>' +
                        '<div class="divider"></div>' +
                        '<div class="receipt-row"><span>SUBTOTAL:</span><span>' + CUR + receiptSubtotal.toFixed(2) + '</span></div>' +
                        '<div class="receipt-row"><span>VAT (' + (d.vat_rate || 0) + '%):</span><span>' + CUR + receiptVat.toFixed(2) + '</span></div>' +
                        '<div class="receipt-row"><span>TAX (' + (d.tax_rate || 0) + '%):</span><span>' + CUR + receiptTax.toFixed(2) + '</span></div>' +
                        '<div class="total-band"><span>TOTAL DUE:</span><span>' + CUR + d.total.toFixed(2) + '</span></div>' +
                        '<div class="divider"></div>' +
                        '<div class="receipt-row"><span>PAYMENT: CASH</span></div>' +
                        '<div class="receipt-row"><span>CASH TENDERED:</span><span>' + CUR + d.cash.toFixed(2) + '</span></div>' +
                        '<div class="receipt-row"><span>CHANGE DUE:</span><span>' + CUR + d.change.toFixed(2) + '</span></div>' +
                        '<div class="receipt-row"><span>ITEMS:</span><span>' + itemCount + '</span></div>' +
                        receiptFooterHTML(['Thank You for Shopping!', 'Please keep receipt for returns.']) +
                        barcodeImgHtml +
                        '</div>' +
                        '<script>window.onload=function(){window.print();}<\/script>' +
                        '</body></html>'
                    );
                    win.document.close();
                };

                if (typeof JsBarcode === 'undefined') {
                    // Library didn't load (offline/CDN blocked) — print the receipt anyway,
                    // just without the scan-to-void barcode this one time.
                    writeReceiptDoc('');
                } else {
                    const tmpSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                    try {
                        JsBarcode(tmpSvg, cleanRef, {
                            format: 'CODE128',
                            width: 1.6,
                            height: 38,
                            displayValue: true,
                            fontSize: 10,
                            margin: 6,
                            background: '#ffffff',
                            lineColor: '#000000'
                        });
                        svgToCanvasPng(tmpSvg, (dataUrl) => {
                            writeReceiptDoc(dataUrl ?
                                '<div style="text-align:center;margin-top:8px;"><img src="' + dataUrl + '" style="max-width:100%;"/><div style="font-size:.68rem;color:#666;margin-top:2px;">Scan to void this order</div></div>' :
                                '');
                        });
                    } catch (e) {
                        writeReceiptDoc('');
                    }
                }
            }


            // ════════════════════════════════
            // PRODUCTS PAGE
            // ════════════════════════════════
            let invProds = [],
                invCats = [],
                activeProdCat = '';

            function prodsInit() {
                if (cur_page !== 'products') return;
                apiGet('get_settings').then(s => {
                    CUR = s?.data?.currency || '₱';
                });
                loadInvProds();
                loadInvCats();
            }

            function loadInvProds() {
                apiGet('get_products').then(r => {
                    if (r?.success) {
                        invProds = r.data;
                        renderProds();
                    }
                });
            }

            function loadInvCats() {
                // Returns the promise (instead of firing-and-forgetting) so callers like
                // deleteCat()/addCat() can wait for the REFRESHED list before re-rendering
                // the category modal — otherwise the modal redraws immediately using the
                // stale array, making a just-deleted category look like it's still there.
                return apiGet('get_categories').then(r => {
                    if (!r?.success) return;
                    invCats = r.data;
                    const sel = document.getElementById('cat-filter');
                    if (sel) sel.innerHTML = '<option value="">All Categories</option>' + invCats.map(c => '<option value="' + c.id + '">' + c.name + '</option>').join('');
                    renderProdCatPills();
                });
            }

            function renderProdCatPills() {
                const el = document.getElementById('prod-cat-pills');
                if (!el) return;
                el.innerHTML = ['All', ...invCats.map(c => c.name)].map(c =>
                    '<button class="cat-pill ' + ((activeProdCat === '' && c === 'All') || c === activeProdCat ? 'active' : '') + '" onclick="setProdCat(\'' + c + '\')">' + c + '</button>'
                ).join('');
            }

            function setProdCat(c) {
                activeProdCat = c === 'All' ? '' : c;
                renderProdCatPills();
                renderProds();
            }

            function renderProds() {
                const q = (document.getElementById('prod-search')?.value || '').toLowerCase();
                const catF = document.getElementById('cat-filter')?.value || '';
                const sort = document.getElementById('sort-sel')?.value || 'name';
                let list = invProds.filter(p => {
                    const mq = !q || p.name.toLowerCase().includes(q);
                    const mc = activeProdCat ? p.category_name === activeProdCat : (!catF || p.category_id == catF);
                    return mq && mc;
                });
                list.sort((a, b) =>
                    sort === 'price' ? a.price - b.price :
                    sort === 'qty' ? b.quantity - a.quantity :
                    sort === 'sold' ? b.total_sold - a.total_sold :
                    a.name.localeCompare(b.name)
                );
                const countEl = document.getElementById('prod-count');
                if (countEl) countEl.textContent = list.length + ' products';
                const grid = document.getElementById('prod-grid');
                if (!grid) return;
                if (!list.length) {
                    grid.innerHTML = '<div style="grid-column:1/-1"><div class="empty-state"><div class="empty-icon">📦</div><div class="empty-text">No products</div></div></div>';
                    return;
                }
                grid.innerHTML = list.map(p => {
                    const storeQ = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                    const stockColor = storeQ <= 0 ? 'var(--danger)' : storeQ <= 5 ? 'var(--accent2)' : 'var(--green)';
                    const img = p.has_image == 1 ? '<img src="' + prodImgUrl(p.id, p.updated_at) + '" class="product-card-img" loading="lazy" data-fallback="div" onerror="imgFallback(this)"/>' : '<div class="product-card-ph"><img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt=""></div>';
                    const promoInfo = getPromoInfo(p);
                    const priceHTML = promoInfo.active ?
                        '<span class="promo-strike">' + CUR + promoInfo.price.toFixed(2) + '</span><span class="promo-now">' + CUR + promoInfo.promo.toFixed(2) + '</span>' :
                        CUR + parseFloat(p.price).toFixed(2);
                    return '<div class="product-card" onclick="openEditModal(' + p.id + ')">' +
                        img +
                        (promoInfo.active ? '<span class="sale-badge">🏷️ SALE</span>' : '') +
                        '<div class="product-card-body">' +
                        '<div class="product-card-name">' + p.name + '</div>' +
                        '<div class="product-card-price">' + priceHTML + '</div>' +
                        '<div class="product-card-meta">' + (p.category_name || 'Uncategorized') + '</div>' +
                        '<div class="product-card-meta" style="color:' + stockColor + ';font-weight:600;">Store: ' + formatUnitBreakdown(storeQ, p) + '</div>' +
                        '<div class="product-card-meta" style="color:var(--text3);">Warehouse: ' + formatUnitBreakdown(p.warehouse_quantity || 0, p) + '</div>' +
                        '</div></div>';
                }).join('');
            }

            // Toggles the Unit of Measurement's #p-unit-size id between the visible
            // numeric input (for ml/L/g/kg/pcs/box/pack/case) and a visible, editable
            // text field (for a picked Diaper/Sleeper size). The text field starts
            // pre-filled with the picked size's own label, since a type="number" input
            // can never hold text like "Medium (M) – 6-11kg" — the browser just
            // silently blanks it — but it's left fully editable afterward so the actual
            // size/weight (e.g. "XXL – 16kg", or a specific number like "42" for
            // slippers) can be recorded instead of only the preset bracket. The person
            // only ever touches the ONE Unit Type dropdown; this just makes
            // #p-unit-size resolve to whichever element can actually hold what was
            // picked, so save, edit-population, reset, and barcode autofill all keep
            // working unchanged either way.
            function onUnitTypeChange() {
                const typeEl = document.getElementById('p-unit-type');
                const numEl = document.querySelector('[data-role="unit-size-number"]');
                const sizeEl = document.querySelector('[data-role="unit-size-size"]');
                if (!typeEl || !numEl || !sizeEl) return;
                if (typeEl.value.startsWith('size|')) {
                    numEl.removeAttribute('id');
                    numEl.style.display = 'none';
                    // Only overwrite what's there when the picked size actually changed
                    // (tracked via a data attribute) — so re-running this after the person
                    // has already typed their own actual size doesn't wipe it out.
                    const presetLabel = typeEl.value.slice(5); // everything after "size|"
                    if (sizeEl.dataset.lastPreset !== presetLabel) {
                        sizeEl.value = presetLabel;
                        sizeEl.dataset.lastPreset = presetLabel;
                    }
                    sizeEl.style.display = '';
                    sizeEl.id = 'p-unit-size';
                } else {
                    sizeEl.removeAttribute('id');
                    sizeEl.style.display = 'none';
                    numEl.id = 'p-unit-size';
                    numEl.style.display = '';
                }
            }

            function openAddModal() {
                document.getElementById('edit-id').value = '';
                document.getElementById('prod-modal-title').textContent = 'Add Product';
                document.getElementById('p-name').value = '';
                document.getElementById('p-price').value = '';
                const pCostReset = document.getElementById('p-cost');
                if (pCostReset) pCostReset.value = '';
                document.getElementById('p-desc').value = '';
                setExpiryFromIso('');
                setDeliveryFromIso('');
                document.getElementById('p-barcode').value = '';
                _barcodeAutoGenerated = false;
                const pBcCheck = document.getElementById('p-barcode-check');
                if (pBcCheck) pBcCheck.textContent = '';
                ['p-qty-cases', 'p-qty-bundles', 'p-qty-loose', 'p-wh-qty-cases', 'p-wh-qty-bundles', 'p-wh-qty-loose'].forEach(fid => {
                    const el = document.getElementById(fid);
                    if (el) el.value = '';
                });
                document.getElementById('delete-prod-btn').style.display = 'none';
                const showQrBtn = document.getElementById('show-qr-btn');
                if (showQrBtn) showQrBtn.style.display = 'none';
                const qrWrap = document.getElementById('qr-preview-wrap');
                if (qrWrap) qrWrap.style.display = 'none';
                document.getElementById('p-cat-input').value = '';
                document.getElementById('p-cat').value = '';
                closeCatDropdown();
                const packQty = document.getElementById('p-pack-qty');
                if (packQty) packQty.value = '';
                const packBc = document.getElementById('p-pack-barcode');
                if (packBc) packBc.value = '';
                const packPrice = document.getElementById('p-pack-price');
                if (packPrice) packPrice.value = '';
                const caseQty = document.getElementById('p-case-qty');
                if (caseQty) caseQty.value = '';
                const caseBc = document.getElementById('p-case-barcode');
                if (caseBc) caseBc.value = '';
                const casePrice = document.getElementById('p-case-price');
                if (casePrice) casePrice.value = '';
                const autoConv = document.getElementById('p-auto-convert');
                if (autoConv) autoConv.checked = false;
                const lowStockThr = document.getElementById('p-low-stock-threshold');
                if (lowStockThr) lowStockThr.value = '';
                const pBrand = document.getElementById('p-brand');
                if (pBrand) pBrand.value = '';
                const pSupplier = document.getElementById('p-supplier');
                if (pSupplier) pSupplier.value = '';
                const pUnitType = document.getElementById('p-unit-type');
                if (pUnitType) pUnitType.value = 'pcs';
                onUnitTypeChange();
                const pUnitSize = document.getElementById('p-unit-size');
                if (pUnitSize) pUnitSize.value = '';
                const sizeHolderReset = document.querySelector('[data-role="unit-size-size"]');
                if (sizeHolderReset) delete sizeHolderReset.dataset.lastPreset;
                const promoEnabled = document.getElementById('p-promo-enabled');
                if (promoEnabled) promoEnabled.checked = false;
                const promoPrice = document.getElementById('p-promo-price');
                if (promoPrice) promoPrice.value = '';
                const promoPackEnabled = document.getElementById('p-promo-pack-enabled');
                if (promoPackEnabled) promoPackEnabled.checked = false;
                const promoPackPrice = document.getElementById('p-promo-pack-price');
                if (promoPackPrice) promoPackPrice.value = '';
                const promoCaseEnabled = document.getElementById('p-promo-case-enabled');
                if (promoCaseEnabled) promoCaseEnabled.checked = false;
                const promoCasePrice = document.getElementById('p-promo-case-price');
                if (promoCasePrice) promoCasePrice.value = '';
                onPromoToggle();
                onPromoToggle('pack');
                onPromoToggle('case');
                populateBrandSupplierDatalists();
                updatePackHints();
                removeImg();
                openModal('prod-modal');
            }

            // tier: 'piece' (default), 'pack' (Bundle), or 'case' — each tier has its own
            // enable checkbox + promo price field, following the p-promo(-TIER)-* naming.
            function onPromoToggle(tier) {
                const suffix = !tier || tier === 'piece' ? '' : '-' + tier;
                const enabled = document.getElementById('p-promo' + suffix + '-enabled')?.checked;
                const wrap = document.getElementById('p-promo' + suffix + '-wrap');
                if (wrap) wrap.style.display = enabled ? '' : 'none';
                updatePromoHint(tier);
            }

            function updatePromoHint(tier) {
                const suffix = !tier || tier === 'piece' ? '' : '-' + tier;
                const priceFieldId = tier === 'pack' ? 'p-pack-price' : tier === 'case' ? 'p-case-price' : 'p-price';
                const hint = document.getElementById('p-promo' + suffix + '-hint');
                if (!hint) return;
                const enabled = document.getElementById('p-promo' + suffix + '-enabled')?.checked;
                if (!enabled) {
                    hint.textContent = '';
                    return;
                }
                const price = parseFloat(document.getElementById(priceFieldId)?.value);
                const promo = parseFloat(document.getElementById('p-promo' + suffix + '-price')?.value);
                if (isNaN(promo) || promo <= 0) {
                    hint.textContent = 'Enter a promo price lower than the Selling Price.';
                    hint.style.color = 'var(--text3)';
                    return;
                }
                if (isNaN(price) || promo >= price) {
                    hint.textContent = '⚠️ Promo price must be lower than the Selling Price (₱' + (isNaN(price) ? '0.00' : price.toFixed(2)) + ') to take effect.';
                    hint.style.color = 'var(--danger)';
                    return;
                }
                const pct = Math.round((1 - promo / price) * 100);
                hint.textContent = '✅ ' + pct + '% off — will show as ₱' + promo.toFixed(2) + ' (was ₱' + price.toFixed(2) + ') in Sales, Cart, and Receipt.';
                hint.style.color = 'var(--green)';
            }

            function populateBrandSupplierDatalists() {
                const allProds = (invProds && invProds.length ? invProds : whProds) || [];
                const brands = [...new Set(allProds.map(p => p.brand).filter(Boolean))].sort();
                const suppliers = [...new Set(allProds.map(p => p.supplier).filter(Boolean))].sort();
                const brandDl = document.getElementById('p-brand-datalist');
                const supDl = document.getElementById('p-supplier-datalist');
                if (brandDl) brandDl.innerHTML = brands.map(b => '<option value="' + escapeHtml(b) + '">').join('');
                if (supDl) supDl.innerHTML = suppliers.map(s => '<option value="' + escapeHtml(s) + '">').join('');
            }

            function openEditModal(id) {
                const p = invProds.find(x => x.id == id) || whProds.find(x => x.id == id);
                if (!p) return;
                document.getElementById('edit-id').value = p.id;
                document.getElementById('prod-modal-title').textContent = 'Edit Product';
                document.getElementById('p-name').value = p.name;
                document.getElementById('p-price').value = p.price;
                const pCostEdit = document.getElementById('p-cost');
                if (pCostEdit) pCostEdit.value = (p.cost_price ?? '');
                document.getElementById('p-desc').value = p.description || '';
                setExpiryFromIso(p.expiry_date || '');
                setDeliveryFromIso(p.delivery_date || '');
                document.getElementById('p-barcode').value = p.barcode || '';
                _barcodeAutoGenerated = false; // editing an existing real barcode — never silently swap it
                const pBcCheck2 = document.getElementById('p-barcode-check');
                if (pBcCheck2) pBcCheck2.textContent = '';
                // Decompose the saved totals back into Cases/Bundles/Loose Pcs using this
                // product's own Case/Bundle sizes — e.g. a saved total of 2880 pcs on a
                // 120-pcs case re-opens as "24 Cases", not "0 Cases, 2880 Loose Pcs".
                // (Previously this just dumped the whole total into Loose Pcs on every
                // edit, silently discarding whatever Cases/Bundles split was entered.)
                const storeTotal = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                const storeSplit = splitQtyIntoUnits(storeTotal, p);
                const qtyLoose = document.getElementById('p-qty-loose');
                if (qtyLoose) qtyLoose.value = storeSplit.pcs;
                const qtyCases = document.getElementById('p-qty-cases');
                if (qtyCases) qtyCases.value = storeSplit.cases || '';
                const qtyBundles = document.getElementById('p-qty-bundles');
                if (qtyBundles) qtyBundles.value = storeSplit.bundles || '';
                const whSplit = splitQtyIntoUnits(p.warehouse_quantity ?? 0, p);
                const whLoose = document.getElementById('p-wh-qty-loose');
                if (whLoose) whLoose.value = whSplit.pcs;
                const whCases = document.getElementById('p-wh-qty-cases');
                if (whCases) whCases.value = whSplit.cases || '';
                const whBundles = document.getElementById('p-wh-qty-bundles');
                if (whBundles) whBundles.value = whSplit.bundles || '';
                document.getElementById('delete-prod-btn').style.display = '';
                const showQrBtn = document.getElementById('show-qr-btn');
                if (showQrBtn) showQrBtn.style.display = p.barcode ? '' : 'none';
                // invCats may not be loaded yet if this modal was opened from a page other
                // than Products (e.g. Warehouse) — fetch it on demand so the dropdown
                // still has options to show/filter against.
                if (!invCats.length) loadInvCats();
                // category_name is always returned by get_products, so use it directly
                // rather than depending on invCats being loaded/matched.
                document.getElementById('p-cat-input').value = p.category_name || '';
                document.getElementById('p-cat').value = p.category_id || '';
                const packQty = document.getElementById('p-pack-qty');
                if (packQty) packQty.value = p.pack_qty || '';
                const packBc = document.getElementById('p-pack-barcode');
                if (packBc) packBc.value = p.pack_barcode || '';
                const packPrice = document.getElementById('p-pack-price');
                if (packPrice) packPrice.value = p.pack_price || '';
                const caseQty = document.getElementById('p-case-qty');
                if (caseQty) caseQty.value = p.case_qty || '';
                const caseBc = document.getElementById('p-case-barcode');
                if (caseBc) caseBc.value = p.case_barcode || '';
                const casePrice = document.getElementById('p-case-price');
                if (casePrice) casePrice.value = p.case_price || '';
                const autoConv = document.getElementById('p-auto-convert');
                if (autoConv) autoConv.checked = !!p.auto_convert;
                const lowStockThr = document.getElementById('p-low-stock-threshold');
                if (lowStockThr) lowStockThr.value = (p.low_stock_threshold ?? 5);
                const pBrand = document.getElementById('p-brand');
                if (pBrand) pBrand.value = p.brand || '';
                const pSupplier = document.getElementById('p-supplier');
                if (pSupplier) pSupplier.value = p.supplier || '';
                const pUnitType = document.getElementById('p-unit-type');
                if (pUnitType) {
                    if (p.unit_type === 'size' && p.unit_size) {
                        // The stored size may be an exact preset ("size|XXL – 15kg & up") or
                        // a since-edited actual size ("size|XXL – 16kg") that no longer matches
                        // any option verbatim — the dropdown's own value only needs to land on
                        // ANY "size|…" option to switch the field into size/text mode; the real
                        // value the person sees and can keep editing is set from p.unit_size
                        // itself just below, not from what the dropdown resolves to.
                        const exactValue = 'size|' + p.unit_size;
                        const hasExactOption = [...pUnitType.options].some(o => o.value === exactValue);
                        pUnitType.value = hasExactOption ? exactValue :
                            ([...pUnitType.options].find(o => o.value.startsWith('size|'))?.value || 'pcs');
                    } else {
                        pUnitType.value = p.unit_type || 'pcs';
                    }
                }
                onUnitTypeChange(); // resolve #p-unit-size to the right element BEFORE setting the value below
                const pUnitSize = document.getElementById('p-unit-size');
                if (pUnitSize) pUnitSize.value = p.unit_size ?? '';
                const hasPromo = p.promo_price !== null && p.promo_price !== undefined && p.promo_price !== '';
                const promoEnabled = document.getElementById('p-promo-enabled');
                if (promoEnabled) promoEnabled.checked = hasPromo;
                const promoPrice = document.getElementById('p-promo-price');
                if (promoPrice) promoPrice.value = hasPromo ? p.promo_price : '';
                const hasPackPromo = p.promo_pack_price !== null && p.promo_pack_price !== undefined && p.promo_pack_price !== '';
                const promoPackEnabled = document.getElementById('p-promo-pack-enabled');
                if (promoPackEnabled) promoPackEnabled.checked = hasPackPromo;
                const promoPackPrice = document.getElementById('p-promo-pack-price');
                if (promoPackPrice) promoPackPrice.value = hasPackPromo ? p.promo_pack_price : '';
                const hasCasePromo = p.promo_case_price !== null && p.promo_case_price !== undefined && p.promo_case_price !== '';
                const promoCaseEnabled = document.getElementById('p-promo-case-enabled');
                if (promoCaseEnabled) promoCaseEnabled.checked = hasCasePromo;
                const promoCasePrice = document.getElementById('p-promo-case-price');
                if (promoCasePrice) promoCasePrice.value = hasCasePromo ? p.promo_case_price : '';
                onPromoToggle();
                onPromoToggle('pack');
                onPromoToggle('case');
                populateBrandSupplierDatalists();
                updatePackHints();
                imgB64 = null;
                const preview = document.getElementById('img-preview');
                const placeholder = document.getElementById('img-placeholder');
                const removeBtn = document.getElementById('img-remove-btn');
                const qrWrap = document.getElementById('qr-preview-wrap');
                if (qrWrap) qrWrap.style.display = 'none';
                if (p.has_image == 1) {
                    if (preview) {
                        preview.src = prodImgUrl(p.id, p.updated_at);
                        preview.style.display = 'block';
                        // If the DB record says there's a photo but the actual file is
                        // gone (e.g. lost on a restart without a persisted uploads disk),
                        // fall back to the same placeholder shown for "no photo at all"
                        // instead of the browser's broken-image icon.
                        preview.onerror = function() {
                            this.style.display = 'none';
                            this.onerror = null;
                            if (placeholder) placeholder.style.display = 'block';
                            if (removeBtn) removeBtn.style.display = 'none';
                        };
                    }
                    if (placeholder) placeholder.style.display = 'none';
                    if (removeBtn) removeBtn.style.display = '';
                } else {
                    if (preview) {
                        preview.src = '';
                        preview.style.display = 'none';
                    }
                    if (placeholder) placeholder.style.display = 'block';
                    if (removeBtn) removeBtn.style.display = 'none';
                }
                openModal('prod-modal');
            }

            async function saveProduct() {
                const id = document.getElementById('edit-id').value;
                const name = document.getElementById('p-name').value.trim();
                const price = parseFloat(document.getElementById('p-price').value);
                const costRaw = document.getElementById('p-cost')?.value;
                const cost = (costRaw !== '' && costRaw !== undefined) ? parseFloat(costRaw) : null;
                const qty = parseInt(document.getElementById('p-qty').value);
                const desc = document.getElementById('p-desc').value.trim();
                const expiry = document.getElementById('p-expiry').value || null;
                const deliveryDate = document.getElementById('p-delivery').value || null;
                const barcode = document.getElementById('p-barcode').value.trim() || null;
                if (!name) {
                    toast('Product name is required', 'error');
                    return;
                }
                if (isNaN(price) || price < 0) {
                    toast('Enter a valid price', 'error');
                    return;
                }
                if (isNaN(qty) || qty < 0) {
                    toast('Enter a valid quantity', 'error');
                    return;
                }
                const btn = document.getElementById('save-prod-btn');
                setLoading(btn, true);
                const catId = await resolveCategoryId();
                const whQtyEl = document.getElementById('p-wh-qty');
                const whQty = whQtyEl ? (parseInt(whQtyEl.value) || 0) : 0;
                // Multi-unit packaging (Bundle/Case) — optional, blank means "not configured".
                const packQtyVal = document.getElementById('p-pack-qty')?.value;
                const packBarcodeVal = document.getElementById('p-pack-barcode')?.value.trim();
                const packPriceVal = document.getElementById('p-pack-price')?.value;
                const caseQtyVal = document.getElementById('p-case-qty')?.value;
                const caseBarcodeVal = document.getElementById('p-case-barcode')?.value.trim();
                const casePriceVal = document.getElementById('p-case-price')?.value;
                const autoConvert = document.getElementById('p-auto-convert')?.checked ? 1 : 0;
                const lowStockThresholdVal = document.getElementById('p-low-stock-threshold')?.value;
                const brandVal = document.getElementById('p-brand')?.value.trim();
                const supplierVal = document.getElementById('p-supplier')?.value.trim();
                // "size|<label>" is the dropdown's own composite value for a
                // directly-picked Diaper/Sleeper size — split back into the plain
                // unit_type='size' + unit_size=<label> the backend actually expects.
                const rawUnitType = document.getElementById('p-unit-type')?.value || 'pcs';
                const unitTypeVal = rawUnitType.startsWith('size|') ? 'size' : rawUnitType;
                // #p-unit-size always resolves (via onUnitTypeChange's id-swap) to whichever
                // element currently holds the real value — the number input, or the
                // editable size/text field, which may have been customized past its
                // preset label (e.g. "XXL – 15kg & up" edited to "XXL – 16kg"). Reading
                // that field directly, rather than re-deriving it from the dropdown's own
                // option value, is what makes that edit actually get saved.
                const unitSizeVal = document.getElementById('p-unit-size')?.value;
                const promoEnabledVal = document.getElementById('p-promo-enabled')?.checked;
                const promoPriceRaw = document.getElementById('p-promo-price')?.value;
                let promoPriceVal = null;
                if (promoEnabledVal && promoPriceRaw !== '' && promoPriceRaw !== undefined) {
                    const pp = parseFloat(promoPriceRaw);
                    if (isNaN(pp) || pp <= 0 || pp >= price) {
                        setLoading(btn, false);
                        toast('Promo price must be a positive number lower than the Selling Price', 'error');
                        return;
                    }
                    promoPriceVal = pp;
                }
                const promoPackEnabledVal = document.getElementById('p-promo-pack-enabled')?.checked;
                const promoPackPriceRaw = document.getElementById('p-promo-pack-price')?.value;
                let promoPackPriceVal = null;
                if (promoPackEnabledVal && promoPackPriceRaw !== '' && promoPackPriceRaw !== undefined) {
                    const pp = parseFloat(promoPackPriceRaw);
                    const packP = parseFloat(packPriceVal);
                    if (isNaN(pp) || pp <= 0 || isNaN(packP) || pp >= packP) {
                        setLoading(btn, false);
                        toast('Bundle promo price must be a positive number lower than the Bundle Selling Price', 'error');
                        return;
                    }
                    promoPackPriceVal = pp;
                }
                const promoCaseEnabledVal = document.getElementById('p-promo-case-enabled')?.checked;
                const promoCasePriceRaw = document.getElementById('p-promo-case-price')?.value;
                let promoCasePriceVal = null;
                if (promoCaseEnabledVal && promoCasePriceRaw !== '' && promoCasePriceRaw !== undefined) {
                    const pp = parseFloat(promoCasePriceRaw);
                    const caseP = parseFloat(casePriceVal);
                    if (isNaN(pp) || pp <= 0 || isNaN(caseP) || pp >= caseP) {
                        setLoading(btn, false);
                        toast('Case promo price must be a positive number lower than the Case Selling Price', 'error');
                        return;
                    }
                    promoCasePriceVal = pp;
                }
                const payload = {
                    name,
                    price,
                    cost_price: (cost !== null && !isNaN(cost) && cost >= 0) ? cost : null,
                    quantity: qty,
                    store_quantity: qty,
                    warehouse_quantity: whQty,
                    category_id: catId || null,
                    description: desc,
                    image: imgB64 || null,
                    expiry_date: expiry,
                    delivery_date: deliveryDate,
                    barcode: barcode,
                    pack_qty: packQtyVal || null,
                    pack_barcode: packBarcodeVal || null,
                    pack_price: packPriceVal || null,
                    case_qty: caseQtyVal || null,
                    case_barcode: caseBarcodeVal || null,
                    case_price: casePriceVal || null,
                    auto_convert: autoConvert,
                    low_stock_threshold: lowStockThresholdVal || null,
                    brand: brandVal || null,
                    supplier: supplierVal || null,
                    unit_type: unitTypeVal,
                    unit_size: unitSizeVal || null,
                    promo_price: promoPriceVal,
                    promo_pack_price: promoPackPriceVal,
                    promo_case_price: promoCasePriceVal
                };
                let req;
                if (id) {
                    payload.id = parseInt(id);
                    req = apiPost('update_product', payload);
                } else {
                    req = apiPost('add_product', payload);
                }
                let r = await req;
                // SELF-HEALING BARCODE RETRY: if the code currently in the field came
                // from the Auto-Generate button and it happened to collide with an
                // existing one, silently mint a fresh code and retry — the user never
                // typed or scanned this value on purpose, so there's nothing for them
                // to "fix" manually. A real typed/scanned duplicate still surfaces the
                // error below, since that's a genuine conflict they need to resolve.
                let barcodeRetries = 0;
                while (!r?.success && _barcodeAutoGenerated && /barcode already exists/i.test(r?.error || '') && barcodeRetries < 5) {
                    barcodeRetries++;
                    const freshBarcode = 'BC-' + generateBarcodeSuffix();
                    payload.barcode = freshBarcode;
                    document.getElementById('p-barcode').value = freshBarcode;
                    r = id ? await apiPost('update_product', payload) : await apiPost('add_product', payload);
                }
                setLoading(btn, false);
                if (!r?.success) {
                    toast(r?.error || 'Error saving product', 'error');
                    return;
                }
                // If new product, show the generated barcode
                if (!id && r.data?.barcode) {
                    document.getElementById('p-barcode').value = r.data.barcode;
                    const showQrBtn = document.getElementById('show-qr-btn');
                    if (showQrBtn) showQrBtn.style.display = '';
                }
                toast(id ? 'Product updated!' : 'Product added!', 'success');
                closeModal('prod-modal');
                loadInvProds();
            }

            function deleteProduct() {
                const id = document.getElementById('edit-id').value;
                if (!id) return;
                if (!confirm('Delete this product? This cannot be undone.')) return;
                apiPost('delete_product', {
                    id: parseInt(id)
                }).then(r => {
                    if (!r?.success) {
                        toast('Error deleting', 'error');
                        return;
                    }
                    toast('Product deleted', 'success');
                    closeModal('prod-modal');
                    loadInvProds();
                });
            }

            function openCatModal() {
                renderCatList();
                openModal('cat-modal');
            }

            function renderCatList() {
                const el = document.getElementById('cat-list');
                if (!el) return;
                el.innerHTML = invCats.map(c =>
                    '<div class="cat-manage-row"><span>' + c.name + '</span><button type="button" class="btn btn-danger btn-sm" onclick="deleteCat(' + c.id + ')">Delete</button></div>'
                ).join('');
            }

            function addCat() {
                const name = document.getElementById('new-cat-input').value.trim();
                if (!name) {
                    toast('Enter a category name', 'error');
                    return;
                }
                apiPost('add_category', {
                    name
                }).then(r => {
                    if (!r?.success) {
                        toast(r?.error || 'Error adding category', 'error');
                        return;
                    }
                    toast('Category added', 'success');
                    document.getElementById('new-cat-input').value = '';
                    loadInvCats().then(renderCatList); // wait for the fresh list before redrawing
                });
            }

            function deleteCat(id) {
                if (!confirm('Delete this category? Products will become uncategorized.')) return;
                apiPost('delete_category', {
                    id
                }).then(r => {
                    if (!r?.success) {
                        toast('Error deleting category', 'error');
                        return;
                    }
                    toast('Category deleted', 'success');
                    loadInvCats().then(renderCatList); // wait for the fresh list before redrawing —
                    // redrawing immediately (before this resolves) is what made deleted categories
                    // appear to "stick" in the modal even though they were already gone server-side.
                });
            }

            // ════════════════════════════════
            // SALES PAGE
            // ════════════════════════════════
            let txData = [];

            function clearDateFilter() {
                const df = document.getElementById('date-from-filter');
                const dt = document.getElementById('date-to-filter');
                if (df) df.value = '';
                if (dt) dt.value = '';
                closeDateRangePopover();
                loadTx();
            }

            function applyDateRange() {
                closeDateRangePopover();
                loadTx();
            }

            // Toggle the date-range popover open/closed. stopPropagation so the same
            // click that opens it doesn't immediately trigger the document-level
            // click-outside handler below and close it again.
            function toggleDateRangePopover(evt) {
                evt?.stopPropagation();
                const pop = document.getElementById('date-range-popover');
                if (!pop) return;
                pop.style.display = pop.style.display === 'block' ? 'none' : 'block';
            }

            function closeDateRangePopover() {
                const pop = document.getElementById('date-range-popover');
                if (pop) pop.style.display = 'none';
            }
            document.addEventListener('click', e => {
                const wrap = document.getElementById('date-range-wrap');
                if (wrap && !wrap.contains(e.target)) closeDateRangePopover();
            });

            function salesInit() {
                if (cur_page !== 'sales') return;
                // Load settings first so CUR is set, then load ALL transactions (no date filter by default)
                apiGet('get_settings').then(s => {
                    CUR = s?.data?.currency || '\u20B1';
                    loadTx();
                    loadSalesCharts();
                });
            }

            function loadSalesCharts() {
                loadSalesTopProducts(currentSalesChartPeriod);
                loadCategoryChart(currentSalesChartPeriod);
                loadDailyChart(currentSalesChartPeriod);
            }

            // Tracks which period the 7-Day/Weekly/Monthly sales chart is currently
            // showing, so re-renders (e.g. after a sale) keep whatever the cashier/owner
            // last selected instead of silently resetting back to Daily.
            let currentSalesChartPeriod = 'daily';

            function loadDailyChart(period) {
                period = period || 'daily';
                const params = {
                    period
                };
                if (period === 'daily') params.days = 7;
                apiGet('get_daily_sales', params).then(daily => {
                    if (!daily?.success) return;
                    const rows = daily.data;
                    const max = Math.max(...rows.map(r => r.revenue), 1);
                    const el = document.getElementById('daily-chart');
                    if (el) el.innerHTML = rows.map(r =>
                        '<div class="bar-row">' +
                        '<div class="bar-label">' + r.short + '</div>' +
                        '<div class="bar-track"><div class="bar-fill" style="width:' + (r.revenue / max * 100).toFixed(1) + '%"></div></div>' +
                        '<div class="bar-val">' + CUR + parseFloat(r.revenue).toFixed(0) + '</div>' +
                        '</div>'
                    ).join('');
                });
            }

            function loadCategoryChart(period) {
                const params = period ? {
                    period
                } : {};
                apiGet('get_category_stats', params).then(catStats => {
                    if (!catStats?.success) return;
                    const rows = catStats.data;
                    const max = Math.max(...rows.map(r => r.total_revenue), 1);
                    const el = document.getElementById('cat-chart');
                    if (el) el.innerHTML = rows.length ? rows.map(r =>
                        '<div class="bar-row">' +
                        '<div class="bar-label" style="font-size:.7rem;">' + r.category + '</div>' +
                        '<div class="bar-track"><div class="bar-fill" style="width:' + (r.total_revenue / max * 100).toFixed(1) + '%"></div></div>' +
                        '<div class="bar-val">' + CUR + parseFloat(r.total_revenue).toFixed(0) + '</div>' +
                        '</div>'
                    ).join('') : '<div style="text-align:center;padding:20px;color:var(--text3);font-size:.83rem;">No data yet</div>';
                });
            }

            // Shared Daily/Weekly/Monthly toggle (positioned just below Sales History) —
            // re-scopes Top Products, Sales by Category, AND the trend chart all at once:
            // Daily = today only, Weekly = last 7 days, Monthly = last 30 days. Replaces
            // the old per-card toggle that only affected the 7-Day Sales chart.
            function periodLabel(period) {
                return period === 'weekly' ? 'This Week' : period === 'monthly' ? 'This Month' : 'Today';
            }

            function setSharedSalesPeriod(period, btnEl) {
                currentSalesChartPeriod = period;
                const wrap = btnEl.closest('.period-toggle');
                if (wrap) wrap.querySelectorAll('.period-btn').forEach(b => b.classList.toggle('active', b === btnEl));

                const topTitleEl = document.getElementById('top-list-title');
                if (topTitleEl) topTitleEl.textContent = '🏆 Top Products — ' + periodLabel(period);
                const catTitleEl = document.getElementById('cat-chart-title');
                if (catTitleEl) catTitleEl.textContent = '🏷️ Sales by Category — ' + periodLabel(period);
                const dailyTitleEl = document.getElementById('daily-chart-title');
                if (dailyTitleEl) dailyTitleEl.textContent = period === 'weekly' ? '📈 Weekly Sales' : period === 'monthly' ? '📈 Monthly Sales' : '📈 7-Day Sales';

                const topEl = document.getElementById('top-list');
                if (topEl) topEl.innerHTML = '<div style="text-align:center;padding:16px;color:var(--text3);font-size:.83rem;">Loading…</div>';
                const catEl = document.getElementById('cat-chart');
                if (catEl) catEl.innerHTML = '<div style="color:var(--text3);font-size:.83rem;text-align:center;padding:20px;">Loading…</div>';
                const chartEl = document.getElementById('daily-chart');
                if (chartEl) chartEl.innerHTML = '<div style="color:var(--text3);font-size:.83rem;text-align:center;padding:20px;">Loading…</div>';

                loadSalesTopProducts(period);
                loadCategoryChart(period);
                loadDailyChart(period);
            }

            // Generic accordion toggle for the Sales-page summary cards (Top Products,
            // Sales by Category, 7-Day Sales). Closed by default on page load; first
            // click opens, second click closes — clicking the title toggles, nothing
            // auto-loads or re-fetches on toggle since the data is already loaded
            // underneath regardless of visibility.
            function toggleCollapseCard(bodyId, headerEl) {
                const body = document.getElementById(bodyId);
                if (!body) return;
                const isOpen = body.style.display !== 'none';
                body.style.display = isOpen ? 'none' : '';
                if (headerEl) headerEl.classList.toggle('is-open', !isOpen);
            }

            function loadSalesTopProducts(period) {
                const params = period ? {
                    limit: 10,
                    period
                } : {
                    limit: 10
                };
                apiGet('get_top_products', params).then(top => {
                    if (!top?.success) return;
                    const tops = top.data;
                    const el = document.getElementById('top-list');
                    if (!el) return;
                    el.innerHTML = tops.length ? tops.map((p, i) => {
                        const rc = i === 0 ? 'gold' : i === 1 ? 'silver' : i === 2 ? 'bronze' : '';
                        const imgEl = p.has_image ? '<img src="' + prodImgUrl(p.id, p.updated_at) + '" loading="lazy" style="width:100%;height:100%;object-fit:cover;" onerror="imgFallback(this)"/>' : '<img src="' + DEFAULT_PRODUCT_IMG + '" class="default-prod-img" alt="">';
                        return '<div class="top-row">' +
                            '<div class="top-rank ' + rc + '">' + (i + 1) + '</div>' +
                            '<div class="top-img">' + imgEl + '</div>' +
                            '<div class="top-info"><div class="top-name">' + p.name + '</div><div class="top-sales">' + (p.category_name || '') + ' · ' + p.total_sold + ' sold</div></div>' +
                            '<div class="top-rev">' + CUR + parseFloat(p.total_revenue).toFixed(2) + '</div>' +
                            '</div>';
                    }).join('') : '<div class="empty-state"><div class="empty-icon">📊</div><div class="empty-text">No sales yet</div></div>';
                });
            }

            function loadTx() {
                const dateFrom = document.getElementById('date-from-filter')?.value || '';
                const dateTo = document.getElementById('date-to-filter')?.value || '';
                // If neither bound is set, fetch ALL transactions (no filter params)
                const params = {};
                if (dateFrom) params.date_from = dateFrom;
                if (dateTo) params.date_to = dateTo;
                apiGet('get_transactions', params).then(r => {
                    if (!r?.success) return;
                    txData = r.data;
                    const labelEl = document.getElementById('tx-label');
                    let rangeLabel = ' (all time)';
                    if (dateFrom && dateTo) rangeLabel = dateFrom === dateTo ? ' on ' + dateFrom : ' from ' + dateFrom + ' to ' + dateTo;
                    else if (dateFrom) rangeLabel = ' from ' + dateFrom;
                    else if (dateTo) rangeLabel = ' up to ' + dateTo;
                    if (labelEl) labelEl.textContent = txData.length + ' transaction(s)' + rangeLabel;
                    // Reflect the active range on the dropdown button itself
                    const rangeBtnLabel = document.getElementById('date-range-label');
                    if (rangeBtnLabel) rangeBtnLabel.textContent = (dateFrom || dateTo) ? rangeLabel.trim() : 'Filter by Date';
                    const body = document.getElementById('tx-body');
                    const emptyEl = document.getElementById('tx-empty');
                    if (!txData.length) {
                        if (body) body.innerHTML = '';
                        if (emptyEl) emptyEl.style.display = 'block';
                        return;
                    }
                    if (emptyEl) emptyEl.style.display = 'none';
                    if (body) {
                        body.innerHTML = txData.map((tx, i) => {
                            const voided = parseFloat(tx.voided_total || 0);
                            const netTotal = tx.net_total != null ? parseFloat(tx.net_total) : parseFloat(tx.total);
                            // Whole-order void (Sales History "Void Order" button) takes
                            // priority over the partial-line-void display below — the spec
                            // wants the ENTIRE cell replaced with "₱0.00 VOIDED" and the
                            // original price struck through, not a running net total.
                            const totalCell = tx.status === 'VOIDED' ?
                                '<span style="text-decoration:line-through;color:var(--text3);font-size:.78rem;">' + CUR + parseFloat(tx.total).toFixed(2) + '</span><br>' +
                                '<span style="color:var(--danger);font-weight:800;">' + CUR + '0.00 VOIDED</span>' :
                                voided > 0 ?
                                '<span style="text-decoration:line-through;color:var(--text3);font-size:.75rem;">' + CUR + parseFloat(tx.total).toFixed(2) + '</span><br>' +
                                '<span style="color:var(--accent);font-weight:700;">' + CUR + netTotal.toFixed(2) + '</span> ' +
                                '<span style="color:var(--danger);font-size:.68rem;font-weight:700;">VOIDED ' + CUR + voided.toFixed(2) + '</span>' :
                                '<span style="color:var(--accent);font-weight:700;">' + CUR + parseFloat(tx.total).toFixed(2) + '</span>';
                            return '<tr>' +
                                '<td>' + (txData.length - i) + '</td>' +
                                '<td style="font-weight:700;">' + tx.order_ref + '</td>' +
                                '<td>' + (tx.items || []).length + ' item(s)</td>' +
                                '<td>' + totalCell + '</td>' +
                                '<td>' + CUR + parseFloat(tx.cash).toFixed(2) + '</td>' +
                                '<td style="color:var(--green);font-weight:600;">' + CUR + parseFloat(tx.change).toFixed(2) + '</td>' +
                                '<td>' + (tx.cashier || '—') + '</td>' +
                                '<td style="color:var(--text3);font-size:.78rem;">' + fmtDate(tx.created_at) + '</td>' +
                                '<td style="display:flex;gap:5px;">' + '<button type="button" class="btn btn-secondary btn-sm" onclick="viewTx(' + tx.id + ')">View</button>' + '<button type="button" class="btn btn-danger btn-sm" onclick="deleteTx(' + tx.id + ',' + jsAttr(tx.order_ref) + ')">🗑️</button>' + '</td>' +
                                '</tr>';
                        }).join('');
                    }
                });
            }

            function viewTx(id) {
                const tx = txData.find(t => t.id === id);
                if (!tx) return;
                const items = tx.items || [];
                const netTotal = tx.net_total != null ? parseFloat(tx.net_total) : parseFloat(tx.total);
                const voided = parseFloat(tx.voided_total || 0);
                const hasVoidableItems = items.some(it => (it.quantity - (it.voided_qty || 0)) > 0);
                document.getElementById('tx-modal-title').textContent = 'Order #' + tx.order_ref;
                document.getElementById('tx-modal-body').innerHTML =
                    '<div style="font-size:.8rem;color:var(--text3);margin-bottom:14px;">' + fmtDate(tx.created_at) + ' · Cashier: ' + (tx.cashier || '—') + '</div>' +
                    '<table style="width:100%;border-collapse:collapse;font-size:.85rem;margin-bottom:14px;">' +
                    '<thead><tr style="border-bottom:2px solid var(--border);"><th style="padding:6px;text-align:left;">Item</th><th style="padding:6px;text-align:center;">Qty</th><th style="padding:6px;text-align:right;">Subtotal</th></tr></thead>' +
                    '<tbody>' + items.map(it => {
                        const voidedQty = it.voided_qty || 0;
                        // Full product detail set (Category, Brand, Supplier, Barcode,
                        // Unit Size, Description) isn't stored per-sale in transaction_items,
                        // so it's looked up here from the current product record by
                        // product_id — reflects the product's details as they stand now,
                        // not necessarily exactly as they were at sale time. Falls back to
                        // just the item name (as already recorded on the sale) if the
                        // product was since deleted.
                        const prod = allProds.find(p => p.id === it.product_id);
                        const detailParts = [];
                        // "Sold at" comes straight from the transaction line itself (it.price)
                        // — that IS the actual historical price charged on this sale, unlike
                        // everything else here which is looked up from the current product
                        // record. Cost Price and current Selling Price aren't stored per-sale
                        // at all, so those two carry the same "as of today" caveat as the
                        // rest of this block.
                        detailParts.push('Sold at: ' + CUR + parseFloat(it.price).toFixed(2));
                        if (prod) {
                            const curPrice = parseFloat(prod.price || 0);
                            if (!isNaN(curPrice) && Math.abs(curPrice - parseFloat(it.price)) > 0.004) {
                                detailParts.push('Current Price: ' + CUR + curPrice.toFixed(2));
                            }
                            if (prod.cost_price !== null && prod.cost_price !== undefined && prod.cost_price !== '') {
                                detailParts.push('Cost Price: ' + CUR + parseFloat(prod.cost_price).toFixed(2));
                            }
                            if (prod.category_name) detailParts.push('Category: ' + escapeHtml(prod.category_name));
                            if (prod.brand) detailParts.push('Brand: ' + escapeHtml(prod.brand));
                            if (prod.supplier) detailParts.push('Supplier: ' + escapeHtml(prod.supplier));
                            if (prod.unit_type) detailParts.push(escapeHtml(formatUnitSizeLabel(prod.unit_type, prod.unit_size)));
                            if (prod.barcode) detailParts.push('SKU: ' + escapeHtml(prod.barcode));
                            if (prod.description) detailParts.push(escapeHtml(prod.description.length > 42 ? prod.description.slice(0, 42) + '…' : prod.description));
                        }
                        const detailLine = detailParts.length ?
                            '<div style="font-size:.72rem;color:var(--text3);margin-top:2px;">' + detailParts.join(' · ') + '</div>' :
                            (!prod ? '<div style="font-size:.72rem;color:var(--text3);margin-top:2px;font-style:italic;">Product details unavailable (deleted since this sale)</div>' : '');
                        const nameCell = it.product_name + (voidedQty > 0 ? ' <span style="color:var(--danger);font-size:.7rem;font-weight:700;">(' + voidedQty + ' voided)</span>' : '') + detailLine;
                        const line = voidedQty > 0 ?
                            '<td style="padding:6px;">' + nameCell + '</td>' +
                            '<td style="padding:6px;text-align:center;">' + (it.quantity - voidedQty) + ' / ' + it.quantity + '</td>' +
                            '<td style="padding:6px;text-align:right;text-decoration:' + (it.quantity - voidedQty === 0 ? 'line-through' : 'none') + ';">' + CUR + parseFloat(it.subtotal).toFixed(2) + '</td>' :
                            '<td style="padding:6px;">' + nameCell + '</td>' +
                            '<td style="padding:6px;text-align:center;">' + it.quantity + '</td>' +
                            '<td style="padding:6px;text-align:right;">' + CUR + parseFloat(it.subtotal).toFixed(2) + '</td>';
                        return '<tr style="border-bottom:1px solid var(--border);">' + line + '</tr>';
                    }).join('') + '</tbody>' +
                    '</table>' +
                    (voided > 0 ?
                        '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:.8rem;text-decoration:line-through;color:var(--text3);"><span>Original Total</span><span>' + CUR + parseFloat(tx.total).toFixed(2) + '</span></div>' +
                        '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:.8rem;color:var(--danger);font-weight:700;"><span>Voided</span><span>-' + CUR + voided.toFixed(2) + '</span></div>' :
                        '') +
                    '<div style="display:flex;justify-content:space-between;padding:6px 0;font-weight:700;border-top:2px solid var(--border);"><span>' + (voided > 0 ? 'Net Total' : 'Total') + '</span><span>' + CUR + netTotal.toFixed(2) + '</span></div>' +
                    '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:.86rem;"><span>Cash</span><span>' + CUR + parseFloat(tx.cash).toFixed(2) + '</span></div>' +
                    '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:.86rem;color:var(--green);font-weight:600;"><span>Change</span><span>' + CUR + parseFloat(tx.change).toFixed(2) + '</span></div>' +
                    (tx.voids && tx.voids.length ?
                        '<div style="margin-top:12px;padding-top:10px;border-top:1px dashed var(--border);">' +
                        '<div style="font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--text3);margin-bottom:6px;">Void Audit Trail</div>' +
                        tx.voids.map(v =>
                            '<div style="font-size:.76rem;color:var(--text2);padding:2px 0;">Void #' + v.id + ' — ' + v.qty_voided + '× ' + escapeHtml(v.product_name) +
                            ' (' + CUR + parseFloat(v.amount_voided).toFixed(2) + ') · ' + escapeHtml(v.reason || '') + ' · ' + escapeHtml(v.voided_by_name || '—') + ' · ' + fmtDate(v.created_at) + '</div>'
                        ).join('') + '</div>' :
                        '') +
                    (hasVoidableItems ?
                        '<button type="button" class="btn btn-secondary btn-full" style="margin-top:14px;" onclick="openVoidOrderModal(\'' + tx.order_ref + '\')">🔒 Modify / Void Item</button>' :
                        '');
                openModal('tx-modal');
            }

            // PART 1 STEP 6 — print an updated receipt showing the remaining items,
            // recalculated total, and the voided line + amount returned.
            function printVoidReceipt(tx, voidData) {
                const win = window.open('', '_blank', 'width=380,height=650');
                if (!win) {
                    toast('Pop-up blocked — allow pop-ups to print the void receipt', 'warning');
                    return;
                }
                const esc = receiptEsc;
                const items = (tx.items || []);
                const isFullVoid = tx.status === 'VOIDED';

                // Same date/time formatting as the Payment Receipt — "now", since this is
                // printed at the moment the void is authorized, not at original sale time.
                const dt = new Date();
                const dateStr = String(dt.getMonth() + 1).padStart(2, '0') + '/' + String(dt.getDate()).padStart(2, '0') + '/' + dt.getFullYear();
                let hh = dt.getHours();
                const ampm = hh >= 12 ? 'PM' : 'AM';
                hh = hh % 12;
                if (hh === 0) hh = 12;
                const timeStr = String(hh).padStart(2, '0') + ':' + String(dt.getMinutes()).padStart(2, '0') + ' ' + ampm;

                // Same QTY | ITEM DESCRIPTION | PRICE | TOTAL table as the Payment
                // Receipt. Visual audit trail (Section 3): every line on the order is
                // listed, not just what's left. An untouched line prints one normal row.
                // A line with any voided_qty gets its remaining-active row as usual PLUS
                // a separate struck-through "VOIDED" row for the removed quantity, so the
                // full before/after picture is on one receipt.
                const itemRows = items.map(it => {
                    const voidedQty = it.voided_qty || 0;
                    const remaining = it.quantity - voidedQty;
                    let html = '';
                    if (remaining > 0) {
                        html += '<tr><td>' + remaining + ' x</td><td>' + esc(it.product_name) + '</td>' +
                            '<td class="right">' + CUR + parseFloat(it.price).toFixed(2) + '</td>' +
                            '<td class="right">' + fmt(remaining * it.price) + '</td></tr>';
                    }
                    if (voidedQty > 0) {
                        html += '<tr class="voided-row"><td>' + voidedQty + ' x</td><td>' + esc(it.product_name) + ' <span class="void-tag">VOIDED</span></td>' +
                            '<td class="right">' + CUR + parseFloat(it.price).toFixed(2) + '</td>' +
                            '<td class="right">-' + fmt(voidedQty * it.price) + '</td></tr>';
                    }
                    return html;
                }).join('');

                win.document.write(
                    '<!DOCTYPE html><html><head><style>' +
                    receiptBaseCSS() +
                    '</style></head><body>' +
                    '<div class="receipt-container">' +
                    receiptHeaderHTML(isFullVoid ? 'VOID RECEIPT — ORDER VOIDED' : 'VOID RECEIPT — ITEM(S) VOIDED') +
                    '<div class="receipt-row"><span>OR#: ' + esc(tx.order_ref) + '</span></div>' +
                    '<div class="divider"></div>' +
                    '<div class="receipt-row"><span>CASHIER: ' + esc(CASHIER_NAME) + '</span></div>' +
                    '<div class="receipt-row"><span>TERM: ' + esc(TERMINAL_ID) + '</span><span>' + dateStr + ' ' + timeStr + '</span></div>' +
                    '<div class="divider"></div>' +
                    '<table class="items">' +
                    '<colgroup><col class="qty"><col class="desc"><col class="price"><col class="total"></colgroup>' +
                    '<thead><tr><th>QTY</th><th>ITEM DESCRIPTION</th><th class="right">PRICE</th><th class="right">TOTAL</th></tr></thead>' +
                    '<tbody>' + itemRows + '</tbody>' +
                    '</table>' +
                    '<div class="divider"></div>' +
                    '<div class="void-band"><span>VOIDED — REFUNDED (THIS ACTION)</span><span>-' + fmt(voidData.voided_amount) + '</span></div>' +
                    '<div class="total-band"><span>' + (isFullVoid ? 'NEW TOTAL' : 'UPDATED TOTAL') + '</span><span>' + fmt(tx.net_total) + '</span></div>' +
                    '<div class="divider"></div>' +
                    receiptFooterHTML(['Thank You for Shopping!', 'Please keep receipt for returns.']) +
                    '</div>' +
                    '<script>window.onload=function(){window.print();}<\/script>' +
                    '</body></html>'
                );
                win.document.close();
            }

            // ── VOID ORDER WORKFLOW ("Void Order" toolbar button + Sales History "view" modal) ──
            // This is now the SINGLE void flow in the app — looks an order up directly
            // by its code, shows a Payment Receipt-styled summary to confirm it's the
            // right one, then lets the cashier pick specific line items (and how many
            // units of each) to void, gated behind an ADMIN password
            // (verifyAdminPassword() server-side — a cashier's own password is always
            // rejected, even if correct). The Sales History "view" modal's
            // "🔒 Modify / Void Item" button opens this same modal pre-filled with that
            // order's code (see openVoidOrderModal's prefillRef param below) instead of
            // running its own separate, older single-item flow.
            let voOrderData = null; // holds the looked-up order between Step 2 and Step 4
            let voSelections = {}; // { itemId: qty } — currently checked items and their void qty

            // prefillRef is optional — when the "🔒 Modify / Void" button is clicked
            // from a specific order's view (Sales History → View), the order code is
            // passed in here so this modal opens already looked-up, instead of making
            // the person retype a code they were already looking at.
            function openVoidOrderModal(prefillRef) {
                voOrderData = null;
                voSelections = {};
                const codeInput = document.getElementById('vo-order-code');
                const pwInput = document.getElementById('vo-password');
                const errEl = document.getElementById('vo-lookup-error');
                const summaryWrap = document.getElementById('vo-summary-wrap');
                const confirmBtn = document.getElementById('vo-confirm-btn');
                const itemsList = document.getElementById('vo-items-list');
                if (codeInput) codeInput.value = prefillRef || '';
                if (pwInput) pwInput.value = '';
                if (errEl) {
                    errEl.style.display = 'none';
                    errEl.textContent = '';
                }
                if (summaryWrap) summaryWrap.style.display = 'none';
                if (confirmBtn) confirmBtn.disabled = true;
                if (itemsList) itemsList.innerHTML = '';
                // Void Order must always be the only thing on screen — if the Cart (or
                // any other modal) happens to already be open when this is triggered
                // (e.g. scanning a receipt barcode to void an order), close it first so
                // it doesn't stack underneath and show through. A "scan to void" flow
                // should only ever surface the Void Order modal (plus its own toast) —
                // never the Cart too.
                document.querySelectorAll('.modal-overlay.open').forEach(m => {
                    if (m.id !== 'void-order-modal') m.classList.remove('open');
                });
                openModal('void-order-modal');
                if (prefillRef) {
                    verifyVoidOrderCode();
                } else {
                    setTimeout(() => codeInput?.focus(), 100);
                }
            }

            function closeVoidOrderModal() {
                voOrderData = null;
                voSelections = {};
                closeModal('void-order-modal');
            }

            // STEP 1 → STEP 2: look the order up by its code, reveal the summary, and
            // render the line-item selector for every item still available to void.
            function verifyVoidOrderCode() {
                const codeInput = document.getElementById('vo-order-code');
                const errEl = document.getElementById('vo-lookup-error');
                const summaryWrap = document.getElementById('vo-summary-wrap');
                const confirmBtn = document.getElementById('vo-confirm-btn');
                const verifyBtn = document.getElementById('vo-verify-btn');
                const code = (codeInput?.value || '').trim().toUpperCase();

                if (errEl) {
                    errEl.style.display = 'none';
                    errEl.textContent = '';
                }
                if (summaryWrap) summaryWrap.style.display = 'none';
                if (confirmBtn) confirmBtn.disabled = true;
                voOrderData = null;
                voSelections = {};

                if (!code) {
                    if (errEl) {
                        errEl.textContent = 'Enter an order code first';
                        errEl.style.display = 'block';
                    }
                    return;
                }

                setLoading(verifyBtn, true);
                apiGet('find_order_by_ref', {
                    order_ref: code
                }).then(r => {
                    setLoading(verifyBtn, false);
                    if (!r?.success) {
                        if (errEl) {
                            errEl.textContent = r?.error || 'Order not found';
                            errEl.style.display = 'block';
                        }
                        return;
                    }
                    voOrderData = r.data;
                    document.getElementById('vo-sum-ref').textContent = voOrderData.order_ref;
                    document.getElementById('vo-sum-cashier').textContent = voOrderData.cashier || '—';
                    document.getElementById('vo-sum-items').textContent = voOrderData.item_count + ' item(s)';
                    document.getElementById('vo-sum-total').textContent = fmt(voOrderData.total);
                    voRenderItemsList();
                    if (summaryWrap) summaryWrap.style.display = 'block';
                    updateVoidOrderConfirmState();
                    setTimeout(() => document.getElementById('vo-password')?.focus(), 100);
                });
            }

            // Renders one row per line item still available to void (remaining qty >
            // already-voided qty), each with a checkbox + a qty input capped at what's
            // actually left on that line. Fully-voided lines are skipped entirely —
            // there's nothing left on them to select.
            function voRenderItemsList() {
                const list = document.getElementById('vo-items-list');
                if (!list || !voOrderData) return;
                const items = (voOrderData.items || []).filter(it => (it.quantity - (it.voided_qty || 0)) > 0);
                if (!items.length) {
                    list.innerHTML = '<div style="padding:12px;text-align:center;color:var(--text3);font-size:.8rem;">No voidable items remain on this order.</div>';
                    return;
                }
                list.innerHTML = items.map(it => {
                    const remaining = it.quantity - (it.voided_qty || 0);
                    return '<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-bottom:1px solid var(--border);">' +
                        '<input type="checkbox" id="vo-chk-' + it.id + '" onchange="voToggleItem(' + it.id + ',' + remaining + ',this.checked)" style="width:18px;height:18px;flex:none;"/>' +
                        '<div style="flex:1;min-width:0;">' +
                        '<div style="font-size:.84rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(it.product_name) + '</div>' +
                        '<div style="font-size:.72rem;color:var(--text3);">' + fmt(it.price) + ' × ' + remaining + ' remaining</div>' +
                        '</div>' +
                        '<input type="number" id="vo-qty-' + it.id + '" min="1" max="' + remaining + '" value="' + remaining + '" disabled ' +
                        'onchange="voUpdateQty(' + it.id + ',' + remaining + ',this.value)" style="width:56px;padding:5px;border:1px solid var(--border);border-radius:6px;text-align:center;"/>' +
                        '</div>';
                }).join('');
            }

            // Checkbox toggled: add/remove that item from voSelections and enable/
            // disable its qty input. Defaults the qty to the full remaining amount —
            // the cashier can reduce it afterward if only voiding some units.
            function voToggleItem(itemId, remaining, checked) {
                const qtyInput = document.getElementById('vo-qty-' + itemId);
                if (checked) {
                    if (qtyInput) {
                        qtyInput.disabled = false;
                        qtyInput.value = remaining;
                    }
                    voSelections[itemId] = remaining;
                } else {
                    if (qtyInput) qtyInput.disabled = true;
                    delete voSelections[itemId];
                }
                updateVoidOrderConfirmState();
            }

            // Qty input changed on an already-checked row — clamp to [1, remaining] so
            // a cashier can't type something nonsensical, then keep voSelections in sync.
            function voUpdateQty(itemId, remaining, value) {
                let qty = parseInt(value, 10) || 1;
                qty = Math.max(1, Math.min(remaining, qty));
                const qtyInput = document.getElementById('vo-qty-' + itemId);
                if (qtyInput) qtyInput.value = qty;
                if (voSelections[itemId] !== undefined) voSelections[itemId] = qty;
                updateVoidOrderConfirmState();
            }

            // "Select All" — checks every voidable row at its full remaining quantity,
            // equivalent to a whole-order void in one click.
            function voSelectAll() {
                if (!voOrderData) return;
                const items = (voOrderData.items || []).filter(it => (it.quantity - (it.voided_qty || 0)) > 0);
                items.forEach(it => {
                    const remaining = it.quantity - (it.voided_qty || 0);
                    const chk = document.getElementById('vo-chk-' + it.id);
                    const qtyInput = document.getElementById('vo-qty-' + it.id);
                    if (chk) chk.checked = true;
                    if (qtyInput) {
                        qtyInput.disabled = false;
                        qtyInput.value = remaining;
                    }
                    voSelections[it.id] = remaining;
                });
                updateVoidOrderConfirmState();
            }

            // STEP 3 gate: Confirm Void stays disabled until at least one item is
            // selected AND a password has been typed.
            function updateVoidOrderConfirmState() {
                const confirmBtn = document.getElementById('vo-confirm-btn');
                const pw = document.getElementById('vo-password')?.value || '';
                const hasSelection = Object.keys(voSelections).length > 0;
                if (confirmBtn) confirmBtn.disabled = !(voOrderData && hasSelection && pw.trim().length > 0);
            }

            // STEP 4: admin-password-gated write. Voids exactly the selected
            // items/quantities, refunds their inventory, and updates the Sales History
            // row — "₱0.00 VOIDED" if that was every remaining item, otherwise a
            // struck-through original total next to the new net total. Then
            // automatically re-prints an updated receipt showing which lines are still
            // active and which are now voided.
            function confirmVoidOrder() {
                if (!voOrderData) return;
                const pw = document.getElementById('vo-password')?.value || '';
                const items = Object.entries(voSelections).map(([itemId, qty]) => ({
                    item_id: parseInt(itemId, 10),
                    qty
                }));
                if (!pw.trim() || !items.length) return;

                const confirmBtn = document.getElementById('vo-confirm-btn');
                setLoading(confirmBtn, true);
                apiPost('void_order_items', {
                    transaction_id: voOrderData.id,
                    password: pw,
                    items
                }).then(r => {
                    setLoading(confirmBtn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Void failed', 'error');
                        return;
                    }
                    toast('Order ' + r.data.order_ref + ' updated — ' + fmt(r.data.cash_due_to_customer) + ' due back to customer', 'success');
                    closeVoidOrderModal();
                    loadTx();
                    // Automatic print trigger (Section 3): re-issue the receipt right away
                    // using the full, fresh item list the backend just returned — no extra
                    // round trip needed since void_order_items already sends it back.
                    const txForPrint = {
                        order_ref: r.data.order_ref,
                        status: r.data.status,
                        items: r.data.items,
                        net_total: r.data.net_total,
                    };
                    printVoidReceipt(txForPrint, {
                        voided_amount: r.data.voided_amount
                    });
                });
            }


            function deleteTx(id, orderRef) {
                if (!confirm('Delete order #' + orderRef + '?\nThis cannot be undone.')) return;
                apiPost('delete_transaction', {
                    id
                }).then(r => {
                    if (!r?.success) {
                        toast(r?.error || 'Error deleting transaction', 'error');
                        return;
                    }
                    toast('Order #' + orderRef + ' deleted', 'success');
                    loadTx();
                });
            }

            function deleteAllTx() {
                // Only owner can do this — show confirm modal
                openModal('del-all-modal');
            }

            function confirmDeleteAll() {
                const btn = document.getElementById('confirm-del-all-btn');
                setLoading(btn, true);
                apiPost('delete_all_transactions', {}).then(r => {
                    setLoading(btn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Error deleting transactions', 'error');
                        return;
                    }
                    toast('All transaction history cleared', 'success');
                    closeModal('del-all-modal');
                    loadTx();
                });
            }

            function exportCSV() {
                if (!txData.length) {
                    // Try fetching all transactions for export if current view is empty
                    toast('Fetching all data for export…', 'default');
                    apiGet('get_transactions', {}).then(r => {
                        if (!r?.success || !r.data.length) {
                            toast('No transactions found in database', 'error');
                            return;
                        }
                        doExportCSV(r.data);
                    });
                    return;
                }
                doExportCSV(txData);
            }

            function doExportCSV(data) {
                const rows = [
                    ['Order Ref', 'Date', 'Product', 'Category', 'Qty', 'Voided Qty', 'Price', 'Subtotal', 'Order Total', 'Voided Amount', 'Net Total', 'Cash', 'Change', 'Day', 'Hour']
                ];
                data.forEach(tx => {
                    (tx.items || []).forEach(it => {
                        const d = new Date(tx.created_at);
                        rows.push([tx.order_ref, tx.created_at, it.product_name, it.category_name, it.quantity, it.voided_qty || 0, it.price, it.subtotal, tx.total, tx.voided_total || 0, tx.net_total != null ? tx.net_total : tx.total, tx.cash, tx.change, d.toLocaleDateString('en', {
                            weekday: 'long'
                        }), d.getHours()]);
                    });
                });
                const csv = rows.map(r => r.map(v => '"' + v + '"').join(',')).join('\n');
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob([csv], {
                    type: 'text/csv'
                }));
                a.download = 'canteen_data_' + new Date().toISOString().slice(0, 10) + '.csv';
                a.click();
                toast('CSV exported! ' + data.length + ' transactions', 'success');
            }

            function exportJSON() {
                if (!txData.length) {
                    toast('Fetching all data for export…', 'default');
                    apiGet('get_transactions', {}).then(r => {
                        if (!r?.success || !r.data.length) {
                            toast('No transactions found in database', 'error');
                            return;
                        }
                        doExportJSON(r.data);
                    });
                    return;
                }
                doExportJSON(txData);
            }

            function doExportJSON(data) {
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], {
                    type: 'application/json'
                }));
                a.download = 'canteen_data_' + new Date().toISOString().slice(0, 10) + '.json';
                a.click();
                toast('JSON exported! ' + data.length + ' transactions', 'success');
            }

            // ════════════════════════════════
            // ANALYTICS PAGE
            // ════════════════════════════════
            // ════════════════════════════════════════════════════════
            // FORECAST PAGE
            // ════════════════════════════════════════════════════════
            let _fcPeriod = 'daily';
            let _fcStoresLoaded = false;

            // Fetches the real list of trained store models from the ML API (via the
            // get_ml_stores PHP action) and fills the dropdown with it, instead of the
            // old hardcoded BAR-01..BAR-04 pills that didn't reflect what was actually
            // trained.
            async function loadStoreDropdown(forceRefresh) {
                const sel = document.getElementById('fc-store-select');
                const btn = document.getElementById('fc-store-refresh-btn');
                if (!sel) return;
                if (btn && forceRefresh) {
                    btn.disabled = true;
                    btn.textContent = '⏳';
                }

                const params = forceRefresh ? {
                    refresh: 1
                } : {};
                const r = await apiGet('get_ml_stores', params);
                const stores = (r?.success && Array.isArray(r.data?.stores)) ? r.data.stores : [];

                if (btn) {
                    btn.disabled = false;
                    btn.textContent = '🔄';
                }

                if (!stores.length) {
                    sel.innerHTML = '<option value="BAR-01">BAR-01 (default)</option>';
                } else {
                    sel.innerHTML = stores.map(s => {
                        const mape = (s.mape !== null && s.mape !== undefined) ? ' — MAPE ' + s.mape + '%' : '';
                        return '<option value="' + s.store_id + '">' + s.store_id + mape + '</option>';
                    }).join('');
                }

                const countEl = document.getElementById('fc-store-count');
                if (countEl) countEl.textContent = stores.length ? '(' + stores.length + ' stores available)' : '';

                // Keep whatever was previously selected (e.g. across period tab switches),
                // otherwise default to the first store in the list.
                const prev = document.getElementById('fc-store-id')?.value;
                const toSelect = (prev && stores.some(s => s.store_id === prev)) ? prev : sel.options[0]?.value;
                if (toSelect) {
                    sel.value = toSelect;
                    onFcStoreChange(toSelect, /*skipReload=*/ true);
                }

                if (r?.data?.source === 'local' && r.data.message) {
                    toast('📡 ' + r.data.message, 'warning');
                } else if (forceRefresh && stores.length > 1) {
                    toast('✅ Loaded ' + stores.length + ' stores', 'success');
                }

                _fcStoresLoaded = true;
                if (forceRefresh) runAllForecasts();
            }

            function onFcStoreChange(id, skipReload) {
                if (!id) return;
                document.getElementById('fc-store-id').value = id;
                const disp = document.getElementById('fc-store-display');
                if (disp) disp.textContent = id;
                if (!skipReload && _fcStoresLoaded) runAllForecasts();
            }

            let _fcResults = [];
            let _fcFiltered = [];


            function forecastInit() {
                if (cur_page !== 'forecast') return;
                // Load the real store list first, THEN run forecasts for whichever store
                // ends up selected (loadStoreDropdown sets fc-store-id but doesn't
                // auto-run, to avoid a double fetch on page load).
                loadStoreDropdown().then(runAllForecasts);
            }

            function setFcPeriod(period) {
                _fcPeriod = period;
                ['daily', 'weekly', 'monthly'].forEach(p => {
                    const btn = document.getElementById('fc-tab-' + p);
                    if (btn) btn.className = p === period ? 'btn btn-primary' : 'btn btn-secondary';
                });
                const lbl = document.getElementById('fc-table-period-label');
                if (lbl) lbl.textContent = '(' + period.charAt(0).toUpperCase() + period.slice(1) + ')';
                const periodLbl = document.getElementById('fc-period-label');
                if (periodLbl) periodLbl.textContent = period.charAt(0).toUpperCase() + period.slice(1);
                // Re-render existing results with new period if already loaded
                if (_fcResults.length) renderFcTable(_fcResults);
                else runAllForecasts();
            }

            async function runAllForecasts() {
                const btn = document.getElementById('fc-run-btn');
                const wrap = document.getElementById('fc-table-wrap');
                const storeId = document.getElementById('fc-store-id')?.value.trim() || 'BAR-01';
                if (btn) {
                    btn.disabled = true;
                    btn.textContent = '⏳ Forecasting…';
                }
                if (wrap) wrap.innerHTML = '<div class="fc-loading">🔮 Loading forecast… (cached results load instantly; a cold API falls back to your sales history in a few seconds)</div>';

                const r = await apiGet('get_all_forecasts', {
                    period: _fcPeriod,
                    store_id: storeId
                });

                if (btn) {
                    btn.disabled = false;
                    btn.textContent = '🔮 Run Forecast';
                }

                if (!r?.success) {
                    if (wrap) wrap.innerHTML = '<div class="empty-state"><div class="empty-icon">⚠️</div><div class="empty-text">' + (r?.error || 'Could not reach forecast API. Check your internet connection.') + '</div></div>';
                    return;
                }

                _fcResults = r.data.forecasts || [];
                _fcFiltered = [..._fcResults];

                // Show a friendly banner if we're running on the local offline fallback
                const existingBanner = document.getElementById('fc-offline-banner');
                if (existingBanner) existingBanner.remove();
                if (r.data.source === 'local' && wrap) {
                    const banner = document.createElement('div');
                    banner.id = 'fc-offline-banner';
                    banner.style.cssText = 'background:rgba(244,160,36,.12);border:1.5px solid rgba(244,160,36,.4);border-radius:10px;padding:10px 14px;margin-bottom:12px;font-size:.83rem;color:#7a5500;';
                    banner.innerHTML = '📡 <strong>Offline mode:</strong> ' + (r.data.message || 'ML API unreachable — showing estimates from your own sales history.');
                    wrap.parentElement?.insertBefore(banner, wrap);
                }

                // Update summary cards
                const totalPred = _fcResults.reduce((s, f) => s + (f.predicted_qty || 0), 0);
                const totalRestock = _fcResults.reduce((s, f) => s + (f.restock_suggest || 0), 0);
                const totalSales = r.data.total_predicted_sales || 0;
                document.getElementById('fc-count').textContent = _fcResults.length;
                document.getElementById('fc-total-pred').textContent = totalPred + ' units';
                document.getElementById('fc-total-restock').textContent = totalRestock + ' units';
                const lbl = document.getElementById('fc-period-label');
                if (lbl) lbl.textContent = _fcPeriod.charAt(0).toUpperCase() + _fcPeriod.slice(1);
                const summary = document.getElementById('fc-summary');
                if (summary) summary.style.display = 'grid';

                // Show ML sales forecast mini-chart if data available
                const mlRaw = r.data.ml_forecast_raw || [];
                if (mlRaw.length) renderFcSalesChart(mlRaw, r.data.store_id || 'BAR-01', totalSales, !!r.data.no_period_transactions);

                renderFcTable(_fcResults);
                renderRestockPanel(_fcResults);
            }

            function renderFcSalesChart(forecast, storeId, totalSales, noPeriodTx) {
                let chartEl = document.getElementById('fc-ml-chart');
                if (!chartEl) {
                    const card = document.createElement('div');
                    card.className = 'card';
                    card.style.cssText = 'margin-bottom:20px;';
                    card.innerHTML = '<div class="card-title">📈 ML Sales Forecast — Store: <span id="fc-chart-store"></span></div>' +
                        '<div style="font-size:.82rem;color:var(--text2);margin-bottom:10px;">Predicted revenue from <strong>pos-ml-api.onrender.com</strong></div>' +
                        '<div id="fc-ml-zero-note" style="display:none;font-size:.8rem;color:var(--text3);background:var(--surface2);border-radius:8px;padding:8px 12px;margin-bottom:10px;"></div>' +
                        '<div id="fc-ml-chart" style="overflow-x:auto;"></div>' +
                        '<div style="margin-top:8px;font-size:.82rem;color:var(--text3);">Total predicted: <strong id="fc-total-sales-val" style="color:var(--green);"></strong></div>';
                    const tbl = document.getElementById('fc-table-wrap')?.closest('.card');
                    if (tbl) tbl.parentNode.insertBefore(card, tbl);
                    chartEl = document.getElementById('fc-ml-chart');
                }
                document.getElementById('fc-chart-store').textContent = storeId;
                document.getElementById('fc-total-sales-val').textContent = '₱' + parseFloat(totalSales).toLocaleString('en-PH', {
                    minimumFractionDigits: 2
                });

                // No sales logged yet for the period currently being viewed (Daily/Weekly/
                // Monthly) — the chart shows a flat zero line instead of the ML model's
                // number, since that model has no idea whether THIS store made any sales
                // in that window. Per-product restock suggestions below are unaffected.
                const noteEl = document.getElementById('fc-ml-zero-note');
                if (noteEl) {
                    if (noPeriodTx) {
                        noteEl.style.display = 'block';
                        noteEl.textContent = '📭 No transactions logged yet for this period — showing ₱0 instead of a forecast until there\'s real sales data to predict from.';
                    } else {
                        noteEl.style.display = 'none';
                    }
                }

                chartEl.innerHTML = buildLineChartSVG(
                    forecast.map(d => ({
                        x: (d.date || '').slice(5),
                        y: parseFloat(d.predicted_sales) || 0,
                        full: d.date || ''
                    }))
                );
            }

            // Builds a responsive SVG line chart: smooth-ish polyline, gradient fill
            // under the curve, dots at each point, and a native <title> tooltip on
            // hover (no extra JS libraries needed). Replaces the old flex/div bar chart.
            function buildLineChartSVG(points, opts = {}) {
                if (!points.length) return '<div class="empty-state" style="padding:20px;"><div class="empty-text">No forecast data yet.</div></div>';

                const W = Math.max(320, points.length * 56); // width grows with point count, scrolls on small screens
                const H = opts.height || 160;
                const padL = 44,
                    padR = 14,
                    padT = 16,
                    padB = 26;
                const plotW = W - padL - padR;
                const plotH = H - padT - padB;

                const vals = points.map(p => p.y);
                const maxVal = Math.max(...vals, 0);
                const minVal = Math.min(...vals, 0);
                const range = (maxVal - minVal) || 1;

                const xAt = i => padL + (points.length === 1 ? plotW / 2 : (i / (points.length - 1)) * plotW);
                const yAt = v => padT + plotH - ((v - minVal) / range) * plotH;

                const coords = points.map((p, i) => [xAt(i), yAt(p.y)]);
                const linePath = coords.map((c, i) => (i === 0 ? 'M' : 'L') + c[0].toFixed(1) + ',' + c[1].toFixed(1)).join(' ');
                const areaPath = linePath +
                    ' L' + coords[coords.length - 1][0].toFixed(1) + ',' + (padT + plotH) +
                    ' L' + coords[0][0].toFixed(1) + ',' + (padT + plotH) + ' Z';

                // Light horizontal gridlines (0%, 50%, 100% of range)
                const gridLines = [0, 0.5, 1].map(t => {
                    const y = padT + plotH * t;
                    const label = (maxVal - range * t);
                    const labelStr = label >= 1000 ? (label / 1000).toFixed(1) + 'k' : label.toFixed(0);
                    return '<line x1="' + padL + '" y1="' + y.toFixed(1) + '" x2="' + (W - padR) + '" y2="' + y.toFixed(1) + '" stroke="var(--border)" stroke-width="1" stroke-dasharray="3,3"/>' +
                        '<text x="' + (padL - 8) + '" y="' + (y + 3).toFixed(1) + '" font-size="9" fill="var(--text3)" text-anchor="end">₱' + labelStr + '</text>';
                }).join('');

                const dotsAndLabels = points.map((p, i) => {
                    const [x, y] = coords[i];
                    const val = p.y >= 1000 ? (p.y / 1000).toFixed(1) + 'k' : p.y.toFixed(0);
                    return '<circle cx="' + x.toFixed(1) + '" cy="' + y.toFixed(1) + '" r="3.5" fill="var(--accent)" stroke="#fff" stroke-width="1.5">' +
                        '<title>' + (p.full || p.x) + ': ₱' + p.y.toFixed(2) + '</title>' +
                        '</circle>' +
                        '<text x="' + x.toFixed(1) + '" y="' + (y - 9).toFixed(1) + '" font-size="9" font-weight="700" fill="var(--text2)" text-anchor="middle">₱' + val + '</text>' +
                        '<text x="' + x.toFixed(1) + '" y="' + (H - 8) + '" font-size="9" fill="var(--text3)" text-anchor="middle">' + p.x + '</text>';
                }).join('');

                return '<svg viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '" style="min-width:' + W + 'px;display:block;">' +
                    '<defs><linearGradient id="fcLineFill" x1="0" y1="0" x2="0" y2="1">' +
                    '<stop offset="0%" stop-color="var(--accent)" stop-opacity="0.28"/>' +
                    '<stop offset="100%" stop-color="var(--accent)" stop-opacity="0"/>' +
                    '</linearGradient></defs>' +
                    gridLines +
                    '<path d="' + areaPath + '" fill="url(#fcLineFill)" stroke="none"/>' +
                    '<path d="' + linePath + '" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>' +
                    dotsAndLabels +
                    '</svg>';
            }


            function renderFcTable(rows) {
                const wrap = document.getElementById('fc-table-wrap');
                if (!wrap) return;
                if (!rows.length) {
                    wrap.innerHTML = '<div class="empty-state"><div class="empty-icon">📭</div><div class="empty-text">No products with sales history found. Add products and make some sales first.</div></div>';
                    return;
                }

                const periodLabel = _fcPeriod.charAt(0).toUpperCase() + _fcPeriod.slice(1);
                const tbl = document.createElement('table');
                tbl.innerHTML =
                    '<thead><tr>' +
                    '<th>Product</th>' +
                    '<th>Category</th>' +
                    '<th>Price</th>' +
                    '<th>Store Stock</th>' +
                    '<th>Predicted (' + periodLabel + ')</th>' +
                    '<th>Restock Suggest</th>' +
                    '<th>Status</th>' +
                    '</tr></thead>';

                const tbody = document.createElement('tbody');
                rows.forEach(f => {
                    const storeQ = f.store_quantity || 0;
                    const pred = f.predicted_qty || 0;
                    const restock = f.restock_suggest || 0;

                    let pillClass, pillLabel;
                    if (storeQ >= pred) {
                        pillClass = 'fc-pill-ok';
                        pillLabel = '✅ Sufficient';
                    } else if (storeQ >= pred * 0.5) {
                        pillClass = 'fc-pill-warn';
                        pillLabel = '⚠️ Low';
                    } else {
                        pillClass = 'fc-pill-danger';
                        pillLabel = '🚨 Restock Now';
                    }

                    const tr = document.createElement('tr');
                    tr.innerHTML =
                        '<td style="font-weight:600;">' + f.name + '</td>' +
                        '<td style="color:var(--text3);font-size:.8rem;">' + (f.category || '—') + '</td>' +
                        '<td>' + CUR + parseFloat(f.price || 0).toFixed(2) + '</td>' +
                        '<td style="font-weight:600;">' + storeQ + '</td>' +
                        '<td style="font-weight:700;color:var(--primary);">' + pred + ' units</td>' +
                        '<td style="font-weight:700;color:' + (restock > 0 ? 'var(--danger)' : 'var(--green)') + ';">' + restock + ' units</td>' +
                        '<td><span class="fc-pill ' + pillClass + '">' + pillLabel + '</span></td>';
                    tbody.appendChild(tr);
                });

                tbl.appendChild(tbody);
                wrap.innerHTML = '';
                wrap.appendChild(tbl);
            }

            function filterFcTable() {
                const q = (document.getElementById('fc-search')?.value || '').toLowerCase();
                _fcFiltered = q ? _fcResults.filter(f => f.name.toLowerCase().includes(q) || (f.category || '').toLowerCase().includes(q)) : [..._fcResults];
                renderFcTable(_fcFiltered);
            }

            function renderRestockPanel(rows) {
                const panel = document.getElementById('fc-restock-panel');
                const list = document.getElementById('fc-restock-list');
                if (!panel || !list) return;

                const needRestock = rows.filter(f => (f.restock_suggest || 0) > 0)
                    .sort((a, b) => b.restock_suggest - a.restock_suggest);

                if (!needRestock.length) {
                    panel.style.display = 'none';
                    return;
                }

                panel.style.display = 'block';
                list.innerHTML = needRestock.map(f =>
                    '<div class="fc-restock-item">' +
                    '<div>' +
                    '<div style="font-weight:700;">' + f.name + '</div>' +
                    '<div style="font-size:.78rem;color:var(--text3);">' + (f.category || '') + ' · Store stock: ' + (f.store_quantity || 0) + ' · Predicted: ' + f.predicted_qty + '</div>' +
                    '</div>' +
                    '<div style="text-align:right;">' +
                    '<div style="font-size:1.2rem;font-weight:800;color:var(--danger);">+' + f.restock_suggest + ' units</div>' +
                    '<div style="font-size:.73rem;color:var(--text3);">recommended restock</div>' +
                    '</div>' +
                    '<button type="button" class="btn btn-primary btn-sm" onclick="openTransferModalFor(' + f.id + ')">🔄 Transfer to Store</button>' +
                    '</div>'
                ).join('');
            }

            // ── AUTOCOMPLETE: Quick Single Forecast (Product Name / Category) &
            // Product Combo Recommendations (Cart Items) ──
            // All three reuse the same lightweight product/category cache — loaded
            // once on first use per page visit, not on every keystroke — and the
            // same .cat-dropdown panel styling already used for the Add Product
            // category picker.
            let _fcProductsCache = null; // [{name, category_name, price}, ...]
            let _fcCategoriesCache = null; // [{id, name}, ...]

            async function ensureFcProductsLoaded() {
                if (_fcProductsCache) return _fcProductsCache;
                const r = await apiGet('get_products');
                _fcProductsCache = (r?.success && Array.isArray(r.data)) ?
                    r.data.map(p => ({
                        name: p.name,
                        category_name: p.category_name || '',
                        price: p.price ?? ''
                    })) : [];
                return _fcProductsCache;
            }

            async function ensureFcCategoriesLoaded() {
                if (_fcCategoriesCache) return _fcCategoriesCache;
                const r = await apiGet('get_categories');
                _fcCategoriesCache = (r?.success && Array.isArray(r.data)) ? r.data : [];
                return _fcCategoriesCache;
            }

            // Product Name field — selecting a suggestion also fills in that
            // product's own Category and Price, since those two are what the
            // forecast model actually uses alongside the name.
            async function onFcProductInput() {
                const panel = document.getElementById('fc-product-dropdown');
                const typed = (document.getElementById('fc-product')?.value || '').trim().toLowerCase();
                const products = await ensureFcProductsLoaded();
                const matches = rankAutocompleteMatches(products, typed, p => p.name).slice(0, 20);
                if (!panel) return;
                panel.innerHTML = matches.length ?
                    matches.map(p =>
                        '<div class="cat-dropdown-item" onmousedown="event.preventDefault();selectFcProduct(' +
                        jsAttr(p.name) + ',' + jsAttr(p.category_name) + ',' + jsAttr(p.price) + ')">' +
                        escapeHtml(p.name) +
                        (p.category_name ? '<span style="color:var(--text3);font-size:.78rem;"> — ' + escapeHtml(p.category_name) + '</span>' : '') +
                        '</div>'
                    ).join('') :
                    '<div class="cat-dropdown-empty">No matching products yet</div>';
                panel.classList.add('open');
            }

            function selectFcProduct(name, categoryName, price) {
                document.getElementById('fc-product').value = name;
                if (categoryName) document.getElementById('fc-category').value = categoryName;
                if (price !== '' && price !== null && price !== undefined) document.getElementById('fc-price').value = price;
                document.getElementById('fc-product-dropdown')?.classList.remove('open');
            }

            // Category field — suggests from your actual category list.
            async function onFcCategoryInput() {
                const panel = document.getElementById('fc-category-dropdown');
                const typed = (document.getElementById('fc-category')?.value || '').trim().toLowerCase();
                const cats = await ensureFcCategoriesLoaded();
                const matches = rankAutocompleteMatches(cats, typed, c => c.name).slice(0, 20);
                if (!panel) return;
                panel.innerHTML = matches.length ?
                    matches.map(c =>
                        '<div class="cat-dropdown-item" onmousedown="event.preventDefault();selectFcCategory(' + jsAttr(c.name) + ')">' + escapeHtml(c.name) + '</div>'
                    ).join('') :
                    '<div class="cat-dropdown-empty">No matching categories yet</div>';
                panel.classList.add('open');
            }

            function selectFcCategory(name) {
                document.getElementById('fc-category').value = name;
                document.getElementById('fc-category-dropdown')?.classList.remove('open');
            }

            // Cart Items field — comma-separated, so suggestions filter on whatever
            // is typed after the LAST comma, and picking one just completes that
            // one item (leaving everything typed before it untouched) and leaves a
            // ", " ready for the next item.
            async function onComboCartInput() {
                const panel = document.getElementById('combo-cart-dropdown');
                const full = document.getElementById('combo-cart')?.value || '';
                const parts = full.split(',');
                const current = parts[parts.length - 1].trim().toLowerCase();
                const products = await ensureFcProductsLoaded();
                const matches = rankAutocompleteMatches(products, current, p => p.name).slice(0, 20);
                if (!panel) return;
                panel.innerHTML = matches.length ?
                    matches.map(p =>
                        '<div class="cat-dropdown-item" onmousedown="event.preventDefault();selectComboCartItem(' + jsAttr(p.name) + ')">' + escapeHtml(p.name) + '</div>'
                    ).join('') :
                    '<div class="cat-dropdown-empty">No matching products yet</div>';
                panel.classList.add('open');
            }

            function selectComboCartItem(name) {
                const input = document.getElementById('combo-cart');
                const cleanParts = (input.value || '').split(',').map(s => s.trim()).filter(Boolean);
                if (cleanParts.length === 0) {
                    cleanParts.push(name); // first item typed
                } else {
                    cleanParts[cleanParts.length - 1] = name; // completes whatever was being typed
                }
                input.value = cleanParts.join(', ') + ', ';
                input.focus();
                document.getElementById('combo-cart-dropdown')?.classList.remove('open');
            }

            // Close any of the three new dropdowns on an outside click.
            document.addEventListener('click', e => {
                [
                    ['fc-product-dropdown', 'fc-product'],
                    ['fc-category-dropdown', 'fc-category'],
                    ['combo-cart-dropdown', 'combo-cart']
                ].forEach(([panelId, inputId]) => {
                    const panel = document.getElementById(panelId);
                    const input = document.getElementById(inputId);
                    if (panel && panel.classList.contains('open') && e.target !== input && !panel.contains(e.target)) {
                        panel.classList.remove('open');
                    }
                });
            });

            // ── KEYBOARD NAVIGATION for autocomplete dropdowns ──
            // Every ".cat-dropdown" panel (Product Name, Category, Cart Items on the
            // Forecast page, and the Category picker in Add/Edit Product) is built the
            // same way: a list of ".cat-dropdown-item" rows, each wired only to
            // onmousedown so a click selects it. That meant the panel was completely
            // unusable from a keyboard — arrow keys did nothing (the browser just
            // moved the text cursor), Enter did nothing (nothing was "selected"), and
            // a long list couldn't be reached without a mouse. This one handler, wired
            // via onkeydown on each input, fixes all of them at once:
            //   ↓ / ↑   moves a highlighted row (wrapping at the ends) and scrolls it
            //           into view, so a tall list never gets stuck off-screen.
            //   Enter   "clicks" the highlighted row — dispatching the same mousedown
            //           event the row's own onmousedown handler already listens for,
            //           so it reuses each dropdown's existing select function exactly
            //           as if the person had clicked it, instead of duplicating that
            //           logic here per-dropdown. If nothing is highlighted yet, Enter
            //           is left alone (e.g. so Add Product's Save button still works).
            //   Escape  closes the panel without selecting anything.
            // Highlighting reuses the .cat-dropdown-item.active CSS rule that already
            // existed (same look as :hover) but was never actually toggled by any code.
            function dropdownKeyNav(e, panelId) {
                const panel = document.getElementById(panelId);
                if (!panel || !panel.classList.contains('open')) return;
                const items = Array.from(panel.querySelectorAll('.cat-dropdown-item'));
                if (!items.length) return;
                const curIdx = items.findIndex(i => i.classList.contains('active'));
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    setDropdownActiveItem(items, curIdx < 0 ? 0 : (curIdx + 1) % items.length);
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    setDropdownActiveItem(items, curIdx < 0 ? items.length - 1 : (curIdx - 1 + items.length) % items.length);
                } else if (e.key === 'Enter') {
                    if (curIdx < 0) return; // nothing highlighted — don't hijack Enter from anything else on the page
                    e.preventDefault();
                    items[curIdx].dispatchEvent(new MouseEvent('mousedown', {
                        bubbles: true,
                        cancelable: true
                    }));
                } else if (e.key === 'Escape') {
                    panel.classList.remove('open');
                }
            }

            function setDropdownActiveItem(items, idx) {
                items.forEach(i => i.classList.remove('active'));
                const el = items[idx];
                el.classList.add('active');
                el.scrollIntoView({
                    block: 'nearest'
                });
            }

            async function runSingleForecast() {
                const product = document.getElementById('fc-product')?.value.trim();
                const category = document.getElementById('fc-category')?.value.trim() || '';
                const price = parseFloat(document.getElementById('fc-price')?.value) || 0;
                const storeId = document.getElementById('fc-store-id')?.value.trim() || 'BAR-01';
                if (!product) {
                    toast('Enter a product name', 'warning');
                    return;
                }

                const btn = document.getElementById('fc-single-btn');
                setLoading(btn, true);
                document.getElementById('fc-single-result').style.display = 'none';

                // ONE call now covers daily/weekly/monthly (was 3 separate slow external
                // API calls before) — much faster, especially on a cold external API.
                const r = await apiPost('get_forecast_all_periods', {
                    store_id: storeId,
                    product,
                    category,
                    price
                });

                setLoading(btn, false);

                if (!r?.success) {
                    toast(r?.error || 'Forecast API error — check connection', 'error');
                    return;
                }

                const {
                    daily,
                    weekly,
                    monthly
                } = r.data;

                // Populate result cards
                const set = (id, val) => {
                    const el = document.getElementById(id);
                    if (el) el.textContent = val;
                };
                set('fc-r-daily-pred', (daily.predicted_qty || 0) + ' units');
                set('fc-r-daily-restock', daily.restock_suggest || 0);
                set('fc-r-weekly-pred', (weekly.predicted_qty || 0) + ' units');
                set('fc-r-weekly-restock', weekly.restock_suggest || 0);
                set('fc-r-monthly-pred', (monthly.predicted_qty || 0) + ' units');
                set('fc-r-monthly-restock', monthly.restock_suggest || 0);

                if (r.data.message) toast('📡 ' + r.data.message, 'warning');
                document.getElementById('fc-single-result').style.display = 'block';
            }

            function analyticsInit() {
                if (cur_page !== 'analytics') return;
                apiGet('get_settings').then(s => {
                    CUR = s?.data?.currency || '₱';
                });
                Promise.all([
                    apiGet('get_stats'),
                    apiGet('get_top_products', {
                        limit: 10
                    })
                ]).then(([stats, top]) => {
                    if (stats?.success) {
                        const d = stats.data;
                        document.getElementById('a-rev').textContent = CUR + parseFloat(d.total_revenue).toFixed(2);
                        document.getElementById('a-orders').textContent = d.total_tx;
                        document.getElementById('a-avg').textContent = d.total_tx ? CUR + (d.total_revenue / d.total_tx).toFixed(2) : CUR + '0.00';
                    }
                    if (top?.success && top.data.length) document.getElementById('a-best').textContent = top.data[0].name;

                    // Load basket analysis in background
                    if (document.getElementById('mba-result')) loadBasketAnalysis();

                    // AI Insight
                    if (top?.success && stats?.success) {
                        const d = stats.data;
                        const t = top.data;
                        let msg = '';
                        if (d.total_tx < 3) {
                            msg = 'Make at least 3 sales to get AI-powered insights and restock recommendations.';
                        } else {
                            const topNames = t.slice(0, 3).map(p => p.name).join(', ');
                            if (catStats?.success && catStats.data.length) {
                                msg += '"' + catStats.data[0].category + '" is your top category — consider expanding it. ';
                            }
                            msg += 'Top sellers: ' + topNames + '. ';
                            if (d.low_stock > 0) msg += '⚠️ ' + d.low_stock + ' product(s) are low on stock — reorder soon. ';
                            if (d.out_of_stock > 0) msg += '🚨 ' + d.out_of_stock + ' product(s) are out of stock. ';
                            msg += 'Avg order value is ' + CUR + (d.total_tx ? (d.total_revenue / d.total_tx).toFixed(2) : '0.00') + '. Maintain 2× stock for top sellers to avoid stockouts. View the 🔮 Forecast page for AI-powered demand predictions and restock recommendations.';
                        }
                        const insightEl = document.getElementById('ai-insight');
                        if (insightEl) insightEl.textContent = msg;
                    }
                });

                // If the person tapped the Combo highlight card on the dashboard,
                // jump straight to the combo section here on Analytics and load it.
                if (localStorage.getItem('_gotoCombo') === '1' || location.hash === '#combo') {
                    localStorage.removeItem('_gotoCombo');
                    setTimeout(() => {
                        document.getElementById('combo')?.scrollIntoView({
                            behavior: 'smooth',
                            block: 'start'
                        });
                        loadCombos();
                    }, 350);
                }
            }

            // ════════════════════════════════
            // SHOP LOGO — upload/remove/preview
            // ════════════════════════════════
            function renderShopLogoPreview(url) {
                const img = document.getElementById('shop-logo-preview');
                const placeholder = document.getElementById('shop-logo-placeholder');
                const removeBtn = document.getElementById('shop-logo-remove-btn');
                if (!img) return;
                if (url) {
                    // BUGFIX: this used to call the nonexistent Date.CURRENT_TIMESTAMP
                    // (evaluates to undefined) — this cache-buster never actually
                    // varied, so a freshly-replaced logo could keep showing the
                    // browser's cached old one. Date.now() is the real API.
                    img.src = url + (url.includes('?') ? '&' : '?') + 'v=' + Date.now();
                    img.style.display = '';
                    // Same "DB says there's a file, but it's actually missing on disk"
                    // case as product photos — fall back to the placeholder instead of
                    // a broken-image icon.
                    img.onerror = function() {
                        this.style.display = 'none';
                        this.onerror = null;
                        if (placeholder) placeholder.style.display = '';
                        if (removeBtn) removeBtn.style.display = 'none';
                    };
                    if (placeholder) placeholder.style.display = 'none';
                    if (removeBtn) removeBtn.style.display = '';
                } else {
                    img.style.display = 'none';
                    if (placeholder) placeholder.style.display = '';
                    if (removeBtn) removeBtn.style.display = 'none';
                }
            }

            function onShopLogoFileChosen(inputEl) {
                const file = inputEl.files?.[0];
                if (!file) return;
                if (file.size > 5 * 1024 * 1024) {
                    toast('That image is over 5MB — please choose a smaller file', 'warning');
                    inputEl.value = '';
                    return;
                }
                const reader = new FileReader();
                reader.onload = () => {
                    const img = new Image();
                    img.onload = () => openLogoCropModal(img);
                    img.onerror = () => toast('Could not read that image file', 'error');
                    img.src = reader.result;
                };
                reader.readAsDataURL(file);
                // Reset immediately (rather than after upload) so re-choosing the same
                // file a second time — e.g. after Cancel — still fires onchange.
                inputEl.value = '';
            }

            // ── LOGO CROPPER — plain <canvas>, drag to pan + slider to zoom ──
            const CROP_FRAME = 280; // on-screen crop viewport, in CSS px (canvas is 1:1 with this)
            const CROP_OUTPUT = 512; // exported logo resolution
            let cropImg = null,
                cropScale = 1,
                cropMinScale = 1,
                cropOffsetX = 0,
                cropOffsetY = 0;
            let cropDragging = false,
                cropDragStartX = 0,
                cropDragStartY = 0,
                cropStartOffsetX = 0,
                cropStartOffsetY = 0;
            let cropShape = 'square'; // 'square' or 'circle' — circle exports with transparent corners

            function openLogoCropModal(img) {
                cropImg = img;
                // "cover" scale — the smallest scale at which the image still fills the
                // whole square frame with no empty edges, used as the zoomed-out limit.
                cropMinScale = Math.max(CROP_FRAME / img.width, CROP_FRAME / img.height);
                cropScale = cropMinScale;
                cropOffsetX = (CROP_FRAME - img.width * cropScale) / 2;
                cropOffsetY = (CROP_FRAME - img.height * cropScale) / 2;
                const slider = document.getElementById('crop-zoom-slider');
                if (slider) slider.value = '1';
                setCropShape('square');
                drawCropCanvas();
                setupCropDragHandlers();
                openModal('crop-logo-modal');
            }

            // Square keeps every corner (best for logos that are already a rectangular
            // lockup); Circle masks the frame + export to a circle — best for badge/coin
            // style artwork (like a round FIFA-style emblem) that otherwise gets stuck
            // with mismatched corner background when force-fit into a square.
            function setCropShape(shape) {
                cropShape = shape;
                const frame = document.getElementById('crop-frame-wrap');
                if (frame) frame.style.borderRadius = shape === 'circle' ? '50%' : '14px';
                const sqBtn = document.getElementById('crop-shape-square');
                const circBtn = document.getElementById('crop-shape-circle');
                if (sqBtn) sqBtn.className = 'btn btn-sm ' + (shape === 'square' ? 'btn-primary' : 'btn-secondary');
                if (circBtn) circBtn.className = 'btn btn-sm ' + (shape === 'circle' ? 'btn-primary' : 'btn-secondary');
            }

            function drawCropCanvas() {
                const canvas = document.getElementById('crop-canvas');
                if (!canvas || !cropImg) return;
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0, 0, CROP_FRAME, CROP_FRAME);
                ctx.drawImage(cropImg, cropOffsetX, cropOffsetY, cropImg.width * cropScale, cropImg.height * cropScale);
            }

            // Keeps the image always fully covering the square frame — no gaps at the edges.
            function clampCropOffset() {
                const dw = cropImg.width * cropScale,
                    dh = cropImg.height * cropScale;
                cropOffsetX = Math.min(0, Math.max(CROP_FRAME - dw, cropOffsetX));
                cropOffsetY = Math.min(0, Math.max(CROP_FRAME - dh, cropOffsetY));
            }

            function onCropZoomChange() {
                if (!cropImg) return;
                const slider = document.getElementById('crop-zoom-slider');
                const zoomMult = parseFloat(slider?.value || '1');
                const newScale = cropMinScale * zoomMult;
                // Zoom around the center of the frame rather than the image's corner, so
                // the subject the user has already centered doesn't drift while zooming.
                const cx = CROP_FRAME / 2,
                    cy = CROP_FRAME / 2;
                const imgX = (cx - cropOffsetX) / cropScale;
                const imgY = (cy - cropOffsetY) / cropScale;
                cropScale = newScale;
                cropOffsetX = cx - imgX * cropScale;
                cropOffsetY = cy - imgY * cropScale;
                clampCropOffset();
                drawCropCanvas();
            }

            function setupCropDragHandlers() {
                const canvas = document.getElementById('crop-canvas');
                if (!canvas || canvas._cropHandlersBound) return;
                canvas._cropHandlersBound = true;
                canvas.addEventListener('pointerdown', (e) => {
                    cropDragging = true;
                    cropDragStartX = e.clientX;
                    cropDragStartY = e.clientY;
                    cropStartOffsetX = cropOffsetX;
                    cropStartOffsetY = cropOffsetY;
                    canvas.setPointerCapture(e.pointerId);
                    canvas.style.cursor = 'grabbing';
                });
                canvas.addEventListener('pointermove', (e) => {
                    if (!cropDragging) return;
                    cropOffsetX = cropStartOffsetX + (e.clientX - cropDragStartX);
                    cropOffsetY = cropStartOffsetY + (e.clientY - cropDragStartY);
                    clampCropOffset();
                    drawCropCanvas();
                });
                const endDrag = () => {
                    cropDragging = false;
                    canvas.style.cursor = 'grab';
                };
                canvas.addEventListener('pointerup', endDrag);
                canvas.addEventListener('pointercancel', endDrag);
                canvas.addEventListener('pointerleave', endDrag);
            }

            function cancelLogoCrop() {
                closeModal('crop-logo-modal');
                cropImg = null;
            }

            function applyLogoCrop() {
                if (!cropImg) return;
                const out = document.createElement('canvas');
                out.width = CROP_OUTPUT;
                out.height = CROP_OUTPUT;
                const ctx = out.getContext('2d');
                const factor = CROP_OUTPUT / CROP_FRAME; // scale the same crop math up to export resolution
                if (cropShape === 'circle') {
                    // Clip to a circle before drawing so the corners come out transparent
                    // (PNG) instead of getting a square background around round artwork.
                    ctx.save();
                    ctx.beginPath();
                    ctx.arc(CROP_OUTPUT / 2, CROP_OUTPUT / 2, CROP_OUTPUT / 2, 0, Math.PI * 2);
                    ctx.closePath();
                    ctx.clip();
                }
                ctx.drawImage(
                    cropImg,
                    cropOffsetX * factor, cropOffsetY * factor,
                    cropImg.width * cropScale * factor, cropImg.height * cropScale * factor
                );
                if (cropShape === 'circle') ctx.restore();
                const dataUrl = out.toDataURL('image/png');
                closeModal('crop-logo-modal');
                apiPost('upload_shop_logo', {
                    image: dataUrl
                }).then(r => {
                    if (r?.success) {
                        toast('Logo updated', 'success');
                        renderShopLogoPreview(r.data.logo_url);
                    } else {
                        toast(r?.error || 'Could not upload that logo', 'error');
                    }
                });
                cropImg = null;
            }

            function removeShopLogo() {
                apiPost('remove_shop_logo', {}).then(r => {
                    if (r?.success) {
                        toast('Logo removed', 'success');
                        renderShopLogoPreview('');
                    } else toast(r?.error || 'Could not remove the logo', 'error');
                });
            }

