                if (cur_page !== 'settings') return;
                apiGet('get_settings').then(r => {
                    const s = r?.data || {};
                    const sni = document.getElementById('shop-name-inp');
                    const ci = document.getElementById('currency-inp');
                    const adi = document.getElementById('shop-address-inp');
                    const tni = document.getElementById('shop-tin-inp');
                    const tii = document.getElementById('terminal-id-inp');
                    const vri = document.getElementById('vat-rate-inp');
                    const tri = document.getElementById('tax-rate-inp');
