                    if (dei) dei.checked = !!s.qz_drawer_enabled;
                    if (dpi) dpi.value = s.qz_drawer_printer || '';
                });
                loadUsers();
                loadShiftStatusPanel();
                checkHwDiagLibraryStatus();
