            // ════════════════════════════════════════════════
            // HARDWARE DIAGNOSTICS — Settings page
            // ════════════════════════════════════════════════
            // Reports whether the barcode-rendering library actually loaded. This is
            // the one check safe to run automatically on page load (unlike a pop-up
            // permission check, it needs no user gesture, so it isn't self-defeating
            // to run it up front).
            function checkHwDiagLibraryStatus() {
                const el = document.getElementById('hw-diag-lib-status');
                if (!el) return;
                if (typeof JsBarcode === 'undefined') {
                    el.textContent = '❌ Failed to load';
                    el.style.color = 'var(--red, #C0392B)';
                } else {
                    el.textContent = '✅ Loaded';
                    el.style.color = 'var(--green, #2D7A3A)';
                }
            }

            function hwDiagResult(msg, ok) {
                const el = document.getElementById('hw-diag-result');
                if (!el) return;
                el.innerHTML = (ok ? '✅ ' : '❌ ') + msg;
                el.style.color = ok ? 'var(--green, #2D7A3A)' : 'var(--red, #C0392B)';
            }

            // Sends a sample receipt through the exact same template/print pipeline
            // used for a real sale (receiptBaseCSS/receiptHeaderHTML/receiptFooterHTML),
            // so a pass here means the real thing will work too — not just that SOME
            // window can print. Also doubles as the pop-up-permission check, since
            // that can only be read accurately from a direct click, not on page load.
            function testPrintReceipt() {
                const win = window.open('', '_blank', 'width=380,height=650');
                if (!win) {
                    hwDiagResult('Pop-up blocked — allow pop-ups for this site, then try again.', false);
                    toast('Pop-up blocked — allow pop-ups to test print', 'warning');
                    return;
                }
                const esc = receiptEsc;
                const itemsHtml =
                    '<tr><td>2</td><td>Sample Item A</td><td class="right">' + fmt(25) + '</td><td class="right">' + fmt(50) + '</td></tr>' +
                    '<tr><td>1</td><td>Sample Item B</td><td class="right">' + fmt(75) + '</td><td class="right">' + fmt(75) + '</td></tr>';
                win.document.write(
                    '<!DOCTYPE html><html><head><title>Test Receipt</title><meta charset="utf-8"/><style>' +
                    receiptBaseCSS() +
                    '</style></head><body>' +
                    '<div class="receipt-container">' +
                    receiptHeaderHTML('DIAGNOSTIC TEST PRINT') +
                    '<div class="divider"></div>' +
                    '<table class="items"><colgroup><col class="qty"><col class="desc"><col class="price"><col class="total"></colgroup>' +
                    '<thead><tr><th>Qty</th><th>Item</th><th class="right">Price</th><th class="right">Total</th></tr></thead>' +
                    '<tbody>' + itemsHtml + '</tbody></table>' +
                    '<div class="divider"></div>' +
                    '<div class="total-band"><span>TOTAL</span><span>' + fmt(125) + '</span></div>' +
                    '<div class="divider"></div>' +
                    receiptFooterHTML(['This is a diagnostic test print', 'No sale was recorded — ' + esc(new Date().toLocaleString())]) +
                    '</div>' +
                    '<script>window.onload=function(){window.print();}<\/script>' +
                    '</body></html>'
                );
                win.document.close();
                hwDiagResult('Test receipt sent to print. If nothing came out, check the printer power/cable/paper before retrying.', true);
            }

            // Runs a single barcode through the exact JsBarcode → SVG → canvas → PNG
            // pipeline used for real product labels, then prints it. A pass here means
            // generated labels will actually scan, not just that the printer accepted
            // a page.
            function testPrintBarcodeLabel() {
                if (typeof JsBarcode === 'undefined') {
                    hwDiagResult('Barcode library did not load — check your internet connection and reload the page.', false);
                    toast('Barcode library not loaded', 'error');
                    return;
                }
                const win = window.open('', '_blank');
                if (!win) {
                    hwDiagResult('Pop-up blocked — allow pop-ups for this site, then try again.', false);
                    toast('Pop-up blocked — allow pop-ups to test print', 'warning');
                    return;
                }
                const testCode = 'TEST-' + Date.now().toString().slice(-8);
                const tmpSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                tmpSvg.style.cssText = 'position:absolute;left:-9999px;top:-9999px;';
                document.body.appendChild(tmpSvg);
                try {
                    JsBarcode(tmpSvg, testCode, {
                        format: 'CODE128',
                        width: 2,
                        height: 55,
                        displayValue: true,
                        fontSize: 12,
                        margin: 10,
                        background: '#ffffff',
                        lineColor: '#000000'
                    });
                } catch (e) {
                    document.body.removeChild(tmpSvg);
                    win.close();
                    hwDiagResult('Could not generate the test barcode: ' + e.message, false);
                    return;
                }
                svgToCanvasPng(tmpSvg, (png) => {
                    document.body.removeChild(tmpSvg);
                    if (!png) {
                        win.close();
                        hwDiagResult('Barcode rendered but could not be converted to an image for printing.', false);
                        return;
                    }
                    win.document.write(
                        '<!DOCTYPE html><html><head><title>Test Barcode Label</title><meta charset="utf-8"/><style>' +
                        'body{margin:0;padding:24px;font-family:Arial,sans-serif;text-align:center;}' +
                        'img{max-width:100%;height:auto;image-rendering:crisp-edges;}' +
                        'p{font-size:11px;color:#666;margin-top:10px;}' +
                        '</style></head><body>' +
                        '<img src="' + png + '" alt="test barcode"/>' +
                        '<p>Diagnostic test label — scan this with your handheld scanner to confirm it reads back as "' + testCode + '"</p>' +
                        '<script>window.onload=function(){window.print();}<\/script>' +
                        '</body></html>'
                    );
                    win.document.close();
                    hwDiagResult('Test label sent to print. Scan it afterward to confirm the code reads back correctly.', true);
                });
            }

            // ════════════════════════════════════════════════
            // CASH DRAWER — PHYSICAL TRIGGER (via QZ Tray)
            // ════════════════════════════════════════════════
            // Browsers have no channel to pulse a drawer's kick-out port directly —
            // this is what actually bridges that gap: QZ Tray is a small desktop app
            // (installed separately on the till's PC, not part of this codebase) that
            // exposes a local websocket this page can send raw ESC/POS bytes through,
            // out to whichever real printer the drawer is wired to.
            //
            // Unsigned mode: no signing certificate is configured here (that requires
            // a backend endpoint holding a private key, which is a separate piece of
            // infrastructure). Without one, QZ Tray will show a one-time "Allow/Block"
            // prompt on the till's own screen the first time this page connects each
            // session — that's a QZ Tray security feature, not a bug. If that prompt
            // is a problem in practice, the fix is adding certificate signing, not
            // removing this check.
            let _qzConnectPromise = null;

            function qzConnect() {
                if (typeof qz === 'undefined') return Promise.reject(new Error('QZ Tray script did not load (offline/CDN blocked)'));
                if (qz.websocket.isActive()) return Promise.resolve();
                // Reuse an in-flight connection attempt instead of racing two at once
                // (e.g. auto-open-after-payment firing while someone also clicks Test).
                if (_qzConnectPromise) return _qzConnectPromise;
                _qzConnectPromise = qz.websocket.connect({
                        retries: 2,
                        delay: 1
                    })
                    .catch(err => {
                        _qzConnectPromise = null;
                        throw err;
                    })
                    .then(res => {
                        _qzConnectPromise = null;
                        return res;
                    });
                return _qzConnectPromise;
            }

            // Standard ESC/POS drawer-kick pulse (ESC p 0 25 250) — fires pin 2 on the
            // printer's drawer-kick port, which is how the overwhelming majority of
            // receipt-printer-wired cash drawers are triggered. If a specific printer
            // model needs the alternate pin-5 sequence instead (ESC p 1 25 250) that's
            // a one-character change below, not a redesign.
            const DRAWER_KICK_ESCPOS = '\x1B\x70\x00\x19\xFA';

            // silent=true (used right after a real cash payment) never throws/toasts —
            // a printer being off or QZ Tray not running must NEVER block or interrupt
            // an already-completed sale. silent=false (the Settings test button) always
            // reports a clear pass/fail so a manager can actually debug the wiring.
            function openCashDrawer(silent) {
                if (!QZ_DRAWER_PRINTER) {
                    const msg = 'No printer configured for the cash drawer — set one in Settings → Hardware Diagnostics first.';
                    if (!silent) hwDiagResult(msg, false);
                    return Promise.reject(new Error(msg));
                }
                return qzConnect()
                    .then(() => {
                        const config = qz.configs.create(QZ_DRAWER_PRINTER);
                        return qz.print(config, [{
                            type: 'raw',
                            format: 'command',
                            flavor: 'plain',
                            data: DRAWER_KICK_ESCPOS
                        }]);
                    })
                    .then(() => {
                        if (!silent) hwDiagResult('Drawer-kick signal sent to "' + QZ_DRAWER_PRINTER + '".', true);
                    })
                    .catch(err => {
                        const reason = (err && err.message) ? err.message : String(err);
                        if (silent) {
                            console.warn('Cash drawer kick skipped (sale still completed):', reason);
                        } else {
                            hwDiagResult('Could not open the drawer: ' + reason + ' — check QZ Tray is running and the printer name matches exactly.', false);
                        }
                        throw err;
                    });
            }

            // Persists the two drawer settings (enabled + printer name) via the
            // existing generic save_settings action — no new endpoint needed.
            function saveDrawerConfig() {
                const enabledEl = document.getElementById('hw-diag-drawer-enabled');
                const printerEl = document.getElementById('hw-diag-drawer-printer');
                const enabled = !!enabledEl?.checked;
                const printer = (printerEl?.value || '').trim();
                apiPost('save_settings', {
                    qz_drawer_enabled: enabled ? '1' : '',
                    qz_drawer_printer: printer
                }).then(r => {
                    if (!r?.success) {
                        toast('Could not save cash drawer settings', 'error');
                        return;
                    }
                    QZ_DRAWER_ENABLED = enabled;
                    QZ_DRAWER_PRINTER = printer;
                    toast('✅ Cash drawer settings saved', 'success');
                });
            }


            // ════════════════════════════════════════════════
            // CASH DRAWER — live shift status panel (Settings page)
            // ════════════════════════════════════════════════
            function loadShiftStatusPanel() {
                apiGet('check_cash_float').then(r => {
                    const statusEl = document.getElementById('cf-status');
                    if (!r?.success || !statusEl) return;
                    const d = r.data;
                    if (d.initialized && d.shift) {
                        const s = d.shift;
                        statusEl.innerHTML =
                            '<div style="background:rgba(45,122,58,.1);border:1.5px solid rgba(45,122,58,.3);border-radius:9px;padding:12px 14px;font-size:.83rem;color:#1e6328;line-height:1.7;">' +
                            '✅ Shift active since <strong>' + fmtDate(s.login_time) + '</strong><br>' +
                            'Opening float: <strong>' + fmt(s.opening_float) + '</strong> · Cash sales so far: <strong>' + fmt(s.cash_sales) + '</strong><br>' +
                            'Expected cash in drawer right now: <strong>' + fmt(s.expected_cash) + '</strong>' +
                            '</div>';
                    } else {
                        statusEl.innerHTML = '<div style="background:rgba(244,160,36,.12);border:1.5px solid rgba(244,160,36,.4);border-radius:9px;padding:10px 13px;font-size:.83rem;color:#7a5500;">⚠️ No active shift. You\'ll be asked to count the drawer next time the lock screen appears.</div>';
                    }
                });
                if (typeof USER_ROLE !== 'undefined' && USER_ROLE === 'owner') loadShiftMonitor();
            }

            // ════════════════════════════════════════════════
            // CASHIER SHIFT MONITOR — owner-only accountability view
            // ════════════════════════════════════════════════
            function loadShiftMonitor() {
                const activeEl = document.getElementById('sm-active');
                const summaryEl = document.getElementById('sm-summary');
                const recentEl = document.getElementById('sm-recent');
                if (!activeEl) return;
                apiGet('get_shift_monitor').then(r => {
                    if (!r?.success) {
                        activeEl.innerHTML = '<p style="font-size:.8rem;color:var(--text3);">Couldn\'t load shift monitor.</p>';
                        return;
                    }
                    const d = r.data;

                    // ── Currently clocked in ──
                    let activeHtml = '<div style="font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--text3);margin-bottom:8px;">On Shift Right Now</div>';
                    if (!d.active.length) {
                        activeHtml += '<p style="font-size:.83rem;color:var(--text3);">No cashiers are currently clocked in.</p>';
                    } else {
                        activeHtml += '<div style="display:flex;flex-direction:column;gap:8px;">' + d.active.map(s => {
                            // Same fraud-threshold rule as the closed-shift history below (>3
                            // voids or >₱2,000 voided) — but shown LIVE so an owner can catch it
                            // while the shift is still open, not just after the Z-read.
                            const fraudFlag = (s.void_count > 3) || (s.void_value > 2000);
                            return '<div style="background:' + (fraudFlag ? 'rgba(192,57,43,.08)' : 'rgba(45,122,58,.08)') + ';border:1.5px solid ' + (fraudFlag ? 'var(--danger)' : 'rgba(45,122,58,.25)') + ';border-radius:9px;padding:10px 13px;font-size:.82rem;line-height:1.6;">' +
                                '<strong>🟢 ' + escapeHtml(s.full_name) + '</strong> <span style="color:var(--text3);">@' + escapeHtml(s.username) + '</span><br>' +
                                'Clocked in ' + fmtDate(s.login_time) + ' · Opening float: <strong>' + fmt(s.opening_float) + '</strong><br>' +
                                'Cash sales so far: <strong>' + fmt(s.cash_sales) + '</strong>' + (s.void_count > 0 ? ' · Voids: <strong style="color:var(--danger);">' + s.void_count + ' (' + fmt(s.void_value) + ')</strong>' : '') + '<br>' +
                                'Expected in drawer now: <strong>' + fmt(s.expected_cash) + '</strong>' +
                                (fraudFlag ? '<br><strong style="color:var(--danger);">⚠️ Exceeds void threshold — review live</strong>' : '') +
                                '</div>';
                        }).join('') + '</div>';
                    }
                    if (d.off_shift && d.off_shift.length) {
                        activeHtml += '<div style="font-size:.76rem;color:var(--text3);margin-top:8px;">Off shift: ' + d.off_shift.map(u => escapeHtml(u.full_name)).join(', ') + '</div>';
                    }
                    activeEl.innerHTML = activeHtml;

                    // ── Per-cashier accountability summary (who runs short vs over, and voids) ──
                    let summaryHtml = '<div style="font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--text3);margin-bottom:8px;">Track Record</div>';
                    if (!d.summary.length) {
                        summaryHtml += '<p style="font-size:.83rem;color:var(--text3);">No closed shifts yet — track record builds up as cashiers end their shifts.</p>';
                    } else {
                        summaryHtml += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:.8rem;">' +
                            '<thead><tr style="text-align:left;color:var(--text3);font-size:.7rem;text-transform:uppercase;letter-spacing:.04em;">' +
                            '<th style="padding:6px 8px;">Cashier</th><th style="padding:6px 8px;">Shifts</th><th style="padding:6px 8px;">Short</th><th style="padding:6px 8px;">Over</th><th style="padding:6px 8px;">Voids</th><th style="padding:6px 8px;">Void Value</th><th style="padding:6px 8px;">Net Variance</th><th style="padding:6px 8px;">Worst Short</th></tr></thead><tbody>' +
                            d.summary.map(s => {
                                const netColor = s.total_variance < -0.005 ? 'var(--danger)' : (s.total_variance > 0.005 ? 'var(--green)' : 'var(--text2)');
                                const voidCount = s.total_voids || 0;
                                const voidValue = parseFloat(s.total_void_value || 0);
                                return '<tr style="border-top:1px solid var(--border);">' +
                                    '<td style="padding:6px 8px;font-weight:700;">' + escapeHtml(s.full_name) + '</td>' +
                                    '<td style="padding:6px 8px;">' + s.shifts_closed + '</td>' +
                                    '<td style="padding:6px 8px;' + (s.short_count > 0 ? 'color:var(--danger);font-weight:700;' : '') + '">' + s.short_count + '</td>' +
                                    '<td style="padding:6px 8px;">' + s.over_count + '</td>' +
                                    '<td style="padding:6px 8px;' + (voidCount > 0 ? 'font-weight:700;' : '') + '">' + voidCount + '</td>' +
                                    '<td style="padding:6px 8px;' + (voidValue > 0 ? 'color:var(--danger);font-weight:700;' : '') + '">' + fmt(voidValue) + '</td>' +
                                    '<td style="padding:6px 8px;color:' + netColor + ';font-weight:700;">' + fmt(s.total_variance) + '</td>' +
                                    '<td style="padding:6px 8px;">' + (s.worst_short < -0.005 ? fmt(s.worst_short) : '—') + '</td>' +
                                    '</tr>';
                            }).join('') + '</tbody></table></div>';
                    }
                    summaryEl.innerHTML = summaryHtml;

                    // ── Most recent closed shifts (last 20), flagged short / over / balanced,
                    //    with a fraud-alert highlight if a single shift had heavy voids ──
                    let recentHtml = '<div style="font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--text3);margin-bottom:8px;">Recent Closed Shifts</div>';
                    if (!d.closed.length) {
                        recentHtml += '<p style="font-size:.83rem;color:var(--text3);">No closed shifts to show yet.</p>';
                    } else {
                        recentHtml += '<div style="display:flex;flex-direction:column;gap:6px;max-height:320px;overflow-y:auto;">' + d.closed.map(s => {
                            const v = parseFloat(s.variance);
                            let badge, badgeColor;
                            if (v < -0.005) {
                                badge = '🔴 Short ' + fmt(Math.abs(v));
                                badgeColor = 'var(--danger)';
                            } else if (v > 0.005) {
                                badge = '🟡 Over ' + fmt(v);
                                badgeColor = 'var(--accent2)';
                            } else {
                                badge = '✅ Balanced';
                                badgeColor = 'var(--green)';
                            }
                            const voidCount = s.total_void_count || 0;
                            const voidValue = parseFloat(s.total_void_value || 0);
                            // FRAUD ALERT RULE: flag a single shift with >3 voids or >₱2,000 voided
                            const fraudFlag = voidCount > 3 || voidValue > 2000;
                            const voidSub = voidCount > 0 ?
                                '<div style="font-size:.72rem;margin-top:2px;font-weight:' + (fraudFlag ? '800' : '600') + ';color:' + (fraudFlag ? 'var(--danger)' : 'var(--accent2)') + ';">' +
                                (fraudFlag ? '⚠️ ' : '') + voidCount + ' void(s) · ' + fmt(voidValue) + '</div>' :
                                '';
                            return '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:8px 11px;background:var(--surface2);border-radius:8px;font-size:.79rem;' +
                                (fraudFlag ? 'border:1.5px solid var(--danger);' : '') + '">' +
                                '<div><strong>' + escapeHtml(s.full_name) + '</strong><br><span style="color:var(--text3);font-size:.73rem;">' + fmtDate(s.logout_time) + '</span>' + voidSub + '</div>' +
                                '<div style="text-align:right;color:' + badgeColor + ';font-weight:700;">' + badge + '</div>' +
                                '</div>';
                        }).join('') + '</div>';
                    }
                    recentEl.innerHTML = recentHtml;
                });
            }

            function saveSettings() {
                const shop_name = document.getElementById('shop-name-inp')?.value || '';
                const currency = document.getElementById('currency-inp')?.value || '₱';
                const shop_address = document.getElementById('shop-address-inp')?.value.trim() || '';
                const shop_tin = document.getElementById('shop-tin-inp')?.value.trim() || '';
                const terminal_id = document.getElementById('terminal-id-inp')?.value.trim() || 'POS-01';
                const vat_rate = Math.max(0, parseFloat(document.getElementById('vat-rate-inp')?.value || 0));
                const tax_rate = Math.max(0, parseFloat(document.getElementById('tax-rate-inp')?.value || 0));
                apiPost('save_settings', {
                    shop_name,
                    currency,
                    shop_address,
                    shop_tin,
                    terminal_id
                    , vat_rate
                    , tax_rate
                }).then(r => {
                    toast(r?.success ? 'Settings saved!' : 'Error saving settings', r?.success ? 'success' : 'error');
                });
            }

            // ── SYSTEM THEME (Settings → System Theme) ──
            // Default palette matches the built-in dark theme's own :root values
            // exactly, so "Reset to Default" (and a first-ever visit with nothing
            // saved yet) looks identical to the app's normal look.
            const DEFAULT_SYSTEM_THEME = {
                bg: '#0a1628',
                surface: '#101f38',
                text: '#e8eef7',
                accent: '#2f7ff5',
                font: "'Inter', sans-serif",
                fontSize: 100
            };

            function readSystemThemeInputs() {
                return {
                    bg: document.getElementById('theme-bg-inp')?.value || DEFAULT_SYSTEM_THEME.bg,
                    surface: document.getElementById('theme-surface-inp')?.value || DEFAULT_SYSTEM_THEME.surface,
                    text: document.getElementById('theme-text-inp')?.value || DEFAULT_SYSTEM_THEME.text,
                    accent: document.getElementById('theme-accent-inp')?.value || DEFAULT_SYSTEM_THEME.accent,
                    font: document.getElementById('theme-font-inp')?.value || DEFAULT_SYSTEM_THEME.font,
                    fontSize: parseFloat(document.getElementById('theme-fontsize-inp')?.value) || 100
                };
            }

            function populateSystemThemeInputs() {
                let saved = null;
                try {
                    saved = JSON.parse(localStorage.getItem('pos_custom_theme') || 'null');
                } catch (e) {}
                const t = saved || DEFAULT_SYSTEM_THEME;
                const bgi = document.getElementById('theme-bg-inp');
                const sfi = document.getElementById('theme-surface-inp');
                const txi = document.getElementById('theme-text-inp');
                const aci = document.getElementById('theme-accent-inp');
                const fni = document.getElementById('theme-font-inp');
                const fsi = document.getElementById('theme-fontsize-inp');
                if (bgi) bgi.value = t.bg;
                if (sfi) sfi.value = t.surface;
                if (txi) txi.value = t.text;
                if (aci) aci.value = t.accent;
                if (fni) fni.value = t.font;
                if (fsi) fsi.value = String(t.fontSize);
            }

            // Applies whatever's currently picked immediately, before Save is even
            // tapped — reuses the exact same color-mixing/derivation logic the
            // before-paint <head> script uses (window._themeUtil), so the live
            // preview and what actually loads next time are guaranteed identical.
            function previewSystemTheme() {
                window._themeUtil?.applyCustomThemeVars(readSystemThemeInputs());
            }

            function saveSystemTheme() {
                const t = readSystemThemeInputs();
                try {
                    localStorage.setItem('pos_custom_theme', JSON.stringify(t));
                } catch (e) {
                    toast('Could not save theme (browser storage unavailable)', 'error');
                    return;
                }
                window._themeUtil?.applyCustomThemeVars(t);
                toast('Theme saved!', 'success');
            }

            function resetSystemTheme() {
                try {
                    localStorage.removeItem('pos_custom_theme');
                } catch (e) {}
                // Clearing the inline overrides (rather than re-applying the default
                // theme's own values) lets the normal Light/Dark toggle's stylesheet
                // rules take back over exactly as if no custom theme was ever set.
                const root = document.documentElement.style;
                ['--bg', '--surface', '--surface2', '--border', '--text', '--text2', '--text3', '--accent', '--accent2', '--user-font-family']
                .forEach(p => root.removeProperty(p));
                document.documentElement.style.fontSize = '';
                document.documentElement.style.colorScheme = '';
                populateSystemThemeInputs();
                toast('Theme reset to default', 'success');
            }

            function saveMyEmail() {
                const em = document.getElementById('my-email')?.value.trim() || '';
                apiPost('update_email', {
                    email: em
                }).then(r => {
                    if (!r?.success) {
                        toast(r?.error || 'Error saving email', 'error');
                        return;
                    }
                    toast('Email saved!', 'success');
                });
            }

            function changePW() {
                const o = document.getElementById('old-pw')?.value || '';
                const n = document.getElementById('new-pw')?.value || '';
                if (!o || !n) {
                    toast('Please fill both password fields', 'error');
                    return;
                }
                if (n.length < 6) {
                    toast('New password must be at least 6 characters', 'error');
                    return;
                }
                apiPost('change_password', {
                    old_password: o,
                    new_password: n
                }).then(r => {
                    if (!r?.success) {
                        toast(r?.error || 'Error changing password', 'error');
                        return;
                    }
                    toast('Password updated successfully!', 'success');
                    document.getElementById('old-pw').value = '';
                    document.getElementById('new-pw').value = '';
                });
            }

            function loadUsers() {
                const el = document.getElementById('users-list');
                if (!el) return;
                apiGet('get_users').then(r => {
                    if (!r?.success) return;
                    el.innerHTML = r.data.map(u =>
                        '<div style="display:flex;align-items:center;gap:8px;padding:9px 0;border-bottom:1px solid var(--border);">' +
                        '<div style="flex:1;">' +
                        '<div style="font-size:.88rem;font-weight:600;">' + (u.full_name || u.username) + '</div>' +
                        '<div style="font-size:.74rem;color:var(--text3);">@' + u.username + ' · ' + u.role + (u.email ? ' · ' + u.email : '') + '</div>' +
                        '</div>' +
                        '<button type="button" class="btn btn-danger btn-sm" onclick="deleteUser(' + u.id + ')">Delete</button>' +
                        '</div>'
                    ).join('');
                });
            }

            function addUser() {
                const u = document.getElementById('new-uname')?.value.trim() || '';
                const p = document.getElementById('new-upass')?.value || '';
                const fn = document.getElementById('new-uname-full')?.value.trim() || '';
                const em = document.getElementById('new-uemail')?.value.trim() || '';
                const role = document.getElementById('new-urole')?.value || 'staff';
                if (!u || !p) {
                    toast('Username and password are required', 'error');
                    return;
                }
                apiPost('add_user', {
                    username: u,
                    password: p,
                    full_name: fn,
                    email: em,
                    role
                }).then(r => {
                    if (!r?.success) {
                        toast(r?.error || 'Error adding user', 'error');
                        return;
                    }
                    toast('User added!', 'success');
                    ['new-uname', 'new-upass', 'new-uname-full', 'new-uemail'].forEach(id => {
                        const el = document.getElementById(id);
                        if (el) el.value = '';
                    });
                    loadUsers();
                });
            }

            function deleteUser(id) {
                if (!confirm('Delete this user account?')) return;
                apiPost('delete_user', {
                    id
                }).then(r => {
                    if (!r?.success) {
                        toast(r?.error || 'Error deleting user', 'error');
                        return;
                    }
                    toast('User deleted', 'success');
                    loadUsers();
                });
            }

            // ── INIT ON PAGE LOAD ──

            // ════════════════════════════════════════════════
            // BARCODE GENERATION (JsBarcode — CODE128)
            // ════════════════════════════════════════════════

            // ── BARCODE OPTIONS — single source of truth ──
            const BC_OPTS = {
                format: 'CODE128',
                width: 2,
                height: 55,
                displayValue: true,
                fontSize: 11,
                margin: 10, // wider quiet zone prevents mirror-read failures
                marginLeft: 10,
                marginRight: 10,
                background: '#ffffff',
                lineColor: '#000000'
            };

            // generateBarcode — renders to CANVAS (not SVG) for the on-screen preview.
            // Pipeline: value → hidden SVG (JsBarcode) → svgToCanvasPng → <canvas> displayed.
            // This eliminates all mirror/flip issues because canvas pixels are always LTR.
            function generateBarcode(value, svgId) {
                // svgId param kept for backwards compat but we always use barcode-canvas for display
                const wrap = document.getElementById('qr-preview-wrap');
                const canvas = document.getElementById('barcode-canvas');
                const hiddenSvg = document.getElementById('barcode-svg'); // off-screen, never shown
                if (!canvas && !hiddenSvg) return;
                if (wrap) wrap.style.display = 'block';

                if (typeof JsBarcode === 'undefined') {
                    // Library not loaded yet — show placeholder text on canvas
                    if (canvas) {
                        canvas.width = 260;
                        canvas.height = 70;
                        const ctx = canvas.getContext('2d');
                        ctx.fillStyle = '#fff';
                        ctx.fillRect(0, 0, 260, 70);
                        ctx.fillStyle = '#888';
                        ctx.font = '12px sans-serif';
                        ctx.textAlign = 'center';
                        ctx.fillText('Loading barcode…', 130, 38);
                    }
                    return;
                }

                // Step 1 — Render into the hidden off-screen SVG
                const svg = hiddenSvg || document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                try {
                    JsBarcode(svg, value, BC_OPTS);
                } catch (e) {
                    if (canvas) {
                        canvas.width = 260;
                        canvas.height = 50;
                        const ctx = canvas.getContext('2d');
                        ctx.fillStyle = '#fff';
                        ctx.fillRect(0, 0, 260, 50);
                        ctx.fillStyle = '#c00';
                        ctx.font = '11px sans-serif';
                        ctx.textAlign = 'center';
                        ctx.fillText('Invalid barcode value', 130, 28);
                    }
                    return;
                }

                // Step 2 — Rasterize the SVG to PNG, then paint onto the visible canvas
                svgToCanvasPng(svg, (png) => {
                    if (!png || !canvas) return;
                    const img = new Image();
                    img.onload = () => {
                        // Display at 1× logical pixels (the PNG is already 2× from svgToCanvasPng)
                        canvas.width = Math.round(img.naturalWidth / 2);
                        canvas.height = Math.round(img.naturalHeight / 2);
                        canvas.style.width = Math.min(canvas.width, 280) + 'px';
                        canvas.style.height = Math.min(canvas.height, 90) + 'px';
                        const ctx = canvas.getContext('2d');
                        ctx.imageSmoothingEnabled = false;
                        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                    };
                    img.src = png;
                });
            }

            // Rasterize an SVG barcode element to a PNG data-URL via canvas.
            // This is the ONLY way to guarantee the printed barcode is never mirrored.
            function svgToCanvasPng(svgEl, callback) {
                const svgData = new XMLSerializer().serializeToString(svgEl);
                const svgBlob = new Blob([svgData], {
                    type: 'image/svg+xml;charset=utf-8'
                });
                const url = URL.createObjectURL(svgBlob);
                const img = new Image();
                img.onload = () => {
                    const W = img.naturalWidth || svgEl.width?.baseVal?.value || 300;
                    const H = img.naturalHeight || svgEl.height?.baseVal?.value || 100;
                    const canvas = document.createElement('canvas');
                    canvas.width = W * 2; // 2× for crisp printing
                    canvas.height = H * 2;
                    const ctx = canvas.getContext('2d');
                    ctx.imageSmoothingEnabled = false;
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(0, 0, canvas.width, canvas.height);
                    // Draw WITHOUT any flipping — canvas origin is top-left, positive x is right
                    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                    URL.revokeObjectURL(url);
                    callback(canvas.toDataURL('image/png'), canvas.width, canvas.height);
                };
                img.onerror = () => {
                    URL.revokeObjectURL(url);
                    callback(null);
                };
                img.src = url;
            }

            // Generate a fresh barcode directly onto a canvas (bypasses SVG entirely).
            // width/height are the canvas pixel dimensions.
            function renderBarcodeToCanvas(value, canvas) {
                return new Promise(resolve => {
                    const tmpSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                    document.body.appendChild(tmpSvg);
                    try {
                        JsBarcode(tmpSvg, value, BC_OPTS);
                    } catch (e) {
                        document.body.removeChild(tmpSvg);
                        resolve(null);
                        return;
                    }
                    svgToCanvasPng(tmpSvg, (png, w, h) => {
                        document.body.removeChild(tmpSvg);
                        if (!png) {
                            resolve(null);
                            return;
                        }
                        const img = new Image();
                        img.onload = () => {
                            canvas.width = img.naturalWidth;
                            canvas.height = img.naturalHeight;
                            const ctx = canvas.getContext('2d');
                            ctx.imageSmoothingEnabled = false;
                            ctx.fillStyle = '#fff';
                            ctx.fillRect(0, 0, canvas.width, canvas.height);
                            ctx.drawImage(img, 0, 0);
                            resolve(canvas.toDataURL('image/png'));
                        };
                        img.src = png;
                    });
                });
            }

            // Kept as alias — called in several places
            function generateQRCode(text) {
                let bc = text;
                try {
                    const d = JSON.parse(text);
                    bc = d.barcode || text;
                } catch (e) {}
                generateBarcode(bc, 'barcode-svg');
            }

            function showQRPreview() {
                const barcode = document.getElementById('p-barcode')?.value.trim();
                if (!barcode) {
                    toast('Enter a barcode value first', 'warning');
                    return;
                }
                generateBarcode(barcode, 'barcode-svg');
            }

            // Tracks whether the current p-barcode value came from the Auto-Generate
            // button (vs typed or scanned from a real physical label). Only an
            // auto-generated code is safe to silently replace on a collision —
            // a real scanned/typed barcode colliding means something else already
            // legitimately owns that code, so that case must still show the error.
            let _barcodeAutoGenerated = false;

            // High-entropy suffix: crypto-random bytes instead of Math.random(),
            // and always exactly 10 chars (Math.random().toString(36) can silently
            // produce FEWER characters when the random float has trailing zeros,
            // shrinking the effective entropy right when you need it most).
            function generateBarcodeSuffix() {
                const bytes = new Uint8Array(8);
                (window.crypto || window.msCrypto).getRandomValues(bytes);
                let s = '';
                for (const b of bytes) s += b.toString(36).padStart(2, '0');
                return s.slice(0, 10).toUpperCase();
            }

            function genBarcode(targetId) {
                targetId = targetId || 'p-barcode';
                const bc = 'BC-' + generateBarcodeSuffix();
                const inp = document.getElementById(targetId);
                if (inp) {
                    inp.value = bc;
                    if (targetId === 'p-barcode') {
                        _barcodeAutoGenerated = true;
                        const showQrBtn = document.getElementById('show-qr-btn');
                        if (showQrBtn) showQrBtn.style.display = '';
                        generateBarcode(bc, 'barcode-svg');
                        onBarcodeFieldChange();
                    }
                }
            }

            // ════════════════════════════════════════════════
            // SCAN-TO-ADD PRODUCT BARCODE
            // Lets the owner/employee scan the item's real printed barcode straight
            // into the product form (camera or physical HID scanner both work), instead
            // of typing/guessing a code. Also live-checks for duplicates so two staff
            // members can't accidentally register the same barcode on two products.
            // ════════════════════════════════════════════════
            let _scanTargetField = 'p-barcode';

            function openProductBarcodeScan(targetId) {
                _scanTargetField = targetId || 'p-barcode';
                const statusEl = document.getElementById('prod-scan-status');
                if (statusEl) statusEl.textContent = 'Point the camera at the product\'s printed barcode';
                const manualEl = document.getElementById('prod-scan-manual');
                if (manualEl) manualEl.value = '';
                openModal('prod-scan-modal');
                startScanner('prod-scan-video', null, code => {
                    // Grab the exact camera frame the barcode was read from and use it as the
                    // product photo too — one scan fills in BOTH the barcode and a starting
                    // photo, instead of scanning the barcode then separately uploading a photo.
                    // Only applies when scanning the product's own (piece) barcode.
                    if (_scanTargetField === 'p-barcode') captureVideoFrameAsProductPhoto('prod-scan-video');
                    stopScanner();
                    confirmProductBarcode(code);
                });
            }

            // Snapshots the live scanner video into a still image and drops it straight
            // into the product photo field (same compression pipeline as a normal upload).
            // Only auto-fills for a brand-new product that doesn't already have a photo —
            // scanning a barcode to FIX an existing product's code should never silently
            // replace a photo someone already chose deliberately.
            function captureVideoFrameAsProductPhoto(videoId) {
                const isEditingExisting = !!document.getElementById('edit-id')?.value;
                if (isEditingExisting || imgB64) return;
                const video = document.getElementById(videoId);
                if (!video || !video.videoWidth) return; // camera frame not ready yet
                const c = document.createElement('canvas');
                c.width = video.videoWidth;
                c.height = video.videoHeight;
                c.getContext('2d').drawImage(video, 0, 0, c.width, c.height);
                compressImg(c.toDataURL('image/jpeg', 0.9)).then(b64 => {
                    imgB64 = b64;
                    const preview = document.getElementById('img-preview');
                    const placeholder = document.getElementById('img-placeholder');
                    const removeBtn = document.getElementById('img-remove-btn');
                    if (preview) {
                        preview.src = b64;
                        preview.style.display = 'block';
                    }
                    if (placeholder) placeholder.style.display = 'none';
                    if (removeBtn) removeBtn.style.display = '';
                    toast('📸 Photo captured from scan — retake below if you\'d like a better shot', 'success');
                }).catch(() => {}); // silently skip — barcode still gets filled in either way
            }

            function closeProductBarcodeScan() {
                stopScanner();
                closeModal('prod-scan-modal');
            }

            async function confirmProductBarcode(rawCode) {
                let barcode = (rawCode || '').trim();
                try {
                    const d = JSON.parse(barcode);
                    barcode = (d.barcode || barcode).trim();
                } catch (e) {}
                barcode = barcode.replace(/[\s\r\n\t]/g, '');
                if (!barcode) return;

                closeProductBarcodeScan();
                const targetId = _scanTargetField || 'p-barcode';
                const inp = document.getElementById(targetId);
                if (inp) {
                    inp.value = barcode;
                    inp.dispatchEvent(new Event('input'));
                }
                if (targetId === 'p-barcode') {
                    await onBarcodeFieldChange();
                    autofillFromScannedBarcode(barcode);
                }
            }

            // Auto-fills Name/Brand/Description/Unit from the public Open Food
            // Facts database right after a scan — for a BRAND-NEW product only,
            // and only into fields the user hasn't already typed something into
            // (never overwrites a deliberate entry). Expiry date is NOT touched —
            // no barcode format used at retail encodes it, so that one always
            // stays manual. Silent on a miss (unknown barcode, offline, etc.) —
            // the barcode itself is already filled in fine either way.
            async function autofillFromScannedBarcode(barcode) {
                const isEditingExisting = !!document.getElementById('edit-id')?.value;
                if (isEditingExisting) return;

                const nameEl = document.getElementById('p-name');
                const brandEl = document.getElementById('p-brand');
                const descEl = document.getElementById('p-desc');
                const unitSizeEl = document.getElementById('p-unit-size');
                const unitTypeEl = document.getElementById('p-unit-type');

                // Everything's already filled in — nothing to look up for.
                const nothingToFill = nameEl?.value.trim() && brandEl?.value.trim() && descEl?.value.trim() && unitSizeEl?.value.trim();
                if (nothingToFill) return;

                const r = await apiGet('lookup_barcode_external', {
                    barcode
                });
                if (!r?.success || !r.data) return;

                const d = r.data;
                let filledAny = false;
                if (d.name && nameEl && !nameEl.value.trim()) {
                    nameEl.value = d.name;
                    filledAny = true;
                }
                if (d.brand && brandEl && !brandEl.value.trim()) {
                    brandEl.value = d.brand;
                    filledAny = true;
                }
                if (d.description && descEl && !descEl.value.trim()) {
                    descEl.value = d.description;
                    filledAny = true;
                }
                if (d.unit_size && unitSizeEl && !unitSizeEl.value.trim()) {
                    unitSizeEl.value = d.unit_size;
                    filledAny = true;
                }
                // p-unit-type is a <select> — it always HAS a value ("Pieces (pcs)",
                // the first option), so it's never "empty" the way a text input is.
                // The real signal that the person hasn't touched it yet is that it's
                // still sitting on that default — check THAT instead of emptiness,
                // or this auto-fill silently never applies the kg/ml/g/L the lookup
                // found (the number field would fill in fine, but the unit dropdown
                // next to it would stay stuck on "Pieces").
                if (d.unit_type && unitTypeEl && unitTypeEl.value === 'pcs') {
                    const validOption = [...unitTypeEl.options].some(o => o.value === d.unit_type);
                    if (validOption) {
                        unitTypeEl.value = d.unit_type;
                        if (typeof onUnitTypeChange === 'function') onUnitTypeChange();
                        filledAny = true;
                    }
                }

                if (filledAny) {
                    toast('✅ Filled in Name/Brand/Description/Unit from product database — please double-check before saving', 'success');
                }
            }

            // Live duplicate check — runs whenever the barcode field changes (typed,
            // scanned, or auto-generated). Warns before Save if this barcode is
            // already registered on a DIFFERENT product, so the owner/employee never
            // accidentally overwrites or shares a code between two items.
            let _barcodeCheckTimer = null;

            function onBarcodeFieldChange() {
                clearTimeout(_barcodeCheckTimer);
                const msgEl = document.getElementById('p-barcode-check');
                const barcode = document.getElementById('p-barcode')?.value.trim();
                const editingId = document.getElementById('edit-id')?.value;
                if (!msgEl) return;
                if (!barcode) {
                    msgEl.textContent = '';
                    return;
                }
                msgEl.textContent = '⏳ Checking…';
                msgEl.style.color = 'var(--text3)';
                _barcodeCheckTimer = setTimeout(async () => {
                    const r = await apiGet('get_product_by_barcode', {
                        barcode
                    });
                    if (r?.success && r.data && String(r.data.id) !== String(editingId)) {
                        msgEl.innerHTML = '⚠️ Already used by <strong>' + r.data.name + '</strong> — choose a different code';
                        msgEl.style.color = 'var(--danger)';
                    } else {
                        msgEl.textContent = '✅ This barcode is available';
                        msgEl.style.color = 'var(--green)';
                    }
                }, 400);
            }

            // Recomputes Store/Warehouse Stock totals from their Cases + Bundles + Loose
            // Pcs sub-fields (cases/bundles only count if the ledger above has a
            // case_qty/pack_qty configured), and shows/hides the Cases/Bundles inputs
            // so a product with no Bundle or Case configured just shows a plain "Pcs"
            // field to type the total manually — per-product, not a global toggle.
            function updatePackHints() {
                const packQty = +(document.getElementById('p-pack-qty')?.value) || 0;
                const caseQty = +(document.getElementById('p-case-qty')?.value) || 0;

                ['p-qty', 'p-wh-qty'].forEach(prefix => {
                    const casesWrap = document.getElementById(prefix + '-cases-wrap');
                    const bundlesWrap = document.getElementById(prefix + '-bundles-wrap');
                    const looseLabel = document.getElementById(prefix + '-loose-label');
                    if (casesWrap) casesWrap.style.display = caseQty > 0 ? '' : 'none';
                    if (bundlesWrap) bundlesWrap.style.display = packQty > 0 ? '' : 'none';
                    if (looseLabel) looseLabel.textContent = (caseQty > 0 || packQty > 0) ? 'Loose Pcs' : 'Pcs';

                    const cases = +(document.getElementById(prefix + '-cases')?.value) || 0;
                    const bundles = +(document.getElementById(prefix + '-bundles')?.value) || 0;
                    const loose = +(document.getElementById(prefix + '-loose')?.value) || 0;
                    const total = (cases * caseQty) + (bundles * packQty) + loose;
                    const hidden = document.getElementById(prefix);
                    if (hidden) hidden.value = total;

                    const hint = document.getElementById(prefix + '-hint');
                    if (hint) {
                        const parts = [];
                        if (caseQty > 0 && cases > 0) parts.push(cases + ' case' + (cases !== 1 ? 's' : ''));
                        if (packQty > 0 && bundles > 0) parts.push(bundles + ' bundle' + (bundles !== 1 ? 's' : ''));
                        if (loose > 0) parts.push(loose + ' loose pc' + (loose !== 1 ? 's' : ''));
                        hint.textContent = 'Total: ' + total + ' Pcs' + (parts.length ? ' (' + parts.join(' + ') + ')' : '');
                    }
                });
            }

            // ── CATEGORY (custom dropdown combobox) ──
            // p-cat-input is what the user types/sees; p-cat (hidden) holds the resolved
            // category_id. If the typed text exactly matches an existing category name
            // (case-insensitive) we resolve it immediately; otherwise we leave the hidden
            // id blank and saveProduct() will create the new category on the fly.
            function syncCatFromInput() {
                const typed = (document.getElementById('p-cat-input')?.value || '').trim();
                const hidden = document.getElementById('p-cat');
                if (!hidden) return;
                const match = invCats.find(c => c.name.toLowerCase() === typed.toLowerCase());
                hidden.value = match ? match.id : '';
            }

            // Renders the dropdown panel, filtered to categories whose name contains
            // the currently typed text (empty text = show all, so tapping an empty
            // field still shows every category — the whole point of this custom
            // dropdown, since the native <input list=datalist> combo often didn't
            // show anything at all on tap on mobile Chrome).
            function renderCatDropdown() {
                const panel = document.getElementById('p-cat-dropdown');
                if (!panel) return;
                const typed = (document.getElementById('p-cat-input')?.value || '').trim().toLowerCase();
                const matches = rankAutocompleteMatches(invCats, typed, c => c.name);
                if (!matches.length) {
                    panel.innerHTML = typed
                        ? '<div class="cat-dropdown-empty">No match — Save will create "' + escapeHtml(document.getElementById('p-cat-input').value.trim()) + '" as a new category</div>'
                        : '<div class="cat-dropdown-empty">No categories yet — type a name to create one</div>';
                    return;
                }
                panel.innerHTML = matches.map(c =>
                    '<div class="cat-dropdown-item" onmousedown="event.preventDefault();selectCatOption(' + c.id + ')">' + escapeHtml(c.name) + '</div>'
                ).join('');
            }

            function openCatDropdown() {
                if (!invCats.length) {
                    loadInvCats().then(renderCatDropdown);
                } else {
                    renderCatDropdown();
                }
                document.getElementById('p-cat-dropdown')?.classList.add('open');
            }

            function closeCatDropdown() {
                document.getElementById('p-cat-dropdown')?.classList.remove('open');
            }

            function onCatInputType() {
                syncCatFromInput();
                renderCatDropdown();
                document.getElementById('p-cat-dropdown')?.classList.add('open');
            }

            function selectCatOption(id) {
                const match = invCats.find(c => c.id == id);
                if (!match) return;
                document.getElementById('p-cat-input').value = match.name;
                document.getElementById('p-cat').value = match.id;
                closeCatDropdown();
            }

            // Close the dropdown on any click outside it (a plain blur is too eager —
            // it'd fire before the onmousedown selection above gets to run).
            document.addEventListener('click', e => {
                const panel = document.getElementById('p-cat-dropdown');
                const input = document.getElementById('p-cat-input');
                if (panel && panel.classList.contains('open') && e.target !== input && !panel.contains(e.target)) {
                    closeCatDropdown();
                }
            });

            // Resolves the typed category name to an id, creating the category first if
            // it doesn't already exist. Returns a Promise<string|null> (category_id).
            async function resolveCategoryId() {
                const typed = (document.getElementById('p-cat-input')?.value || '').trim();
                if (!typed) return null;
                const match = invCats.find(c => c.name.toLowerCase() === typed.toLowerCase());
                if (match) return match.id;
                const r = await apiPost('add_category', {
                    name: typed
                });
                if (r?.success && r.data?.id) {
                    invCats.push({
                        id: r.data.id,
                        name: r.data.name || typed
                    });
                    return r.data.id;
                }
                return null;
            }

            // ── EXPIRY DATE (typeable MM/DD/YYYY, with a native picker fallback) ──
            // Auto-inserts slashes as the user types digits, and keeps the hidden
            // #p-expiry field in sync as an ISO yyyy-mm-dd string for the backend.
            function formatExpiryInput(el) {
                let v = el.value.replace(/[^\d]/g, '').slice(0, 8);
                let out = v;
                if (v.length >= 5) out = v.slice(0, 2) + '/' + v.slice(2, 4) + '/' + v.slice(4);
                else if (v.length >= 3) out = v.slice(0, 2) + '/' + v.slice(2);
                el.value = out;
                const hidden = document.getElementById('p-expiry');
                if (v.length === 8) {
                    const mm = v.slice(0, 2),
                        dd = v.slice(2, 4),
                        yyyy = v.slice(4);
                    if (hidden) hidden.value = yyyy + '-' + mm + '-' + dd;
                    const native = document.getElementById('p-expiry-native');
                    if (native) native.value = yyyy + '-' + mm + '-' + dd;
                } else if (hidden) {
                    hidden.value = '';
                }
            }

            function syncExpiryFromNative() {
                const iso = document.getElementById('p-expiry-native')?.value;
                if (!iso) return;
                const hidden = document.getElementById('p-expiry');
                if (hidden) hidden.value = iso;
                const [y, m, d] = iso.split('-');
                const display = document.getElementById('p-expiry-display');
                if (display) display.value = m + '/' + d + '/' + y;
            }
            // Sets both the display and hidden fields from an ISO date (used when
            // opening the edit modal with an existing expiry_date).
            function setExpiryFromIso(iso) {
                const hidden = document.getElementById('p-expiry');
                const display = document.getElementById('p-expiry-display');
                const native = document.getElementById('p-expiry-native');
                if (!iso) {
                    if (hidden) hidden.value = '';
                    if (display) display.value = '';
                    if (native) native.value = '';
                    return;
                }
                const [y, m, d] = iso.split('-');
                if (hidden) hidden.value = iso;
                if (display) display.value = m + '/' + d + '/' + y;
                if (native) native.value = iso;
            }

            // ── DELIVERY DATE (batch received) — same typeable MM/DD/YYYY + native
            // picker pattern as Expiry Date above, kept as its own independent field so
            // a product's "when it arrived" and "when it goes bad" can differ. ──
            function formatDeliveryInput(el) {
                let v = el.value.replace(/[^\d]/g, '').slice(0, 8);
                let out = v;
                if (v.length >= 5) out = v.slice(0, 2) + '/' + v.slice(2, 4) + '/' + v.slice(4);
                else if (v.length >= 3) out = v.slice(0, 2) + '/' + v.slice(2);
                el.value = out;
                const hidden = document.getElementById('p-delivery');
                if (v.length === 8) {
                    const mm = v.slice(0, 2),
                        dd = v.slice(2, 4),
                        yyyy = v.slice(4);
                    if (hidden) hidden.value = yyyy + '-' + mm + '-' + dd;
                    const native = document.getElementById('p-delivery-native');
                    if (native) native.value = yyyy + '-' + mm + '-' + dd;
                } else if (hidden) {
                    hidden.value = '';
                }
            }

            function syncDeliveryFromNative() {
                const iso = document.getElementById('p-delivery-native')?.value;
                if (!iso) return;
                const hidden = document.getElementById('p-delivery');
                if (hidden) hidden.value = iso;
                const [y, m, d] = iso.split('-');
                const display = document.getElementById('p-delivery-display');
                if (display) display.value = m + '/' + d + '/' + y;
            }
            // Sets both the display and hidden fields from an ISO date (used when
            // opening the edit modal with an existing delivery_date).
            function setDeliveryFromIso(iso) {
                const hidden = document.getElementById('p-delivery');
                const display = document.getElementById('p-delivery-display');
                const native = document.getElementById('p-delivery-native');
                if (!iso) {
                    if (hidden) hidden.value = '';
                    if (display) display.value = '';
                    if (native) native.value = '';
                    return;
                }
                const [y, m, d] = iso.split('-');
                if (hidden) hidden.value = iso;
                if (display) display.value = m + '/' + d + '/' + y;
                if (native) native.value = iso;
            }

            function downloadBarcode() {
                // Canvas already contains the correct rasterized PNG — read it directly
                const canvas = document.getElementById('barcode-canvas');
                const barcode = document.getElementById('p-barcode')?.value || 'bc';
                if (!canvas || !canvas.width) {
                    toast('Generate a barcode first', 'warning');
                    return;
                }
                const a = document.createElement('a');
                a.download = 'barcode_' + barcode + '.png';
                a.href = canvas.toDataURL('image/png');
                a.click();
                toast('Barcode downloaded!', 'success');
            }
            // Alias
            function downloadQR() {
                downloadBarcode();
            }

            function printBarcode() {
                // Read PNG straight from the already-rasterized canvas — zero chance of mirroring
                const canvas = document.getElementById('barcode-canvas');
                const name = document.getElementById('p-name')?.value || 'Product';
                const barcode = document.getElementById('p-barcode')?.value || '';
                if (!canvas || !canvas.width || !barcode) {
                    toast('No barcode to print', 'warning');
                    return;
                }
                const png = canvas.toDataURL('image/png');
                const win = window.open('', '_blank');
                if (!win) {
                    toast('Pop-up blocked — allow pop-ups for printing', 'warning');
                    return;
                }
                win.document.write(
                    '<!DOCTYPE html><html><head>' +
                    '<style>*{margin:0;padding:0;box-sizing:border-box;}' +
                    'body{font-family:Arial,sans-serif;text-align:center;padding:20px;background:#fff;}' +
                    'h3{font-size:13px;margin-bottom:3px;}' +
                    'p{font-size:10px;color:#666;margin-bottom:8px;letter-spacing:.05em;}' +
                    'img{display:block;margin:0 auto;max-width:280px;image-rendering:crisp-edges;image-rendering:-webkit-optimize-contrast;}' +
                    '@media print{@page{margin:8mm;}body{padding:10px;}}' +
                    '</style></head><body>' +
                    '<h3>' + name.replace(/</g, '&lt;') + '</h3>' +
                    '<p>' + barcode.replace(/</g, '&lt;') + '</p>' +
                    '<img src="' + png + '" alt="barcode"/>' +
                    '<script>window.onload=function(){window.print();window.close();}<\/script>' +
                    '</body></html>'
                );
                win.document.close();
            }
            // Alias
            function printQR() {
                printBarcode();
            }

            // ════════════════════════════════════════════════
            // PRINT ALL BARCODES (5 per row, custom qty each)
            // ════════════════════════════════════════════════
            // whProds populated by warehouseInit; fallback to empty
            let printAllProds = []; // full cached list backing the search filter below
            let printAllSelected = new Set(); // product ids checked — persists across search filtering

            function openPrintAllModal() {
                const prods = (typeof whProds !== 'undefined' ? whProds : []).filter(p => p.barcode);
                const searchEl = document.getElementById('print-all-search');
                if (searchEl) searchEl.value = '';
                printAllSelected = new Set();
                const selectAllEl = document.getElementById('print-all-select-all');
                if (selectAllEl) selectAllEl.checked = false;
                if (!prods.length) {
                    // Try fetching fresh
                    apiGet('get_warehouse_products').then(r => {
                        whProds = r?.data || [];
                        printAllProds = whProds.filter(p => p.barcode);
                        buildPrintAllList(printAllProds);
                        openModal('print-all-modal');
                    });
                    return;
                }
                printAllProds = prods;
                buildPrintAllList(printAllProds);
                openModal('print-all-modal');
            }

            // Re-filters the cached product list by name/barcode as the user types, so
            // they can find one specific product instead of scrolling the whole catalog.
            // Selections (printAllSelected) survive filtering, so ticking a few items,
            // searching for more, and ticking those too all accumulates correctly.
            function filterPrintAllList() {
                const q = (document.getElementById('print-all-search')?.value || '').toLowerCase().trim();
                if (!q) {
                    buildPrintAllList(printAllProds);
                    return;
                }
                const filtered = printAllProds.filter(p =>
                    p.name.toLowerCase().includes(q) || (p.barcode || '').toLowerCase().includes(q)
                );
                buildPrintAllList(filtered);
            }

            function updatePrintAllSelectedCount() {
                const el = document.getElementById('print-all-selected-count');
                if (el) el.textContent = printAllSelected.size + ' selected';
                // Select All reflects whether every currently-VISIBLE row is checked —
                // not the whole catalog — so it stays meaningful after a search filters
                // the list down.
                const visibleIds = [...document.querySelectorAll('.print-all-row-check')].map(c => parseInt(c.dataset.pid));
                const selectAllEl = document.getElementById('print-all-select-all');
                if (selectAllEl) selectAllEl.checked = visibleIds.length > 0 && visibleIds.every(id => printAllSelected.has(id));
            }

            function togglePrintAllRow(pid, checked) {
                if (checked) printAllSelected.add(pid);
                else printAllSelected.delete(pid);
                updatePrintAllSelectedCount();
            }

            // Selects/deselects every row currently visible (i.e. matching the active
            // search), not the entire catalog — so "Select All" after a search only
            // grabs the filtered set, which is what someone searching first would expect.
            function togglePrintAllSelectAll(checkboxEl) {
                const checked = checkboxEl.checked;
                document.querySelectorAll('.print-all-row-check').forEach(c => {
                    c.checked = checked;
                    const pid = parseInt(c.dataset.pid);
                    if (checked) printAllSelected.add(pid);
                    else printAllSelected.delete(pid);
                });
                updatePrintAllSelectedCount();
            }

            function buildPrintAllList(prods) {
                const el = document.getElementById('print-all-list');
                if (!el) return;
                if (!prods.length) {
                    el.innerHTML = '<p style="color:var(--text3);font-size:.83rem;text-align:center;padding:12px;">No matching products found.</p>';
                    updatePrintAllSelectedCount();
                    return;
                }
                el.innerHTML = prods.map(p =>
                    '<div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid var(--border);">' +
                    '<input type="checkbox" class="print-all-row-check" data-pid="' + p.id + '" ' +
                    (printAllSelected.has(p.id) ? 'checked' : '') + ' onchange="togglePrintAllRow(' + p.id + ',this.checked)" ' +
                    'aria-label="Select ' + escapeHtml(p.name) + ' for printing"/>' +
                    '<div style="flex:1;font-size:.84rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(p.name) + '</div>' +
                    // Barcode is now a real clickable button — opens the same barcode
                    // preview/print/download modal used everywhere else, so a single item
                    // can be printed right from here without going through "Print All".
                    '<button type="button" onclick="showProductBarcode(' + p.id + ',' + jsAttr(p.barcode) + ',' + jsAttr(p.name) + ')" ' +
                    'style="font-size:.72rem;color:var(--accent);background:var(--surface2);border:1px solid var(--border);border-radius:5px;padding:3px 7px;cursor:pointer;min-width:90px;text-align:center;" ' +
                    'title="Click to preview / print this barcode">' + escapeHtml(p.barcode) + '</button>' +
                    '<div style="display:flex;align-items:center;gap:4px;flex-shrink:0;">' +
                    '<label style="font-size:.72rem;color:var(--text2);">Qty:</label>' +
                    '<input type="number" min="1" max="200" value="1" class="bc-qty-inp" data-pid="' + p.id + '" ' +
                    'data-barcode="' + p.barcode + '" data-name="' + (p.name || '').replace(/"/g, '&quot;') + '" ' +
                    'style="width:52px;padding:3px 6px;border:1.5px solid var(--border);border-radius:6px;font-size:.8rem;"/>' +
                    '</div>' +
                    '<button type="button" class="btn btn-secondary btn-sm" onclick="printWhBarcode(' + jsAttr(p.barcode) + ',' + jsAttr(p.name) + ')" title="Print just this product">🖨️</button>' +
                    '</div>'
                ).join('');
                updatePrintAllSelectedCount();
            }

            // Sticker label presets, keyed by how many print per row (matches how
            // sticker rolls are actually sold/labeled, e.g. "3 in 1 row"). cols = labels
            // printed per row; bar* controls JsBarcode's own rendered size; the
            // *FontSize values scale the product name / barcode-number text underneath
            // so tiny labels don't get text bigger than the label itself.
            const LABEL_SIZES = {
                r6: {
                    cols: 2,
                    barWidth: 2.4,
                    barHeight: 64,
                    barFontSize: 12,
                    nameFontSize: 10,
                    codeFontSize: 9
                },
                r5: {
                    cols: 3,
                    barWidth: 2.0,
                    barHeight: 55,
                    barFontSize: 10,
                    nameFontSize: 9,
                    codeFontSize: 8
                },
                r4: {
                    cols: 4,
                    barWidth: 1.8,
                    barHeight: 48,
                    barFontSize: 9,
                    nameFontSize: 8,
                    codeFontSize: 7
                },
                r3: {
                    cols: 5,
                    barWidth: 1.5,
                    barHeight: 38,
                    barFontSize: 8,
                    nameFontSize: 7,
                    codeFontSize: 6
                },
                r2: {
                    cols: 6,
                    barWidth: 1.2,
                    barHeight: 30,
                    barFontSize: 7,
                    nameFontSize: 6.5,
                    codeFontSize: 5.5
                },
            };

            async function doPrintAll() {
                const sizeKey = document.getElementById('print-label-size')?.value || 'r3';
                const size = LABEL_SIZES[sizeKey] || LABEL_SIZES.r3;

                // Only the ticked rows get printed — this is the whole point of the
                // checkboxes/Select All, so "Print" never silently prints the entire
                // catalog just because it happened to be the current search result.
                if (!printAllSelected.size) {
                    toast('Select at least one product first', 'warning');
                    return;
                }

                const items = [];
                document.querySelectorAll('.bc-qty-inp').forEach(inp => {
                    const pid = parseInt(inp.dataset.pid);
                    if (!printAllSelected.has(pid)) return;
                    const qty = Math.max(1, Math.min(200, parseInt(inp.value) || 1));
                    for (let i = 0; i < qty; i++) {
                        items.push({
                            barcode: inp.dataset.barcode,
                            name: inp.dataset.name
                        });
                    }
                });
                // A selected product can fall outside the CURRENT search filter (it was
                // ticked before searching for something else), so its qty input isn't in
                // the DOM right now — fall back to qty 1 for those from the full cached list.
                const visiblePids = new Set([...document.querySelectorAll('.bc-qty-inp')].map(i => parseInt(i.dataset.pid)));
                printAllProds.forEach(p => {
                    if (printAllSelected.has(p.id) && !visiblePids.has(p.id) && p.barcode) {
                        items.push({
                            barcode: p.barcode,
                            name: p.name
                        });
                    }
                });
                if (!items.length) {
                    toast('No items to print', 'error');
                    return;
                }

                toast('Rasterizing barcodes… please wait', 'default');

                // De-duplicate barcodes so we only rasterize each unique code once
                const unique = [...new Map(items.map(it => [it.barcode, it])).values()];
                const pngCache = {};

                // Render each unique barcode to a PNG using an offscreen SVG → canvas pipeline
                for (const it of unique) {
                    await new Promise(resolve => {
                        const tmpSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                        tmpSvg.style.cssText = 'position:absolute;left:-9999px;top:-9999px;';
                        document.body.appendChild(tmpSvg);
                        try {
                            JsBarcode(tmpSvg, it.barcode, {
                                format: 'CODE128',
                                width: size.barWidth,
                                height: size.barHeight,
                                displayValue: true,
                                fontSize: size.barFontSize,
                                margin: 8,
                                marginLeft: 8,
                                marginRight: 8,
                                background: '#ffffff',
                                lineColor: '#000000'
                            });
                        } catch (e) {
                            document.body.removeChild(tmpSvg);
                            resolve();
                            return;
                        }
                        svgToCanvasPng(tmpSvg, (png) => {
                            document.body.removeChild(tmpSvg);
                            if (png) pngCache[it.barcode] = png;
                            resolve();
                        });
                    });
                }

                // Build label cells using <img> tags (PNGs) — never raw SVG
                const COLS = size.cols;
                const cellWidthPct = (100 / COLS).toFixed(4) + '%';
                let rows = '';
                for (let i = 0; i < items.length; i += COLS) {
                    const chunk = items.slice(i, i + COLS);
                    while (chunk.length < COLS) chunk.push(null);
                    const cells = chunk.map(it => {
                        if (!it) return '<td style="width:' + cellWidthPct + ';padding:4px;"></td>';
                        const png = pngCache[it.barcode] || '';
                        return '<td style="width:' + cellWidthPct + ';padding:4px;text-align:center;vertical-align:top;border:1px dashed #ccc;">' +
                            (png ?
                                '<img src="' + png + '" style="max-width:100%;height:auto;display:block;margin:0 auto;image-rendering:crisp-edges;" alt="barcode"/>' :
                                '<div style="height:40px;line-height:40px;font-size:9px;color:#c00;">Error</div>'
                            ) +
                            '<div style="font-size:' + size.nameFontSize + 'px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px;">' + (it.name || '').replace(/</g, '&lt;') + '</div>' +
                            '<div style="font-size:' + size.codeFontSize + 'px;color:#888;">' + (it.barcode || '').replace(/</g, '&lt;') + '</div>' +
                            '</td>';
                    }).join('');
                    rows += '<tr>' + cells + '</tr>';
                }

                const win = window.open('', '_blank');
                if (!win) {
                    toast('Pop-up blocked — allow pop-ups for printing', 'warning');
                    return;
                }
                win.document.write(
                    '<!DOCTYPE html><html><head><title>Barcode Labels</title>' +
                    '<style>*{margin:0;padding:0;box-sizing:border-box;}' +
                    'body{font-family:Arial,sans-serif;background:#fff;}' +
                    'table{width:100%;border-collapse:collapse;}' +
                    'img{image-rendering:-webkit-optimize-contrast;image-rendering:crisp-edges;}' +
                    '@media print{@page{margin:6mm;}}</style>' +
                    '</head><body>' +
                    '<table>' + rows + '</table>' +
                    '<script>window.onload=function(){window.print();window.close();}<\/script>' +
                    '</body></html>'
                );
                win.document.close();
                toast('✅ Sent ' + items.length + ' label' + (items.length > 1 ? 's' : '') + ' to print', 'success');
                closeModal('print-all-modal');
            }

            // ════════════════════════════════════════════════
            // ════════════════════════════════════════════════
            // BARCODE SCANNER — Multi-method: BarcodeDetector → ZXing → jsQR
            // Handles: Code128, EAN-13, EAN-8, UPC-A, UPC-E, QR, Code39, Code93, ITF, PDF417
            // Works at any angle, any position, any distance
            // ════════════════════════════════════════════════
            let scanStream = null,
                scanInterval = null,
                scanCooldown = false;
            let _barcodeDetector = null,
                _zxingReader = null;

            // Pre-init BarcodeDetector and ZXing as early as possible
            async function initScanEngines() {
                // 1. Native BarcodeDetector (Chrome/Edge/Android — handles ALL formats natively)
                if ('BarcodeDetector' in window) {
                    try {
                        const supported = await BarcodeDetector.getSupportedFormats().catch(() => []);
                        const formats = supported.length > 0 ? supported : [
                            'code_128', 'ean_13', 'ean_8', 'upc_a', 'upc_e', 'qr_code',
                            'code_39', 'code_93', 'itf', 'pdf417', 'aztec', 'data_matrix'
                        ];
                        _barcodeDetector = new BarcodeDetector({
                            formats
                        });
                    } catch (e) {
                        _barcodeDetector = null;
                    }
                }

                // 2. ZXing — comprehensive barcode library (any orientation, any type)
                if (typeof ZXing !== 'undefined') {
                    try {
                        const hints = new Map();
                        // Enable all supported formats for maximum compatibility
                        if (ZXing.DecodeHintType) {
                            hints.set(ZXing.DecodeHintType.TRY_HARDER, true);
                            hints.set(ZXing.DecodeHintType.POSSIBLE_FORMATS, [
                                ZXing.BarcodeFormat.CODE_128,
                                ZXing.BarcodeFormat.EAN_13,
                                ZXing.BarcodeFormat.EAN_8,
                                ZXing.BarcodeFormat.UPC_A,
                                ZXing.BarcodeFormat.UPC_E,
                                ZXing.BarcodeFormat.CODE_39,
                                ZXing.BarcodeFormat.CODE_93,
                                ZXing.BarcodeFormat.ITF,
                                ZXing.BarcodeFormat.PDF_417,
                                ZXing.BarcodeFormat.QR_CODE,
                                ZXing.BarcodeFormat.DATA_MATRIX,
                                ZXing.BarcodeFormat.AZTEC,
                            ].filter(Boolean));
                        }
                        _zxingReader = new ZXing.BrowserMultiFormatReader(hints);
                    } catch (e) {
                        _zxingReader = null;
                    }
                }
            }
            initScanEngines();

            // ── Core decode function — tries all 3 engines in order ──
            async function tryDecode(video, canvas) {
                // Guard: video must be playing with valid dimensions
                const vw = video.videoWidth;
                const vh = video.videoHeight;
                if (!vw || !vh) return null;

                // Method 1: Native BarcodeDetector (fastest, any rotation, all formats)
                if (_barcodeDetector) {
                    try {
                        const results = await _barcodeDetector.detect(video);
                        if (results && results.length > 0) return results[0].rawValue;
                    } catch (e) {}
                }

                // Shared canvas snapshot — draw once, reuse for ZXing + jsQR
                let snapshotCanvas = canvas;
                if (!snapshotCanvas || typeof snapshotCanvas.getContext !== 'function') {
                    snapshotCanvas = document.createElement('canvas');
                }
                snapshotCanvas.width = vw;
                snapshotCanvas.height = vh;
                const ctx = snapshotCanvas.getContext('2d');
                ctx.drawImage(video, 0, 0, vw, vh);

                // Method 2: ZXing decodeFromCanvas (handles Code128, EAN, UPC, QR, Code39, etc.)
                if (_zxingReader) {
                    try {
                        const result = await _zxingReader.decodeFromCanvas(snapshotCanvas);
                        if (result && result.getText()) return result.getText();
                    } catch (e) {
                        // NotFoundException is thrown when no barcode found — this is normal, ignore
                    }
                }

                // Method 3: jsQR (QR codes — reliable fallback)
                if (typeof jsQR !== 'undefined') {
                    try {
                        const imgData = ctx.getImageData(0, 0, vw, vh);
                        const code = jsQR(imgData.data, vw, vh, {
                            inversionAttempts: 'attemptBoth'
                        });
                        if (code && code.data) return code.data;
                    } catch (e) {}
                }

                return null; // Nothing decoded
            }

            // ── Start camera scanner ──
            async function startScanner(videoId, canvasId, onResult) {
                // The browser only exposes navigator.mediaDevices on secure origins
                // (https:// or localhost). On plain http://, mediaDevices is undefined
                // entirely — NOT a permission problem — so calling .getUserMedia on it
                // throws "Cannot read properties of undefined (reading 'getUserMedia')".
                // Catching this case up front turns that cryptic error into an actionable
                // one, and tells the cashier the manual barcode field still works.
                if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                    const isSecure = window.isSecureContext;
                    if (!isSecure) {
                        toast('📷 Camera needs a secure (https://) connection — this page loaded over http://. Use manual entry below, or ask your admin to enable HTTPS.', 'error');
                    } else {
                        toast('📷 Camera not supported on this browser — use manual entry below', 'warning');
                    }
                    return;
                }

                try {
                    // Request back camera first, fallback to any camera
                    let stream;
                    try {
                        stream = await navigator.mediaDevices.getUserMedia({
                            video: {
                                facingMode: {
                                    ideal: 'environment'
                                },
                                width: {
                                    ideal: 1280,
                                    min: 640
                                },
                                height: {
                                    ideal: 720,
                                    min: 480
                                },
                            }
                        });
                    } catch (e) {
                        // Fallback: any camera with relaxed constraints
                        stream = await navigator.mediaDevices.getUserMedia({
                            video: true
                        });
                    }
                    scanStream = stream;

                    const video = document.getElementById(videoId);
                    if (!video) {
                        stream.getTracks().forEach(t => t.stop());
                        return;
                    }
                    video.srcObject = stream;
                    video.setAttribute('playsinline', 'true'); // iOS Safari
                    video.muted = true;

                    // Wait for video to actually start playing with valid dimensions
                    await new Promise((resolve, reject) => {
                        const timeout = setTimeout(() => reject(new Error('Video timeout')), 10000);
                        const check = () => {
                            if (video.readyState >= 2 && video.videoWidth > 0 && video.videoHeight > 0) {
                                clearTimeout(timeout);
                                resolve();
                            } else {
                                video.play().catch(() => {});
                                setTimeout(check, 100);
                            }
                        };
                        video.addEventListener('loadedmetadata', check, {
                            once: true
                        });
                        video.addEventListener('canplay', check, {
                            once: true
                        });
                        video.play().catch(() => {});
                        setTimeout(check, 300); // initial check in case events already fired
                    }).catch(() => {}); // non-fatal — interval will check readyState anyway

                    // Offscreen canvas for pixel decoding — always create one
                    let offscreen = canvasId ? document.getElementById(canvasId) : null;
                    if (!offscreen || typeof offscreen.getContext !== 'function') {
                        offscreen = document.createElement('canvas');
                        offscreen.style.display = 'none';
                    }

                    scanCooldown = false;
                    let _zxingActive = false;

                    scanInterval = setInterval(async () => {
                        if (scanCooldown) return;
                        if (video.readyState < 2 || !video.videoWidth || !video.videoHeight) return;
                        if (_zxingActive) return; // prevent overlapping async decode
                        _zxingActive = true;
                        try {
                            const code = await tryDecode(video, offscreen);
                            if (code && !scanCooldown) {
                                scanCooldown = true;
                                onResult(code.trim());
                            }
                        } catch (e) {
                            // ignore decode errors
                        } finally {
                            _zxingActive = false;
                        }
                    }, 300);

                } catch (e) {
                    if (e.name === 'NotAllowedError') {
                        toast('📷 Camera permission denied — use manual entry below', 'warning');
                    } else if (e.name === 'NotFoundError') {
                        toast('No camera found — use manual entry below', 'warning');
                    } else {
                        toast('Camera error: ' + e.message, 'error');
                    }
                }
            }

            function stopScanner() {
                if (scanInterval) {
                    clearInterval(scanInterval);
                    scanInterval = null;
                }
                if (scanStream) {
                    scanStream.getTracks().forEach(t => t.stop());
                    scanStream = null;
                }
                scanCooldown = false;
            }

            function resumeScanning(ms) {
                setTimeout(() => {
                    if (scanStream) scanCooldown = false;
                }, ms || 1800);
            }

            // ── DASHBOARD SCANNER ──
            // Ensure a hidden canvas exists for the dash scanner (ZXing needs it)
            function ensureDashScanCanvas() {
                let c = document.getElementById('dash-scan-canvas');
                if (!c) {
                    c = document.createElement('canvas');
                    c.id = 'dash-scan-canvas';
                    c.style.display = 'none';
                    const modal = document.getElementById('dash-scan-modal');
                    if (modal) modal.appendChild(c);
                    else document.body.appendChild(c);
                }
                return c;
            }

            function openDashScan() {
                // Stop any running scanner before opening a new one
                stopScanner();
                openModal('dash-scan-modal');
                updateScanCartCount();
                ensureDashScanCanvas();
                const statusEl = document.getElementById('dash-scan-status');
                if (statusEl) statusEl.textContent = '📷 Point at any barcode — Code128, QR, EAN, UPC all supported';
                startScanner('dash-scan-video', 'dash-scan-canvas', code => {
                    let barcode = code.trim();
                    try {
                        const d = JSON.parse(code);
                        barcode = (d.barcode || code).trim();
                    } catch (e) {}
                    barcode = barcode.replace(/[\s\r\n\t]/g, '');
                    if (!barcode) {
                        resumeScanning(800);
                        return;
                    }
                    if (statusEl) statusEl.textContent = '⏳ Looking up: ' + barcode;
                    apiGet('get_product_by_barcode', {
                        barcode
                    }).then(r => {
                        if (!r?.success) {
                            toast('❌ Not found: ' + barcode, 'error');
                            if (statusEl) statusEl.textContent = '❌ Not found — try next item';
                            resumeScanning(2000);
                            return;
                        }
                        const p = r.data;
                        // Ensure product is in allProds so addToCart can find it
                        if (!allProds.find(x => x.id == p.id)) allProds.push(p);
                        const addQty = scanUnitQty(p);
                        addToCart(p.id, addQty);
                        updateScanCartCount();
                        if (statusEl) statusEl.textContent = '✅ Added: ' + p.name + (addQty > 1 ? ' ×' + addQty : '') + ' — ready for next scan';
                        toast('✅ Added: ' + p.name + (addQty > 1 ? ' ×' + addQty : ''), 'success');
                        resumeScanning(1800);
                    }).catch(() => {
                        if (statusEl) statusEl.textContent = '⚠️ Network error — try again';
                        resumeScanning(2000);
                    });
                });
            }

            function updateScanCartCount() {
                const cnt = (typeof cart !== 'undefined') ? cart.reduce((s, c) => s + c.qty, 0) : 0;
                const el = document.getElementById('scan-cart-count');
                if (el) el.textContent = cnt;
            }

            function closeDashScan() {
                stopScanner();
                closeModal('dash-scan-modal');
            }

            function dashManualLookup() {
                const bc = document.getElementById('dash-manual-bc')?.value.trim();
                if (!bc) return;
                let barcode = bc.replace(/[\s\r\n\t]/g, '');
                try {
                    const d = JSON.parse(bc);
                    barcode = (d.barcode || bc).trim();
                } catch (e) {}
                apiGet('get_product_by_barcode', {
                    barcode
                }).then(r => {
                    if (!r?.success) {
                        toast('Not found: ' + barcode, 'error');
                        return;
                    }
                    const p = r.data;
                    if (!allProds.find(x => x.id == p.id)) allProds.push(p);
                    const addQty = scanUnitQty(p);
                    addToCart(p.id, addQty);
                    updateScanCartCount();
                    document.getElementById('dash-manual-bc').value = '';
                    toast('Added: ' + p.name + (addQty > 1 ? ' ×' + addQty : ''), 'success');
                });
            }

            // ════════════════════════════════════════════════
            // DRAGGABLE SCANNER BUTTON
            // ════════════════════════════════════════════════
            function initDraggableScanner() {
                const el = document.getElementById('scanner-float');
                if (!el) return;
                let dragging = false,
                    startX, startY, origL, origT, moved = false;

                function pointerStart(cx, cy) {
                    dragging = true;
                    moved = false;
                    startX = cx;
                    startY = cy;
                    const r = el.getBoundingClientRect();
                    origL = r.left;
                    origT = r.top;
                    el.style.right = 'auto';
                    el.style.bottom = 'auto';
                    el.style.left = origL + 'px';
                    el.style.top = origT + 'px';
                }

                function pointerMove(cx, cy) {
                    if (!dragging) return;
                    const dx = cx - startX,
                        dy = cy - startY;
                    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) moved = true;
                    const maxL = window.innerWidth - el.offsetWidth;
                    const maxT = window.innerHeight - el.offsetHeight;
                    el.style.left = Math.max(0, Math.min(maxL, origL + dx)) + 'px';
                    el.style.top = Math.max(0, Math.min(maxT, origT + dy)) + 'px';
                }

                function pointerEnd() {
                    dragging = false;
                }

                el.addEventListener('mousedown', e => {
                    e.preventDefault();
                    pointerStart(e.clientX, e.clientY);
                });
                document.addEventListener('mousemove', e => pointerMove(e.clientX, e.clientY));
                document.addEventListener('mouseup', pointerEnd);

                el.addEventListener('touchstart', e => {
                    pointerStart(e.touches[0].clientX, e.touches[0].clientY);
                }, {
                    passive: true
                });
                document.addEventListener('touchmove', e => {
                    if (dragging) {
                        e.preventDefault();
                        pointerMove(e.touches[0].clientX, e.touches[0].clientY);
                    }
                }, {
                    passive: false
                });
                document.addEventListener('touchend', pointerEnd);
            }

            // ════════════════════════════════════════════════
            // WAREHOUSE PAGE
            // ════════════════════════════════════════════════
            let whProds = [],
                whFilter = 'all',
                whFilteredList = [];

            function warehouseInit() {
                if (cur_page !== 'warehouse') return;
                apiGet('get_settings').then(s => {
                    CUR = s?.data?.currency || '₱';
                });
                loadWhProducts();
                loadWhLog();
                loadAlertBanner();
            }

            function loadWhProducts() {
                apiGet('get_products').then(r => {
                    if (!r?.success) return;
                    whProds = r.data;
                    updateWhStats();
                    renderWhProducts();
                });
            }

            function updateWhStats() {
                const total = whProds.length;
                // Uses store_quantity — the same figure shown in the "Store" column and
                // relied on by the Low Stock / Out of Stock filter pills below — instead
                // of the legacy `quantity` field, which can drift from it.
                // FIX: this used to require sq > 0, which silently excluded every
                // Out-of-Stock item (sq === 0) from the count — so a shelf that's
                // completely empty for 5 products showed "Low Stock: 0" right next to
                // 5 rows tagged "Out of Stock" on the same page. Out of stock IS the most
                // urgent form of low stock, so it's included here now.
                const low = whProds.filter(p => {
                    const sq = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                    return sq <= (p.low_stock_threshold ?? 5);
                }).length;
                // FIX: this used to be price (selling price) × quantity (the legacy,
                // largely-unused field) — selling price isn't "cost", and `quantity`
                // drifts to 0 once a product uses the store/warehouse split, which is
                // why this showed ₱0.00 even with thousands of units on hand. Now uses
                // the real Cost Price field × units actually on hand across BOTH
                // locations (store + warehouse) — a true at-cost inventory valuation.
                // Products with no Cost Price set yet contribute ₱0 for themselves only
                // (not the whole total), so it's safe to fill these in gradually.
                const value = whProds.reduce((s, p) => {
                    const cost = parseFloat(p.cost_price);
                    if (isNaN(cost)) return s;
                    const sq = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                    const wq = p.warehouse_quantity ?? 0;
                    return s + cost * (sq + wq);
                }, 0);
                const missingCost = whProds.filter(p => p.cost_price === null || p.cost_price === undefined || p.cost_price === '').length;
                // FIX: a strict 7-day window meant this almost always read 0 for a
                // small store restocking every week or two — not wrong, just not useful
                // as an early warning. 30 days gives enough lead time to actually mark
                // it down or bundle it before it expires. Comparing plain YYYY-MM-DD
                // strings (not Date objects) also avoids a timezone off-by-one where a
                // product expiring "today" could fall just outside the window.
                const todayStr = new Date().toISOString().slice(0, 10);
                const in30 = new Date();
                in30.setDate(in30.getDate() + 30);
                const in30Str = in30.toISOString().slice(0, 10);
                const expiring = whProds.filter(p => {
                    if (!p.expiry_date) return false;
                    const expStr = String(p.expiry_date).slice(0, 10);
                    return expStr >= todayStr && expStr <= in30Str;
                }).length;
                document.getElementById('wh-total').textContent = total;
                document.getElementById('wh-low').textContent = low;
                document.getElementById('wh-value').textContent = CUR + value.toFixed(2) + (missingCost ? ' *' : '');
                const valSub = document.getElementById('wh-value-sub');
                if (valSub) valSub.textContent = missingCost ? ('at cost · * ' + missingCost + ' product(s) missing a Cost Price') : 'at cost price';
                document.getElementById('wh-expiring').textContent = expiring;
                const expSub = document.getElementById('wh-expiring-sub');
                if (expSub) expSub.textContent = 'within 30 days';
            }

            function setWhFilter(f, btn) {
                whFilter = f;
                document.querySelectorAll('#wh-filter-pills .cat-pill').forEach(b => b.classList.remove('active'));
                if (btn) btn.classList.add('active');
                renderWhProducts();
            }

            // Splits a raw piece count into { cases, bundles, pcs } using this product's
            // configured Case/Bundle sizes (case_qty/pack_qty) — largest unit first.
            // Single source of truth for "how many cases/bundles/pcs is this total",
            // shared by the Warehouse table display (formatUnitBreakdown, below) AND the
            // Add/Edit Product form, which used to re-flatten every saved quantity back
            // into a single "Loose Pcs" number on every edit, losing whatever Cases/
            // Bundles split was originally entered (e.g. "24 Cases" would reappear as
            // "0 Cases, 2880 Loose Pcs" the next time the product was opened).
            function splitQtyIntoUnits(qty, p) {
                qty = parseInt(qty) || 0;
                const caseQty = parseInt(p.case_qty) || 0;
                const packQty = parseInt(p.pack_qty) || 0;
                let remaining = qty;
                let cases = 0,
                    bundles = 0;
                if (caseQty > 0) {
                    cases = Math.floor(remaining / caseQty);
                    remaining -= cases * caseQty;
                }
                if (packQty > 0) {
                    bundles = Math.floor(remaining / packQty);
                    remaining -= bundles * packQty;
                }
                return {
                    cases,
                    bundles,
                    pcs: remaining
                };
            }

            // Converts a raw piece count into "X case(s) + Y bundle(s) + Z pcs" for
            // display — e.g. a warehouse count of 2880 pcs on a 120-pcs case reads as
            // "24 cases" instead of a bare number. Falls back to plain "N pcs" for any
            // product that hasn't configured Bundle/Case tiers. Purely a display
            // transformation — the underlying stored value is always the raw pcs total.
            function formatUnitBreakdown(qty, p) {
                const {
                    cases,
                    bundles,
                    pcs
                } = splitQtyIntoUnits(qty, p);
                const caseQty = parseInt(p.case_qty) || 0;
                const packQty = parseInt(p.pack_qty) || 0;
                if (!caseQty && !packQty) return (parseInt(qty) || 0) + ' pcs';
                const parts = [];
                if (cases > 0) parts.push(cases + ' case' + (cases === 1 ? '' : 's'));
                if (bundles > 0) parts.push(bundles + ' bundle' + (bundles === 1 ? '' : 's'));
                if (pcs > 0 || !parts.length) parts.push(pcs + ' pcs');
                return parts.join(' + ');
            }

            function getExpiryStatus(expiry_date) {
                if (!expiry_date) return null;
                const today = new Date();
                today.setHours(0, 0, 0, 0);
                const exp = new Date(expiry_date);
                exp.setHours(0, 0, 0, 0);
                const diff = Math.ceil((exp - today) / (1000 * 60 * 60 * 24));
                if (diff < 0) return {
                    label: 'EXPIRED',
                    cls: 'expired',
                    days: diff
                };
                if (diff <= 3) return {
                    label: diff === 0 ? 'Expires TODAY' : 'Expires in ' + diff + 'd',
                    cls: 'critical',
                    days: diff
                };
                if (diff <= 7) return {
                    label: 'Expires in ' + diff + 'd',
                    cls: 'soon',
                    days: diff
                };
                if (diff <= 30) return {
                    label: 'Expires in ' + diff + 'd',
                    cls: 'upcoming',
                    days: diff
                };
                return {
                    label: exp.toLocaleDateString('en', {
                        month: 'short',
                        day: 'numeric',
                        year: 'numeric'
                    }),
                    cls: 'ok',
                    days: diff
                };
            }

            function renderWhProducts() {
                const q = (document.getElementById('wh-search')?.value || '').toLowerCase();
                const today = new Date();
                today.setHours(0, 0, 0, 0);
                const in30 = new Date(today);
                in30.setDate(today.getDate() + 30);

                let list = whProds.filter(p => {
                    if (q) {
                        const hit = p.name.toLowerCase().includes(q) ||
                            (p.barcode || '').toLowerCase().includes(q) ||
                            (p.brand || '').toLowerCase().includes(q) ||
                            (p.supplier || '').toLowerCase().includes(q);
                        if (!hit) return false;
                    }
                    // store_quantity is what the table's "Store" column actually shows, so the
                    // filter pills must key off the same field — otherwise a product can look
                    // "Low Stock" in the table but never appear when that pill is clicked (or
                    // vice versa) whenever the legacy `quantity` field has drifted from it.
                    const sq = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                    if (whFilter === 'low') return sq > 0 && sq <= (p.low_stock_threshold ?? 5);
                    if (whFilter === 'out') return sq == 0;
                    if (whFilter === 'expiring') {
                        if (!p.expiry_date) return false;
                        const exp = new Date(p.expiry_date);
                        return exp >= today && exp <= in30;
                    }
                    if (whFilter === 'expired') {
                        if (!p.expiry_date) return false;
                        return new Date(p.expiry_date) < today;
                    }
                    return true;
                });
                whFilteredList = list; // captured for the "Export to Excel" button — exports exactly what's on screen

                const body = document.getElementById('wh-body');
                const empty = document.getElementById('wh-empty');
                if (!list.length) {
                    body.innerHTML = '';
                    empty.style.display = 'block';
                    return;
                }
                empty.style.display = 'none';

                body.innerHTML = list.map(p => {
                    const expSt = getExpiryStatus(p.expiry_date);
                    const expiryHTML = expSt ?
                        '<span class="expiry-' + expSt.cls + '">' + expSt.label + '</span>' :
                        '<span style="color:var(--text3);font-size:.78rem;">—</span>';

                    const storeQty = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                    const whQty = p.warehouse_quantity !== undefined ? p.warehouse_quantity : 0;
                    const threshold = p.low_stock_threshold ?? 5;

                    let statusHTML;
                    if (storeQty == 0) statusHTML = '<span class="status-pill status-out">Out of Stock</span>';
                    else if (storeQty <= threshold) statusHTML = '<span class="status-pill status-low">Low Store</span>';
                    else if (expSt && expSt.cls === 'expired') statusHTML = '<span class="status-pill status-expired">Expired</span>';
                    else if (expSt && (expSt.cls === 'critical' || expSt.cls === 'soon' || expSt.cls === 'upcoming')) statusHTML = '<span class="status-pill status-expiring">Expiring</span>';
                    else statusHTML = '<span class="status-pill status-ok">Good</span>';

                    const storeColor = storeQty <= 0 ? 'var(--danger)' : storeQty <= threshold ? 'var(--accent2)' : 'var(--green)';
                    const whColor = whQty <= 0 ? 'var(--text3)' : 'var(--green)';
                    // Explicit Cases / Bundle / Pcs columns for Store & Warehouse — same
                    // splitQtyIntoUnits() math that used to only feed the subtext under the
                    // single Store/Warehouse totals, now broken out into its own cells so
                    // each unit is readable at a glance instead of parsed out of a string.
                    const storeUnits = splitQtyIntoUnits(storeQty, p);
                    const whUnits = splitQtyIntoUnits(whQty, p);
                    const unitCell = (n, color) => '<td style="text-align:center;' + (color ? 'color:' + color + ';' : '') + '">' + (n > 0 ? n : '—') + '</td>';

                    // Adjustments: cumulative damaged / expired / customer-return totals for
                    // this product, from the Pull-Out & Returns log (inventory_adjustments) —
                    // separate from ordinary sales, so shrinkage is visible at a glance
                    // instead of buried inside the Store/Warehouse numbers. Blank when a
                    // product has never had one, so normal fast-movers don't get cluttered.
                    const dmg = parseInt(p.qty_damaged) || 0;
                    const exp2 = parseInt(p.qty_expired) || 0;
                    const retWrite = parseInt(p.qty_returned_writeoff) || 0;
                    const retStock = parseInt(p.qty_returned_restocked) || 0;
                    const adjChips = [];
                    if (dmg) adjChips.push('<span class="adj-chip adj-damaged" title="Damaged on delivery">💔 ' + dmg + '</span>');
                    if (exp2) adjChips.push('<span class="adj-chip adj-expired" title="Pulled out expired">⏰ ' + exp2 + '</span>');
                    if (retWrite) adjChips.push('<span class="adj-chip adj-writeoff" title="Customer returns written off">↩️✕ ' + retWrite + '</span>');
                    if (retStock) adjChips.push('<span class="adj-chip adj-restocked" title="Customer returns put back into stock">↩️✓ ' + retStock + '</span>');
                    const adjHTML = adjChips.length ? adjChips.join(' ') : '<span style="color:var(--text3);font-size:.75rem;">—</span>';

                    const deliveryHTML = (p.delivery_date ?
                            '<span style="font-size:.78rem;">' + p.delivery_date.slice(0, 10) + '</span>' :
                            '<span style="color:var(--text3);font-size:.78rem;">—</span>') +
                        (parseInt(p.batch_count) > 0 ?
                            '<div><button type="button" onclick="openWhProductDetails(' + p.id + ')" style="background:var(--surface2);border:none;border-radius:6px;padding:1px 6px;font-size:.68rem;cursor:pointer;color:var(--text2);margin-top:2px;" title="View batches, FEFO order">📦 ' + p.batch_count + (p.batch_count == 1 ? ' batch' : ' batches') + '</button></div>' :
                            '');

                    const restockDateHTML = p.last_restock_date ?
                        '<span style="font-size:.78rem;">' + p.last_restock_date.slice(0, 10) + '</span>' :
                        '<span style="color:var(--text3);font-size:.78rem;">—</span>';
                    const pulloutDateHTML = p.last_pullout_date ?
                        '<span style="font-size:.78rem;">' + p.last_pullout_date.slice(0, 10) + '</span>' :
                        '<span style="color:var(--text3);font-size:.78rem;">—</span>';

                    return '<tr>' +
                        '<td><div style="font-weight:600;font-size:.88rem;">' + p.name + '</div><div style="font-size:.72rem;color:var(--text3);">' + (p.category_name || '') + (p.brand ? ' · ' + p.brand : '') + '</div></td>' +
                        '<td><code style="font-size:.75rem;background:var(--surface2);padding:2px 6px;border-radius:5px;">' + (p.barcode || '—') + '</code></td>' +
                        unitCell(storeUnits.cases) + unitCell(storeUnits.bundles) + unitCell(storeUnits.pcs) +
                        '<td style="font-weight:700;font-size:.95rem;color:' + storeColor + ';">' + storeQty + '</td>' +
                        '<td><button type="button" class="btn btn-secondary btn-sm" onclick="openTransferModalFor(' + p.id + ')" title="Restock store from warehouse">Restock</button></td>' +
                        '<td><button type="button" class="btn btn-secondary btn-sm" onclick="openPulloutModal(' + p.id + ')" title="Pull-out from store, warehouse, or supplier">Pull-out</button></td>' +
                        unitCell(whUnits.cases) + unitCell(whUnits.bundles) + unitCell(whUnits.pcs) +
                        '<td style="font-weight:700;font-size:.95rem;color:' + whColor + ';">' + whQty + '</td>' +
                        '<td class="move-in">+' + (p.warehouse_in || 0) + '</td>' +
                        '<td>' + restockDateHTML + '</td>' +
                        '<td class="move-out">-' + (p.warehouse_out || 0) + '</td>' +
                        '<td>' + pulloutDateHTML + '</td>' +
                        '<td>' + adjHTML + '</td>' +
                        '<td>' + deliveryHTML + '</td>' +
                        '<td>' + expiryHTML + '</td>' +
                        '<td>' + statusHTML + '</td>' +
                        '<td style="display:flex;gap:5px;">' +
                        '<button type="button" class="btn btn-secondary btn-sm" onclick="openWhProductDetails(' + p.id + ')" title="View Complete Details">👁️</button>' +
                        '<button type="button" class="btn btn-secondary btn-sm" onclick="openEditModal(' + p.id + ')" title="Edit Product">✏️</button>' +
                        '<button type="button" class="btn btn-secondary btn-sm" onclick="openQuickRestockModal(' + p.id + ')" title="Quick Restock">➕</button>' +
                        '<button type="button" class="btn btn-secondary btn-sm" onclick="openMoveModal(' + p.id + ',\'in\',\'warehouse\')" title="Warehouse In">🏭</button>' +
                        '</td>' +
                        '</tr>';
                }).join('');
            }

            // ── EXCEL EXPORT (SheetJS) ── shared helper: turns an array of row objects
            // into a downloadable .xlsx, used by both the Warehouse export and the
            // Product History export below.
            function downloadRowsAsExcel(rows, headers, filename, sheetName) {
                if (typeof XLSX === 'undefined') {
                    toast('Excel library failed to load — check your connection', 'error');
                    return;
                }
                if (!rows.length) {
                    toast('Nothing to export for the current filter', 'warning');
                    return;
                }
                const aoa = [headers, ...rows];
                const ws = XLSX.utils.aoa_to_sheet(aoa);
                const wb = XLSX.utils.book_new();
                XLSX.utils.book_append_sheet(wb, ws, sheetName || 'Sheet1');
                XLSX.writeFile(wb, filename);
            }

            function whStatusText(p) {
                const storeQty = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                const threshold = p.low_stock_threshold ?? 5;
                const expSt = getExpiryStatus(p.expiry_date);
                if (storeQty == 0) return 'Out of Stock';
                if (storeQty <= threshold) return 'Low Store';
                if (expSt && expSt.cls === 'expired') return 'Expired';
                if (expSt && (expSt.cls === 'critical' || expSt.cls === 'soon' || expSt.cls === 'upcoming')) return 'Expiring';
                return 'Good';
            }

            function exportWhToExcel() {
                const headers = ['Product Name', 'Barcode', 'Brand', 'Supplier', 'Store Stock (pcs)', 'Store Stock (breakdown)',
                    'Warehouse Stock (pcs)', 'Warehouse Stock (breakdown)', 'WH-IN', 'Restocking Date', 'WH-OUT', 'Pull-out Date', 'Cost Price', 'Stock Value (at cost)',
                    'Damaged', 'Expired', 'Returned (write-off)', 'Returned (restocked)', 'Delivery Date', 'Expiry Date', 'Status'
                ];
                const rows = whFilteredList.map(p => {
                    const sq = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                    const wq = p.warehouse_quantity ?? 0;
                    const cost = parseFloat(p.cost_price);
                    const value = isNaN(cost) ? '' : (cost * (sq + wq)).toFixed(2);
                    return [
                        p.name,
                        p.barcode || '',
                        p.brand || '',
                        p.supplier || '',
                        sq,
                        formatUnitBreakdown(sq, p),
                        wq,
                        formatUnitBreakdown(wq, p),
                        p.warehouse_in ?? 0,
                        p.last_restock_date ? p.last_restock_date.slice(0, 10) : '',
                        p.warehouse_out ?? 0,
                        p.last_pullout_date ? p.last_pullout_date.slice(0, 10) : '',
                        isNaN(cost) ? '' : cost.toFixed(2),
                        value,
                        p.qty_damaged || 0,
                        p.qty_expired || 0,
                        p.qty_returned_writeoff || 0,
                        p.qty_returned_restocked || 0,
                        p.delivery_date ? p.delivery_date.slice(0, 10) : '',
                        p.expiry_date ? p.expiry_date.slice(0, 10) : '',
                        whStatusText(p)
                    ];
                });
                const stamp = new Date().toISOString().slice(0, 10);
                downloadRowsAsExcel(rows, headers, 'Warehouse_Inventory_' + stamp + '.xlsx', 'Inventory');
            }

            function loadWhLog() {
                apiGet('get_warehouse_log', {
                    limit: 30
                }).then(r => {
                    if (!r?.success) return;
                    const body = document.getElementById('wh-log-body');
                    const empty = document.getElementById('wh-log-empty');
                    if (!r.data.length) {
                        body.innerHTML = '';
                        empty.style.display = 'block';
                        return;
                    }
                    empty.style.display = 'none';
                    body.innerHTML = r.data.map(row => {
                        const isIn = row.qty_in > 0;
                        const qty = isIn ? row.qty_in : row.qty_out;
                        const showBreakdown = (row.case_qty || row.pack_qty) && qty > 0;
                        const breakdownHTML = showBreakdown ?
                            '<div style="font-size:.68rem;color:var(--text3);font-weight:400;">' + formatUnitBreakdown(qty, row) + '</div>' : '';
                        const eventDateHTML = row.event_date ? row.event_date.slice(0, 10) : '—';
                        const batchHTML = row.batch_id ?
                            '<span style="font-size:.74rem;color:var(--text3);" title="' + escapeHtml(row.batch_supplier || 'Delivery') + (row.batch_delivery_date ? ' · ' + row.batch_delivery_date.slice(0, 10) : '') + '">#' + row.batch_id + '</span>' :
                            '<span style="color:var(--text3);">—</span>';
                        return '<tr>' +
                            '<td style="font-weight:600;">' + (row.product_name || '—') + '</td>' +
                            '<td>' + (isIn ? '<span class="move-in">📦 Stock In</span>' : '<span class="move-out">📤 Stock Out</span>') + '</td>' +
                            '<td style="font-weight:700;">' + (isIn ? '+' + row.qty_in : '-' + row.qty_out) + breakdownHTML + '</td>' +
                            '<td style="font-size:.78rem;color:var(--text3);">' + (isIn ? eventDateHTML : '—') + '</td>' +
                            '<td style="font-size:.78rem;color:var(--text3);">' + (!isIn ? eventDateHTML : '—') + '</td>' +
                            '<td style="font-size:.78rem;color:var(--text3);">' + (row.delivery_date ? row.delivery_date.slice(0, 10) : '—') + '</td>' +
                            '<td>' + batchHTML + '</td>' +
                            '<td style="color:var(--text3);font-size:.82rem;">' + (row.note || '—') + '</td>' +
                            '<td style="font-size:.78rem;">' + (row.added_by || '—') + '</td>' +
                            '<td style="font-size:.75rem;color:var(--text3);">' + fmtDate(row.created_at) + '</td>' +
                            '</tr>';
                    }).join('');
                });
            }

            // ── DYNAMIC ALERT BANNER: low stock + expiring/expired, checked DAILY ──
            // Fixed to the "daily" window (expiring today or already expired) — there's
            // no toggle for the admin to dismiss or widen it. It's recomputed fresh from
            // the DB every time this loads, so it keeps showing every single day until
            // the admin actually resolves it via Quick Restock or Pull-Out/Adjust.
            function loadAlertBanner() {
                const el = document.getElementById('expiry-alerts');
                if (!el) return;
                apiGet('get_alert_products', {
                    timeframe: 'daily'
                }).then(r => {
                    if (!r?.success) return;
                    const lowStock = r.data.low_stock || [];
                    const expiring = r.data.expiring || [];
                    if (!lowStock.length && !expiring.length) {
                        el.innerHTML = '';
                        return;
                    }
                    const summary = '⚠️ Daily Alert: ' + lowStock.length + ' item(s) hit low stock limits and ' + expiring.length + ' item(s) are expiring today.';

                    // Products appearing in BOTH lists only get one row (low-stock takes
                    // priority for which action buttons are the primary ones).
                    const expiringOnly = expiring.filter(p => !lowStock.find(l => l.id === p.id));

                    const rowsHtml = lowStock.map(p => alertRowHtml(p, 'low')).join('') +
                        expiringOnly.map(p => alertRowHtml(p, 'expiring')).join('');

                    el.innerHTML = '<div class="expiry-alert-banner" style="flex-direction:column;align-items:stretch;">' +
                        '<div class="alert-banner-summary"><span style="font-size:1.2rem;">🚨</span>' + summary + '</div>' +
                        rowsHtml +
                        '</div>';
                });
            }

            function alertRowHtml(p, kind) {
                const threshold = p.low_stock_threshold ?? 5;
                const qty = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                let info;
                if (kind === 'low') {
                    info = '<strong>' + p.name + '</strong> (Stock: ' + qty + ') - ' + (qty == 0 ? 'Out of Stock' : 'Hits Low Stock Limit (Threshold: ' + threshold + ')');
                } else {
                    const expSt = getExpiryStatus(p.expiry_date);
                    info = '<strong>' + p.name + '</strong> - ' + (expSt?.label || 'Expiring soon');
                }
                return '<div class="alert-banner-row">' +
                    '<div class="alert-banner-row-info">' + info + '</div>' +
                    '<div class="alert-banner-row-actions">' +
                    '<button type="button" class="btn btn-primary btn-sm" onclick="openQuickRestockModal(' + p.id + ')">➕ Quick Restock</button>' +
                    '<button type="button" class="btn btn-secondary btn-sm" onclick="openPulloutModal(' + p.id + ')">⚠️ Pull-Out / Adjust</button>' +
                    '</div>' +
                    '</div>';
            }

            function findWhProdById(id) {
                return whProds.find(x => x.id == id) || invProds.find(x => x.id == id);
            }

            // ── PRODUCT DETAILS MODAL (Warehouse) ──
            // Shows every field configurable in Add Product — pricing (incl. Promo),
            // packaging tiers, stock counts, expiry, brand/supplier/unit info — plus
            // that single product's own Recent Stock Movement feed (via
            // get_product_history filtered by product_id) so nothing about it has to be
            // hunted down across the Products page, Add Product form, and history modal.
            function openWhProductDetails(productId) {
                const p = findWhProdById(productId);
                if (!p) {
                    toast('Product not found', 'error');
                    return;
                }
                openModal('wh-details-modal');
                const body = document.getElementById('wh-details-body');
                if (!body) return;

                const storeQty = p.store_quantity !== undefined ? p.store_quantity : p.quantity;
                const whQty = p.warehouse_quantity ?? 0;
                const promoInfo = getPromoInfo(p);
                const priceHTML = promoInfo.active ?
                    '<span style="text-decoration:line-through;color:var(--text3);">' + CUR + promoInfo.price.toFixed(2) + '</span> <span style="color:#e74c3c;font-weight:700;">' + CUR + promoInfo.promo.toFixed(2) + '</span> <span class="badge" style="background:#e74c3c;color:#fff;">PROMO</span>' :
                    CUR + parseFloat(p.price || 0).toFixed(2);
                const expSt = getExpiryStatus(p.expiry_date);
                const expiryHTML = expSt ? '<span class="expiry-' + expSt.cls + '">' + expSt.label + '</span>' : '—';

                const row = (label, value) => value ?
                    '<div style="display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--border);font-size:.85rem;"><span style="color:var(--text3);">' + label + '</span><span style="font-weight:600;text-align:right;">' + value + '</span></div>' :
                    '';

                const img = p.has_image == 1 ?
                    '<img src="' + prodImgUrl(p.id, p.updated_at) + '" style="width:100%;max-width:160px;aspect-ratio:1;object-fit:cover;border-radius:var(--r-sm);display:block;margin:0 auto 12px;" data-fallback="blank" onerror="imgFallback(this)"/>' :
                    '';

                const costVal = parseFloat(p.cost_price);
                const hasCost = !isNaN(costVal);
                const stockValueHTML = hasCost ? CUR + (costVal * (storeQty + whQty)).toFixed(2) : '<span style="color:var(--text3);">not set</span>';

                // Cumulative shrinkage/return totals — computed server-side (see
                // get_products) from the Pull-Out & Returns log, so this reflects the
                // product's whole history, not just what's on the most recent page.
                const dmg = parseInt(p.qty_damaged) || 0;
                const exp2 = parseInt(p.qty_expired) || 0;
                const retWrite = parseInt(p.qty_returned_writeoff) || 0;
                const retStock = parseInt(p.qty_returned_restocked) || 0;
                const hasAnyAdjustment = dmg || exp2 || retWrite || retStock;

                body.innerHTML =
                    img +
                    '<div style="font-family:\'Poppins\',sans-serif;font-size:1.15rem;font-weight:600;text-align:center;margin-bottom:2px;">' + escapeHtml(p.name) + '</div>' +
                    (p.description ? '<div style="font-size:.8rem;color:var(--text3);text-align:center;margin-bottom:12px;">' + escapeHtml(p.description) + '</div>' : '<div style="margin-bottom:12px;"></div>') +
                    '<div style="font-family:\'Poppins\',sans-serif;font-style:italic;color:var(--text2);margin:10px 0 4px;">💰 Pricing</div>' +
                    row('Selling Price', priceHTML) +
                    row('Bundle Price', p.pack_qty ? CUR + parseFloat(p.pack_price || 0).toFixed(2) + ' (' + p.pack_qty + ' pcs)' : '') +
                    row('Case Price', p.case_qty ? CUR + parseFloat(p.case_price || 0).toFixed(2) + ' (' + p.case_qty + ' pcs)' : '') +
                    row('Cost Price', hasCost ? CUR + costVal.toFixed(2) + ' /pc' : '<span style="color:var(--text3);">not set — edit product to add it</span>') +
                    '<div style="font-family:\'Poppins\',sans-serif;font-style:italic;color:var(--text2);margin:14px 0 4px;">📊 Stock</div>' +
                    row('Store Stock', storeQty + ' pcs <span style="font-weight:400;color:var(--text3);">(' + formatUnitBreakdown(storeQty, p) + ')</span>') +
                    row('Warehouse Stock', whQty + ' pcs <span style="font-weight:400;color:var(--text3);">(' + formatUnitBreakdown(whQty, p) + ')</span>') +
                    row('Total Stock Value', stockValueHTML) +
                    row('Low Stock Threshold', p.low_stock_threshold ?? 5) +
                    row('Delivery Date', p.delivery_date ? p.delivery_date.slice(0, 10) : '') +
                    row('Last Restocking Date', p.last_restock_date ? p.last_restock_date.slice(0, 10) : '') +
                    row('Last Pull-out Date', p.last_pullout_date ? p.last_pullout_date.slice(0, 10) : '') +
                    row('Expiry Date', expiryHTML) +
                    row('Status', whStatusText(p)) +
                    '<div style="font-family:\'Poppins\',sans-serif;font-style:italic;color:var(--text2);margin:14px 0 4px;">🧾 Movement Summary (all-time)</div>' +
                    row('Total Restocked (in)', (parseInt(p.warehouse_in) || 0) + ' pcs') +
                    row('Total Removed (out)', (parseInt(p.warehouse_out) || 0) + ' pcs') +
                    (hasAnyAdjustment ? (
                        row('💔 Damaged on Delivery', dmg ? dmg + ' pcs' : '') +
                        row('⏰ Pulled Out Expired', exp2 ? exp2 + ' pcs' : '') +
                        row('↩️✕ Customer Returns (written off)', retWrite ? retWrite + ' pcs' : '') +
                        row('↩️✓ Customer Returns (restocked)', retStock ? retStock + ' pcs' : '')
                    ) : '<div style="font-size:.8rem;color:var(--text3);padding:4px 0 2px;">No damaged, expired, or returned stock recorded for this product.</div>') +
                    '<div style="font-family:\'Poppins\',sans-serif;font-style:italic;color:var(--text2);margin:14px 0 4px;">🏷️ Identification</div>' +
                    row('Barcode', p.barcode ? '<code>' + escapeHtml(p.barcode) + '</code>' : '') +
                    row('Bundle Barcode', p.pack_barcode ? '<code>' + escapeHtml(p.pack_barcode) + '</code>' : '') +
                    row('Case Barcode', p.case_barcode ? '<code>' + escapeHtml(p.case_barcode) + '</code>' : '') +
                    row('Category', p.category_name ? escapeHtml(p.category_name) : '') +
                    row('Brand', p.brand ? escapeHtml(p.brand) : '') +
                    row('Supplier', p.supplier ? escapeHtml(p.supplier) : '') +
                    row('Unit Type', p.unit_type ? escapeHtml(p.unit_type) + (p.unit_size ? ' (' + p.unit_size + ')' : '') : '') +
                    row('Auto-Convert Bundle/Case', p.auto_convert ? 'Enabled' : '') +
                    '<div style="font-family:\'Poppins\',sans-serif;font-style:italic;color:var(--text2);margin:14px 0 4px;">📦 Batches <span style="font-size:.72rem;font-style:normal;color:var(--text3);">(FEFO — soonest-expiring first)</span></div>' +
                    '<div id="wh-details-batches"><div style="text-align:center;color:var(--text3);font-size:.8rem;padding:6px;">Loading…</div></div>' +
                    '<div style="font-family:\'Poppins\',sans-serif;font-style:italic;color:var(--text2);margin:14px 0 4px;">📋 Delivery &amp; Movement History <span style="font-size:.72rem;font-style:normal;color:var(--text3);">(newest first)</span></div>' +
                    '<div id="wh-details-movement"><div style="text-align:center;color:var(--text3);font-size:.8rem;padding:10px;">Loading…</div></div>' +
                    '<div style="display:flex;gap:8px;margin-top:16px;">' +
                    '<button type="button" class="btn btn-primary btn-full" onclick="closeModal(\'wh-details-modal\');openEditModal(' + p.id + ')">✏️ Edit Product</button>' +
                    '<button type="button" class="btn btn-secondary" onclick="closeModal(\'wh-details-modal\')">Close</button>' +
                    '</div>';

                apiGet('get_batches', {
                    product_id: productId
                }).then(r => {
                    const el = document.getElementById('wh-details-batches');
                    if (!el) return;
                    if (!r?.success || !r.data.length) {
                        el.innerHTML = '<div style="text-align:center;color:var(--text3);font-size:.8rem;padding:6px;">No batches recorded yet</div>';
                        return;
                    }
                    el.innerHTML = r.data.map(b => {
                        const remaining = (parseInt(b.qty_warehouse) || 0) + (parseInt(b.qty_store) || 0);
                        const exhausted = remaining <= 0;
                        const expSt = getExpiryStatus(b.expiry_date);
                        const expiryHTML = b.expiry_date ? (expSt ? '<span class="expiry-' + expSt.cls + '">' + expSt.label + '</span>' : b.expiry_date.slice(0, 10)) : '<span style="color:var(--text3);">No expiry set</span>';
                        return '<div style="background:var(--surface2);border:1.5px solid ' + (exhausted ? 'var(--border)' : 'var(--green)') + ';border-radius:var(--r-sm);padding:9px 12px;font-size:.83rem;margin-bottom:8px;' + (exhausted ? 'opacity:.6;' : '') + '">' +
                            '<div style="display:flex;justify-content:space-between;gap:10px;">' +
                            '<span style="font-weight:700;">Batch #' + b.id + (exhausted ? ' — used up' : '') + '</span>' +
                            '<span style="color:var(--text3);font-size:.76rem;">' + (b.delivery_event_date ? b.delivery_event_date.slice(0, 10) : '—') + '</span>' +
                            '</div>' +
                            '<div style="margin-top:4px;">Received ' + b.qty_received + ' pcs · Remaining ' + remaining + ' pcs <span style="color:var(--text3);font-size:.76rem;">(WH ' + (b.qty_warehouse || 0) + ' / Store ' + (b.qty_store || 0) + ')</span></div>' +
                            '<div style="margin-top:3px;color:var(--text2);">' + (b.cost_price ? 'Cost ' + CUR + parseFloat(b.cost_price).toFixed(2) + '/pc · ' : '') + expiryHTML + '</div>' +
                            (b.supplier_ref ? '<div style="margin-top:2px;color:var(--text3);font-size:.76rem;">' + escapeHtml(b.supplier_ref) + '</div>' : '') +
                            '</div>';
                    }).join('');
                });

                apiGet('get_product_history', {
                    product_id: productId,
                    limit: 50
                }).then(r => {
                    const el = document.getElementById('wh-details-movement');
                    if (!el) return;
                    if (!r?.success || !r.data.length) {
                        el.innerHTML = '<div style="text-align:center;color:var(--text3);font-size:.8rem;padding:10px;">No stock movement recorded yet</div>';
                        return;
                    }
                    el.innerHTML = '<div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Qty</th><th>Restock/Pull-out Date</th><th>Batch</th><th>Note (explanation)</th><th>By</th></tr></thead><tbody>' +
                        r.data.map(row => {
                            const isIn = row.qty_in > 0;
                            const qty = isIn ? row.qty_in : row.qty_out;
                            const breakdownHTML = (p.case_qty || p.pack_qty) && qty > 0 ?
                                '<div style="font-size:.68rem;color:var(--text3);font-weight:400;">' + formatUnitBreakdown(qty, p) + '</div>' : '';
                            const evtDate = (row.restocking_date || row.pullout_date);
                            const batchHTML = row.batch_id ? '<span style="font-size:.74rem;color:var(--text3);">#' + row.batch_id + '</span>' : '<span style="color:var(--text3);">—</span>';
                            return '<tr>' +
                                '<td style="font-size:.75rem;color:var(--text3);">' + fmtDate(row.created_at) + '</td>' +
                                '<td>' + (isIn ? '<span class="move-in">📦 ' + escapeHtml(row.type) + '</span>' : '<span class="move-out">📤 ' + escapeHtml(row.type) + '</span>') + '</td>' +
                                '<td style="font-weight:700;">' + (isIn ? '+' + row.qty_in : '-' + row.qty_out) + breakdownHTML + '</td>' +
                                '<td style="font-size:.75rem;color:var(--text3);">' + (evtDate ? evtDate.slice(0, 10) : '—') + '</td>' +
                                '<td>' + batchHTML + '</td>' +
                                '<td style="color:var(--text3);font-size:.8rem;">' + escapeHtml(row.note || '—') + '</td>' +
                                '<td style="font-size:.78rem;">' + escapeHtml(row.added_by || '—') + '</td>' +
                                '</tr>';
                        }).join('') + '</tbody></table></div>';
                });
            }

            function openQuickRestockModal(productId) {
                const p = findWhProdById(productId);
                const idEl = document.getElementById('qr-product-id');
                idEl.value = productId;
                // Stash this product's Case/Bundle sizes on the hidden id field so
                // _qrUpdateTotal() can convert Cases/Bundle/Pcs into a raw pcs quantity.
                idEl.dataset.caseQty = p ? (parseInt(p.case_qty) || 0) : 0;
                idEl.dataset.packQty = p ? (parseInt(p.pack_qty) || 0) : 0;
                document.getElementById('qr-product-name').textContent = p ? p.name : ('Product #' + productId);
                document.getElementById('qr-destination').value = 'store';
                document.getElementById('qr-cases').value = '';
                document.getElementById('qr-bundle').value = '';
                document.getElementById('qr-pcs').value = '';
                document.getElementById('qr-cost-price').value = p && p.cost_price ? p.cost_price : '';
                document.getElementById('qr-supplier').value = '';
                document.getElementById('qr-restock-date').value = new Date().toISOString().slice(0, 10);
                document.getElementById('qr-expiry').value = p && p.expiry_date ? p.expiry_date.slice(0, 10) : '';
                _qrUpdateTotal();
                openModal('quick-restock-modal');
            }

            // Recomputes the read-only Quick Restock Total field from the Cases/Bundle/
            // Pcs inputs, using the product's case_qty/pack_qty stashed on qr-product-id
            // by openQuickRestockModal — same math as _ndUnitsToQty in New Delivery.
            function _qrUpdateTotal() {
                const idEl = document.getElementById('qr-product-id');
                const caseQty = parseInt(idEl.dataset.caseQty) || 0;
                const packQty = parseInt(idEl.dataset.packQty) || 0;
                const cases = parseInt(document.getElementById('qr-cases').value) || 0;
                const bundle = parseInt(document.getElementById('qr-bundle').value) || 0;
                const pcs = parseInt(document.getElementById('qr-pcs').value) || 0;
                document.getElementById('qr-total').value = (cases * caseQty) + (bundle * packQty) + pcs;
                const hintEl = document.getElementById('qr-unit-hint');
                if (hintEl) {
                    const parts = [];
                    if (caseQty > 0) parts.push('1 case = ' + caseQty + ' pcs');
                    if (packQty > 0) parts.push('1 bundle = ' + packQty + ' pcs');
                    hintEl.textContent = parts.length ? parts.join(' · ') : 'No Case/Bundle sizes set for this product — enter Pcs only.';
                }
            }

            function submitQuickRestock() {
                const pid = parseInt(document.getElementById('qr-product-id').value);
                const idEl = document.getElementById('qr-product-id');
                const caseQty = parseInt(idEl.dataset.caseQty) || 0;
                const packQty = parseInt(idEl.dataset.packQty) || 0;
                const cases = parseInt(document.getElementById('qr-cases').value) || 0;
                const bundle = parseInt(document.getElementById('qr-bundle').value) || 0;
                const pcs = parseInt(document.getElementById('qr-pcs').value) || 0;
                const qty = (cases * caseQty) + (bundle * packQty) + pcs;
                const destination = document.getElementById('qr-destination').value || 'store';
                const costPrice = document.getElementById('qr-cost-price').value || '';
                const supplierRef = document.getElementById('qr-supplier').value.trim();
                const restockDate = document.getElementById('qr-restock-date').value || null;
                const expiryDate = document.getElementById('qr-expiry').value || null;
                if (!pid || !qty || qty < 1) {
                    toast('Enter a valid quantity', 'error');
                    return;
                }
                const btn = document.getElementById('qr-save-btn');
                setLoading(btn, true);
                apiPost('quick_restock', {
                    product_id: pid,
                    qty,
                    destination,
                    cost_price: costPrice,
                    supplier_ref: supplierRef,
                    restock_date: restockDate,
                    expiry_date: expiryDate
                }).then(r => {
                    setLoading(btn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Error saving stock', 'error');
                        return;
                    }
                    toast('Stock added!', 'success');
                    closeModal('quick-restock-modal');
                    loadWhProducts();
                    loadWhLog();
                    loadAlertBanner();
                });
            }

            function onPulloutLocationChange() {
                const loc = document.getElementById('po-location').value || 'store';
                const custWrap = document.getElementById('po-reason-customer-return-wrap');
                const rtsWrap = document.getElementById('po-reason-return-to-supplier-wrap');
                if (custWrap) custWrap.style.display = loc === 'warehouse' ? 'none' : 'flex';
                if (rtsWrap) rtsWrap.style.display = loc === 'warehouse' ? 'flex' : 'none';
                // If the reason currently selected doesn't apply to the newly-picked
                // location (e.g. switching to Warehouse while Customer Return was
                // checked), fall back to Damaged on Delivery rather than leaving an
                // invalid/hidden radio checked.
                const checked = document.querySelector('input[name="po-reason"]:checked')?.value;
                const invalid = (loc === 'warehouse' && checked === 'CUSTOMER_RETURN') || (loc === 'store' && checked === 'RETURN_TO_SUPPLIER');
                if (invalid) {
                    const dmgRadio = document.querySelector('input[name="po-reason"][value="DAMAGE_ON_DELIVERY"]');
                    if (dmgRadio) dmgRadio.checked = true;
                }
                onPulloutReasonChange();
                _poUpdateTotal();
            }

            function onPulloutReasonChange() {
                const reason = document.querySelector('input[name="po-reason"]:checked')?.value;
                const returnWrap = document.getElementById('po-return-action-wrap');
                const rtsHintWrap = document.getElementById('po-rts-hint-wrap');
                if (returnWrap) returnWrap.style.display = reason === 'CUSTOMER_RETURN' ? 'block' : 'none';
                if (rtsHintWrap) rtsHintWrap.style.display = reason === 'RETURN_TO_SUPPLIER' ? 'block' : 'none';
            }

            function openPulloutModal(productId) {
                const p = findWhProdById(productId);
                const idEl = document.getElementById('po-product-id');
                idEl.value = productId;
                // Stash this product's Case/Bundle sizes on the hidden id field so
                // _poUpdateTotal() can convert Cases/Bundle/Pcs into a raw pcs quantity.
                idEl.dataset.caseQty = p ? (parseInt(p.case_qty) || 0) : 0;
                idEl.dataset.packQty = p ? (parseInt(p.pack_qty) || 0) : 0;
                document.getElementById('po-product-name').textContent = p ? p.name : ('Product #' + productId);
                document.getElementById('po-location').value = 'store';
                document.getElementById('po-cases').value = '';
                document.getElementById('po-bundle').value = '';
                document.getElementById('po-pcs').value = '';
                document.getElementById('po-date').value = new Date().toISOString().slice(0, 10);
                document.getElementById('po-note').value = '';
                const dmgRadio = document.querySelector('input[name="po-reason"][value="DAMAGE_ON_DELIVERY"]');
                if (dmgRadio) dmgRadio.checked = true;
                onPulloutLocationChange();
                openModal('pullout-modal');
            }

            // Recomputes the read-only Pull-out Total field from the Cases/Bundle/Pcs
            // inputs, using the product's case_qty/pack_qty stashed on po-product-id by
            // openPulloutModal — same math as _ndUnitsToQty in New Delivery.
            function _poUpdateTotal() {
                const idEl = document.getElementById('po-product-id');
                const caseQty = parseInt(idEl.dataset.caseQty) || 0;
                const packQty = parseInt(idEl.dataset.packQty) || 0;
                const cases = parseInt(document.getElementById('po-cases').value) || 0;
                const bundle = parseInt(document.getElementById('po-bundle').value) || 0;
                const pcs = parseInt(document.getElementById('po-pcs').value) || 0;
                document.getElementById('po-total').value = (cases * caseQty) + (bundle * packQty) + pcs;
                const hintEl = document.getElementById('po-unit-hint');
                if (hintEl) {
                    const parts = [];
                    if (caseQty > 0) parts.push('1 case = ' + caseQty + ' pcs');
                    if (packQty > 0) parts.push('1 bundle = ' + packQty + ' pcs');
                    hintEl.textContent = parts.length ? parts.join(' · ') : 'No Case/Bundle sizes set for this product — enter Pcs only.';
                }
            }

            function submitPullout() {
                const pid = parseInt(document.getElementById('po-product-id').value);
                const idEl = document.getElementById('po-product-id');
                const caseQty = parseInt(idEl.dataset.caseQty) || 0;
                const packQty = parseInt(idEl.dataset.packQty) || 0;
                const cases = parseInt(document.getElementById('po-cases').value) || 0;
                const bundle = parseInt(document.getElementById('po-bundle').value) || 0;
                const pcs = parseInt(document.getElementById('po-pcs').value) || 0;
                const qty = (cases * caseQty) + (bundle * packQty) + pcs;
                const location = document.getElementById('po-location').value || 'store';
                const reasonCode = document.querySelector('input[name="po-reason"]:checked')?.value || 'DAMAGE_ON_DELIVERY';
                const returnAction = document.getElementById('po-return-action')?.value || 'restock';
                const pulloutDate = document.getElementById('po-date').value || null;
                const note = document.getElementById('po-note').value.trim();
                if (!pid || !qty || qty < 1) {
                    toast('Enter a valid quantity', 'error');
                    return;
                }
                const btn = document.getElementById('po-save-btn');
                setLoading(btn, true);
                apiPost('adjust_stock_pullout', {
                    product_id: pid,
                    qty,
                    location,
                    reason_code: reasonCode,
                    return_action: returnAction,
                    pullout_date: pulloutDate,
                    note
                }).then(r => {
                    setLoading(btn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Error submitting report', 'error');
                        return;
                    }
                    toast('Inventory adjustment logged!', 'success');
                    closeModal('pullout-modal');
                    loadWhProducts();
                    loadWhLog();
                    loadAlertBanner();
                });
            }

            // ── PRODUCT HISTORY MODAL ──
            let historyRows = [],
                historyFilteredList = [];

            function openHistoryModal() {
                document.getElementById('hist-q').value = '';
                document.getElementById('hist-date-from').value = '';
                document.getElementById('hist-date-to').value = '';
                apiGet('get_brands_suppliers').then(r => {
                    if (!r?.success) return;
                    const brandSel = document.getElementById('hist-brand');
                    const supSel = document.getElementById('hist-supplier');
                    if (brandSel) brandSel.innerHTML = '<option value="">All Brands</option>' + r.data.brands.map(b => '<option value="' + escapeHtml(b) + '">' + escapeHtml(b) + '</option>').join('');
                    if (supSel) supSel.innerHTML = '<option value="">All Suppliers</option>' + r.data.suppliers.map(s => '<option value="' + escapeHtml(s) + '">' + escapeHtml(s) + '</option>').join('');
                });
                loadHistory();
                openModal('history-modal');
            }

            function loadHistory() {
                const dateFrom = document.getElementById('hist-date-from')?.value || '';
                const dateTo = document.getElementById('hist-date-to')?.value || '';
                apiGet('get_product_history', {
                    date_from: dateFrom,
                    date_to: dateTo,
                    limit: 500
                }).then(r => {
                    if (!r?.success) return;
                    historyRows = r.data;
                    renderHistory();
                });
            }

            function renderHistory() {
                const q = (document.getElementById('hist-q')?.value || '').toLowerCase();
                const brand = document.getElementById('hist-brand')?.value || '';
                const supplier = document.getElementById('hist-supplier')?.value || '';
                const filtered = historyRows.filter(row => {
                    if (q && !(row.product_name || '').toLowerCase().includes(q) && !(row.barcode || '').toLowerCase().includes(q)) return false;
                    if (brand && row.brand !== brand) return false;
                    if (supplier && row.supplier !== supplier) return false;
                    return true;
                });
                historyFilteredList = filtered;
                const body = document.getElementById('history-body');
                const empty = document.getElementById('history-empty');
                if (!body) return;
                if (!filtered.length) {
                    body.innerHTML = '';
                    if (empty) empty.style.display = 'block';
                    return;
                }
                if (empty) empty.style.display = 'none';
                body.innerHTML = filtered.map(row => {
                    const isIn = (row.qty_in || 0) > 0;
                    const qty = isIn ? row.qty_in : row.qty_out;
                    const showBreakdown = (row.case_qty || row.pack_qty) && qty > 0;
                    const breakdownHTML = showBreakdown ?
                        '<div style="font-size:.68rem;color:var(--text3);font-weight:400;">' + formatUnitBreakdown(qty, row) + '</div>' : '';
                    const batchHTML = row.batch_id ?
                        '<span style="font-size:.74rem;color:var(--text3);" title="' + escapeHtml(row.batch_supplier || 'Delivery') + (row.batch_delivery_date ? ' · ' + row.batch_delivery_date.slice(0, 10) : '') + '">#' + row.batch_id + '</span>' :
                        '<span style="color:var(--text3);">—</span>';
                    return '<tr>' +
                        '<td style="font-size:.75rem;color:var(--text3);">' + fmtDate(row.created_at) + '</td>' +
                        '<td style="font-weight:600;">' + (row.product_name || '—') + '</td>' +
                        '<td style="font-size:.8rem;">' + (row.brand || '—') + '</td>' +
                        '<td style="font-size:.8rem;">' + (row.supplier || '—') + '</td>' +
                        '<td style="font-size:.78rem;color:var(--text3);">' + (row.restocking_date ? row.restocking_date.slice(0, 10) : '—') + '</td>' +
                        '<td style="font-size:.78rem;color:var(--text3);">' + (row.pullout_date ? row.pullout_date.slice(0, 10) : '—') + '</td>' +
                        '<td style="font-size:.78rem;color:var(--text3);">' + (row.delivery_date ? row.delivery_date.slice(0, 10) : '—') + '</td>' +
                        '<td>' + (row.type || '—') + '</td>' +
                        '<td class="move-in">' + (isIn ? '+' + row.qty_in + breakdownHTML : '') + '</td>' +
                        '<td class="move-out">' + (!isIn && row.qty_out ? '-' + row.qty_out + breakdownHTML : '') + '</td>' +
                        '<td>' + batchHTML + '</td>' +
                        '<td style="color:var(--text3);font-size:.82rem;">' + (row.note || '—') + '</td>' +
                        '<td style="font-size:.78rem;">' + (row.added_by || '—') + '</td>' +
                        '</tr>';
                }).join('');
            }

            function exportHistoryToExcel() {
                const headers = ['Date', 'Product', 'Brand', 'Supplier', 'Restocking Date', 'Pull-out Date', 'Delivery Date', 'Type', 'Qty In', 'Qty Out', 'Batch', 'Note', 'Added By'];
                const rows = historyFilteredList.map(row => [
                    fmtDate(row.created_at), row.product_name || '', row.brand || '', row.supplier || '',
                    row.restocking_date ? row.restocking_date.slice(0, 10) : '',
                    row.pullout_date ? row.pullout_date.slice(0, 10) : '',
                    row.delivery_date ? row.delivery_date.slice(0, 10) : '',
                    row.type || '', row.qty_in || 0, row.qty_out || 0, row.batch_id ? ('#' + row.batch_id) : '', row.note || '', row.added_by || ''
                ]);
                const stamp = new Date().toISOString().slice(0, 10);
                downloadRowsAsExcel(rows, headers, 'Product_History_' + stamp + '.xlsx', 'History');
            }

            function printHistoryReport() {
                if (!historyFilteredList.length) {
                    toast('Nothing to print for the current filter', 'warning');
                    return;
                }
                const rowsHtml = historyFilteredList.map(row =>
                    '<tr><td>' + fmtDate(row.created_at) + '</td><td>' + (row.product_name || '') + '</td><td>' + (row.brand || '') + '</td><td>' + (row.supplier || '') + '</td><td>' + (row.restocking_date ? row.restocking_date.slice(0, 10) : '') + '</td><td>' + (row.pullout_date ? row.pullout_date.slice(0, 10) : '') + '</td><td>' + (row.delivery_date ? row.delivery_date.slice(0, 10) : '') + '</td><td>' + (row.type || '') + '</td><td>' + (row.qty_in || 0) + '</td><td>' + (row.qty_out || 0) + '</td><td>' + (row.batch_id ? ('#' + row.batch_id) : '') + '</td><td>' + (row.note || '') + '</td><td>' + (row.added_by || '') + '</td></tr>'
                ).join('');
                const win = window.open('', '_blank');
                if (!win) {
                    toast('Pop-up blocked — allow pop-ups for printing', 'warning');
                    return;
                }
                win.document.write(
                    '<html><head><title>Product History Report</title><style>' +
                    'body{font-family:Arial,sans-serif;padding:24px;color:#1A1208;}' +
                    'h1{font-size:18px;margin-bottom:4px;}' +
                    'p{font-size:12px;color:#666;margin-bottom:16px;}' +
                    'table{width:100%;border-collapse:collapse;font-size:11px;}' +
                    'th,td{border:1px solid #ccc;padding:5px 7px;text-align:left;}' +
                    'th{background:#f0f0f0;}' +
                    '</style></head><body>' +
                    '<h1>Product History Report</h1>' +
                    '<p>Generated ' + new Date().toLocaleString() + ' — ' + historyFilteredList.length + ' record(s)</p>' +
                    '<table><thead><tr><th>Date</th><th>Product</th><th>Brand</th><th>Supplier</th><th>Restocking Date</th><th>Pull-out Date</th><th>Delivery Date</th><th>Type</th><th>Qty In</th><th>Qty Out</th><th>Batch</th><th>Note</th><th>Added By</th></tr></thead>' +
                    '<tbody>' + rowsHtml + '</tbody></table>' +
                    '</body></html>'
                );
                win.document.close();
                win.focus();
                setTimeout(() => win.print(), 300);
            }

            function openMoveModal(productId, type, target) {
                const sel = document.getElementById('move-product');
                if (sel) {
                    sel.innerHTML = whProds.map(p => {
                        const sq = p.store_quantity ?? p.quantity ?? 0;
                        const wq = p.warehouse_quantity ?? 0;
                        return '<option value="' + p.id + '"' + (p.id == productId ? ' selected' : '') + '>' + p.name + ' (Store: ' + sq + ' | WH: ' + wq + ')</option>';
                    }).join('');
                }
                const typeSel = document.getElementById('move-type');
                if (typeSel && type) typeSel.value = type;
                const targetSel = document.getElementById('move-target');
                if (targetSel && target) targetSel.value = target;
                document.getElementById('move-qty').value = '';
                document.getElementById('move-note').value = '';
                document.getElementById('move-cost-price').value = '';
                document.getElementById('move-expiry-date').value = '';
                toggleMoveBatchFields();
                openModal('move-modal');
            }

            // Cost Price/Expiry only make sense for a stock-IN (it's opening a new
            // batch) — hidden for Stock Out, where FEFO just depletes existing batches.
            function toggleMoveBatchFields() {
                const isIn = (document.getElementById('move-type')?.value || 'in') === 'in';
                const box = document.getElementById('move-batch-fields');
                if (box) box.style.display = isIn ? 'grid' : 'none';
            }

            function saveMovement() {
                const pid = parseInt(document.getElementById('move-product')?.value);
                const type = document.getElementById('move-type')?.value || 'in';
                const target = document.getElementById('move-target')?.value || 'warehouse';
                const qty = parseInt(document.getElementById('move-qty')?.value);
                const note = document.getElementById('move-note')?.value.trim() || '';
                const costPrice = document.getElementById('move-cost-price')?.value || '';
                const expiryDate = document.getElementById('move-expiry-date')?.value || '';
                if (!pid || !qty || qty < 1) {
                    toast('Select product and enter quantity', 'error');
                    return;
                }
                const btn = document.getElementById('save-move-btn');
                setLoading(btn, true);
                apiPost('add_warehouse_movement', {
                    product_id: pid,
                    type,
                    target,
                    qty,
                    note,
                    cost_price: costPrice,
                    expiry_date: expiryDate
                }).then(r => {
                    setLoading(btn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Error saving movement', 'error');
                        return;
                    }
                    toast('Stock movement saved!', 'success');
                    closeModal('move-modal');
                    loadWhProducts();
                    loadWhLog();
                    loadAlertBanner();
                });
            }

            // ── NEW DELIVERY MODAL: multi-product, one supplier drop-off ──
            let ndItemSeq = 0;
            // Persistently remembers which line item's product search box was last
            // focused/typed in, updated on every focus/input rather than only checked
            // live via document.activeElement at the moment a scan's Enter key fires —
            // a physical scanner burst can otherwise land right as a suggestion-list
            // mousedown or on-screen keyboard event momentarily shifts focus, which
            // used to make a perfectly-tapped field get rejected with
            // "Tap a product field first, then scan".
            let _ndFocusedRowId = null;

            function openNewDeliveryModal() {
                document.getElementById('nd-supplier').value = '';
                document.getElementById('nd-date').value = new Date().toISOString().slice(0, 10);
                document.getElementById('nd-note').value = '';
                document.getElementById('nd-items').innerHTML = '';
                ndItemSeq = 0;
                _ndFocusedRowId = null;
                addDeliveryLineItem();
                // First row is the sensible default target for a scan before the person
                // has tapped anything yet.
                _ndFocusedRowId = 'nd-item-' + ndItemSeq;
                // Suggestions drawn from suppliers already assigned to products — same
                // dedup approach used for the supplier filter elsewhere in the app —
                // so typing doesn't require remembering/retyping exact past spelling.
                const supplierList = document.getElementById('nd-supplier-list');
                if (supplierList) {
                    const suppliers = [...new Set(whProds.map(p => p.supplier).filter(Boolean))].sort();
                    supplierList.innerHTML = suppliers.map(s => '<option value="' + s.replace(/"/g, '&quot;') + '"></option>').join('');
                }
                openModal('new-delivery-modal');
            }

            // Renders the suggestion list for one line item's product search box,
            // filtering by name OR barcode substring match — the actual fix for
            // "scroll to find it" since a long product <select> has been replaced
            // entirely by this.
            function _ndFilterProducts(inputEl) {
                const row = inputEl.closest('.nd-item');
                _ndFocusedRowId = row?.id || null;
                const listEl = row?.querySelector('.nd-suggest');
                if (!listEl) return;
                const q = inputEl.value.trim().toLowerCase();
                // Empty query still shows a short list (rather than nothing) so tapping
                // into an empty box on a touchscreen gives you something to scroll,
                // matching how the old dropdown behaved before you'd typed anything.
                const matches = whProds.filter(p =>
                    !q || p.name.toLowerCase().includes(q) || (p.barcode || '').toLowerCase().includes(q)
                ).slice(0, 8);
                if (!matches.length) {
                    listEl.innerHTML = '<div style="padding:8px 10px;font-size:.8rem;color:var(--text3);">No matching products</div>';
                } else {
                    listEl.innerHTML = matches.map(p => {
                        const sq = p.store_quantity ?? p.quantity ?? 0;
                        const wq = p.warehouse_quantity ?? 0;
                        return '<div class="nd-suggest-row" onmousedown="event.preventDefault();_ndSelectProduct(' + row.id.replace('nd-item-', '') + ',' + p.id + ')" ' +
                            'style="padding:8px 10px;font-size:.85rem;cursor:pointer;border-bottom:1px solid var(--border);">' +
                            '<div style="font-weight:600;">' + p.name + '</div>' +
                            '<div style="font-size:.72rem;color:var(--text3);">' + (p.barcode ? p.barcode + ' · ' : '') + 'Store: ' + sq + ' | WH: ' + wq + '</div>' +
                            '</div>';
                    }).join('');
                }
                listEl.style.display = 'block';
            }

            // onmousedown+preventDefault above fires the selection BEFORE this blur
            // handler's setTimeout closes the list — otherwise a plain click/blur race
            // would hide the suggestions right as the tap lands, and nothing gets picked.
            function _ndHideSuggestSoon(inputEl) {
                const row = inputEl.closest('.nd-item');
                const listEl = row?.querySelector('.nd-suggest');
                setTimeout(() => {
                    if (listEl) listEl.style.display = 'none';
                }, 150);
            }

            function _ndSelectProduct(itemId, productId) {
                const row = document.getElementById('nd-item-' + itemId);
                if (!row) return;
                const p = whProds.find(x => x.id == productId);
                if (!p) return;
                row.querySelector('.nd-product-search').value = p.name;
                row.querySelector('.nd-product-id').value = p.id;
                const listEl = row.querySelector('.nd-suggest');
                if (listEl) listEl.style.display = 'none';

                // Stash this product's Case/Bundle sizes on the row so the Cases/Bundle
                // inputs below can be converted to a raw pcs total (see _ndUnitsToQty).
                const caseQty = parseInt(p.case_qty) || 0;
                const packQty = parseInt(p.pack_qty) || 0;
                row.dataset.caseQty = caseQty;
                row.dataset.packQty = packQty;
                const hintEl = row.querySelector('.nd-unit-hint');
                if (hintEl) {
                    const parts = [];
                    if (caseQty > 0) parts.push('1 case = ' + caseQty + ' pcs');
                    if (packQty > 0) parts.push('1 bundle = ' + packQty + ' pcs');
                    hintEl.textContent = parts.length ? parts.join(' · ') : 'No Case/Bundle sizes set for this product — enter Pcs only.';
                }
                _ndUpdateTotals(itemId);
            }

            function addDeliveryLineItem() {
                const id = ++ndItemSeq;
                const wrap = document.getElementById('nd-items');
                if (!wrap) return;
                const div = document.createElement('div');
                div.className = 'nd-item';
                div.id = 'nd-item-' + id;
                div.style.cssText = 'border:1px solid var(--border);border-radius:10px;padding:10px;';
                div.innerHTML =
                    '<div style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px;">' +
                    '<div style="position:relative;flex:1;">' +
                    '<input type="text" class="form-input nd-product-search" placeholder="Type product name, or scan barcode…" autocomplete="off" ' +
                    'oninput="_ndFilterProducts(this)" onfocus="_ndFilterProducts(this)" onblur="_ndHideSuggestSoon(this)"/>' +
                    '<input type="hidden" class="nd-product-id"/>' +
                    '<div class="nd-suggest" style="display:none;position:absolute;z-index:50;left:0;right:0;top:100%;margin-top:2px;background:var(--surface);border:1px solid var(--border);border-radius:8px;box-shadow:var(--shadow-lg);max-height:220px;overflow-y:auto;"></div>' +
                    '<div class="nd-unit-hint" style="font-size:.68rem;color:var(--text3);margin-top:3px;"></div>' +
                    '</div>' +
                    '<button type="button" onclick="removeDeliveryLineItem(' + id + ')" style="background:none;border:none;color:#dc2626;font-size:1.15rem;line-height:1;cursor:pointer;padding:2px 4px;" title="Remove this product">✕</button>' +
                    '</div>' +
                    '<div style="font-size:.72rem;color:var(--text2);font-weight:700;margin:2px 0 4px;">🏪 → Store</div>' +
                    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:6px;">' +
                    '<div><label class="form-label" style="font-size:.66rem;">Cases</label><input type="number" class="form-input nd-st-cases" min="0" placeholder="0" oninput="_ndUpdateTotals(' + id + ')"/></div>' +
                    '<div><label class="form-label" style="font-size:.66rem;">Bundle</label><input type="number" class="form-input nd-st-bundle" min="0" placeholder="0" oninput="_ndUpdateTotals(' + id + ')"/></div>' +
                    '<div><label class="form-label" style="font-size:.66rem;">Pcs</label><input type="number" class="form-input nd-st-pcs" min="0" placeholder="0" oninput="_ndUpdateTotals(' + id + ')"/></div>' +
                    '<div><label class="form-label" style="font-size:.66rem;">Total</label><input type="text" class="form-input nd-st-total" readonly value="0" style="font-weight:700;background:var(--surface2);"/></div>' +
                    '</div>' +
                    '<div style="font-size:.72rem;color:var(--text2);font-weight:700;margin:10px 0 4px;">🏭 → Warehouse</div>' +
                    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:6px;">' +
                    '<div><label class="form-label" style="font-size:.66rem;">Cases</label><input type="number" class="form-input nd-wh-cases" min="0" placeholder="0" oninput="_ndUpdateTotals(' + id + ')"/></div>' +
                    '<div><label class="form-label" style="font-size:.66rem;">Bundle</label><input type="number" class="form-input nd-wh-bundle" min="0" placeholder="0" oninput="_ndUpdateTotals(' + id + ')"/></div>' +
                    '<div><label class="form-label" style="font-size:.66rem;">Pcs</label><input type="number" class="form-input nd-wh-pcs" min="0" placeholder="0" oninput="_ndUpdateTotals(' + id + ')"/></div>' +
                    '<div><label class="form-label" style="font-size:.66rem;">Total</label><input type="text" class="form-input nd-wh-total" readonly value="0" style="font-weight:700;background:var(--surface2);"/></div>' +
                    '</div>' +
                    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;">' +
                    '<div><label class="form-label" style="font-size:.72rem;">Cost Price</label><input type="number" class="form-input nd-cost" min="0" step="0.01" placeholder="0.00"/></div>' +
                    '<div><label class="form-label" style="font-size:.72rem;">Expiry Date</label><input type="date" class="form-input nd-expiry"/></div>' +
                    '</div>';
                wrap.appendChild(div);
            }

            // Recomputes the read-only Store/Warehouse Total fields for one delivery
            // line item from its Cases/Bundle/Pcs inputs, using the SELECTED product's
            // case_qty/pack_qty (stashed on the row by _ndSelectProduct) — same
            // cases×caseQty + bundles×packQty + pcs math as splitQtyIntoUnits' inverse.
            // Falls back to 0 case/bundle size (so only Pcs counts) if no product has
            // been picked yet or it has no Bundle/Case tiers configured.
            function _ndUnitsToQty(row, casesEl, bundleEl, pcsEl) {
                const caseQty = parseInt(row.dataset.caseQty) || 0;
                const packQty = parseInt(row.dataset.packQty) || 0;
                const cases = parseInt(casesEl.value) || 0;
                const bundles = parseInt(bundleEl.value) || 0;
                const pcs = parseInt(pcsEl.value) || 0;
                return (cases * caseQty) + (bundles * packQty) + pcs;
            }

            function _ndUpdateTotals(id) {
                const row = document.getElementById('nd-item-' + id);
                if (!row) return;
                const stTotal = _ndUnitsToQty(row, row.querySelector('.nd-st-cases'), row.querySelector('.nd-st-bundle'), row.querySelector('.nd-st-pcs'));
                const whTotal = _ndUnitsToQty(row, row.querySelector('.nd-wh-cases'), row.querySelector('.nd-wh-bundle'), row.querySelector('.nd-wh-pcs'));
                const stTotalEl = row.querySelector('.nd-st-total');
                if (stTotalEl) stTotalEl.value = stTotal;
                const whTotalEl = row.querySelector('.nd-wh-total');
                if (whTotalEl) whTotalEl.value = whTotal;
            }

            function removeDeliveryLineItem(id) {
                const el = document.getElementById('nd-item-' + id);
                if (el) el.remove();
                // Always keep at least one line item so the form never looks empty/broken.
                if (!document.getElementById('nd-items').children.length) addDeliveryLineItem();
            }

            function saveNewDelivery() {
                const supplierRef = document.getElementById('nd-supplier').value.trim();
                const eventDate = document.getElementById('nd-date').value || null;
                const note = document.getElementById('nd-note').value.trim();
                const items = [];
                document.querySelectorAll('#nd-items .nd-item').forEach(row => {
                    const pid = parseInt(row.querySelector('.nd-product-id')?.value);
                    const qSt = _ndUnitsToQty(row, row.querySelector('.nd-st-cases'), row.querySelector('.nd-st-bundle'), row.querySelector('.nd-st-pcs'));
                    const qWh = _ndUnitsToQty(row, row.querySelector('.nd-wh-cases'), row.querySelector('.nd-wh-bundle'), row.querySelector('.nd-wh-pcs'));
                    const cost = row.querySelector('.nd-cost')?.value || '';
                    const expiry = row.querySelector('.nd-expiry')?.value || '';
                    if (pid && (qWh + qSt) > 0) {
                        items.push({
                            product_id: pid,
                            qty_warehouse: qWh,
                            qty_store: qSt,
                            cost_price: cost,
                            expiry_date: expiry
                        });
                    }
                });
                if (!items.length) {
                    toast('Add at least one product with a quantity', 'error');
                    return;
                }
                const btn = document.getElementById('nd-save-btn');
                setLoading(btn, true);
                apiPost('add_delivery', {
                    supplier_ref: supplierRef,
                    event_date: eventDate,
                    note,
                    items
                }).then(r => {
                    setLoading(btn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Error saving delivery', 'error');
                        return;
                    }
                    toast('Delivery saved — ' + (r.data?.items_saved ?? items.length) + ' product(s) added!', 'success');
                    closeModal('new-delivery-modal');
                    loadWhProducts();
                    loadWhLog();
                    loadAlertBanner();
                });
            }

            // Show barcode modal for warehouse product — uses canvas for display (no SVG shown)
            function showProductBarcode(productId, barcode, name) {
                if (!barcode) {
                    toast('No barcode for this product', 'warning');
                    return;
                }
                const existing = document.getElementById('prod-bc-modal');
                if (existing) existing.remove();

                const overlay = document.createElement('div');
                overlay.id = 'prod-bc-modal';
                overlay.className = 'modal-overlay';
                document.body.appendChild(overlay);

                const modal = document.createElement('div');
                modal.className = 'modal';
                modal.style.cssText = 'max-width:340px;text-align:center;';
                overlay.appendChild(modal);

                const hdr = document.createElement('div');
                hdr.className = 'modal-header';
                const ttl = document.createElement('span');
                ttl.className = 'modal-title';
                ttl.textContent = '\uD83C\uDFF7\uFE0F ' + name;
                const hdrClose = document.createElement('button');
                hdrClose.className = 'modal-close';
                hdrClose.textContent = '\u2715';
                hdrClose.onclick = () => overlay.remove();
                hdr.appendChild(ttl);
                hdr.appendChild(hdrClose);
                modal.appendChild(hdr);

                // Loading placeholder
                const loadingEl = document.createElement('div');
                loadingEl.style.cssText = 'padding:24px;font-size:.83rem;color:var(--text3);';
                loadingEl.textContent = 'Rendering barcode…';
                modal.appendChild(loadingEl);

                const codeLabel = document.createElement('p');
                codeLabel.style.cssText = 'font-size:.75rem;color:var(--text3);margin-bottom:12px;';
                codeLabel.textContent = barcode;
                modal.appendChild(codeLabel);

                const btnRow = document.createElement('div');
                btnRow.style.cssText = 'display:flex;gap:8px;justify-content:center;';
                let whCanvas = null; // will be set after render

                const pBtn = document.createElement('button');
                pBtn.type = 'button';
                pBtn.className = 'btn btn-primary btn-sm';
                pBtn.textContent = '\uD83D\uDDB8 Print';
                pBtn.onclick = () => printWhBarcode(barcode, name);

                const dBtn = document.createElement('button');
                dBtn.type = 'button';
                dBtn.className = 'btn btn-secondary btn-sm';
                dBtn.textContent = '\u2B07\uFE0F Download';
                dBtn.onclick = () => {
                    if (!whCanvas) {
                        toast('Barcode still rendering', 'warning');
                        return;
                    }
                    const a = document.createElement('a');
                    a.download = 'barcode_' + barcode + '.png';
                    a.href = whCanvas.toDataURL('image/png');
                    a.click();
                    toast('Barcode downloaded!', 'success');
                };

                const cBtn = document.createElement('button');
                cBtn.type = 'button';
                cBtn.className = 'btn btn-secondary btn-sm';
                cBtn.textContent = 'Close';
                cBtn.onclick = () => overlay.remove();

                btnRow.appendChild(pBtn);
                btnRow.appendChild(dBtn);
                btnRow.appendChild(cBtn);
                modal.appendChild(btnRow);
                overlay.addEventListener('click', e => {
                    if (e.target === overlay) overlay.remove();
                });

                const renderBarcode = () => {
                    // Render into a hidden SVG, then rasterize to canvas for display
                    const tmpSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                    tmpSvg.style.cssText = 'position:absolute;left:-9999px;top:-9999px;';
                    document.body.appendChild(tmpSvg);
                    try {
                        JsBarcode(tmpSvg, barcode, BC_OPTS);
                    } catch (e) {
                        document.body.removeChild(tmpSvg);
                        loadingEl.textContent = 'Invalid barcode';
                        return;
                    }
                    svgToCanvasPng(tmpSvg, (png) => {
                        document.body.removeChild(tmpSvg);
                        if (!png) {
                            loadingEl.textContent = 'Render failed';
                            return;
                        }
                        const img = new Image();
                        img.onload = () => {
                            const canvas = document.createElement('canvas');
                            canvas.width = Math.round(img.naturalWidth / 2);
                            canvas.height = Math.round(img.naturalHeight / 2);
                            canvas.style.cssText = 'max-width:280px;height:auto;display:block;margin:0 auto 10px;border-radius:6px;image-rendering:crisp-edges;background:#fff;';
                            const ctx = canvas.getContext('2d');
                            ctx.imageSmoothingEnabled = false;
                            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                            whCanvas = canvas;
                            modal.replaceChild(canvas, loadingEl);
                        };
                        img.src = png;
                    });
                };

                setTimeout(() => {
                    overlay.classList.add('open');
                    if (typeof JsBarcode !== 'undefined') {
                        renderBarcode();
                    } else {
                        const s = document.createElement('script');
                        s.src = 'https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
                        s.onload = renderBarcode;
                        document.head.appendChild(s);
                    }
                }, 30);
            }

            function downloadWhBarcodeSvg(barcode, svgEl) {
                // Legacy — now handled inline in showProductBarcode via canvas
                toast('Use the Download button in the barcode modal', 'default');
            }
            // Keep old name as alias
            function showProductQR(id, bc, name) {
                showProductBarcode(id, bc, name);
            }


            function downloadWhQR(barcode, name) {
                const canvas = document.getElementById('wh-qr-canvas');
                if (!canvas) return;
                const a = document.createElement('a');
                a.download = 'qr_' + barcode + '.png';
                a.href = canvas.toDataURL('image/png');
                a.click();
                toast('QR Downloaded!', 'success');
            }

            function printWhBarcode(barcode, name) {
                if (!barcode) {
                    toast('No barcode to print', 'warning');
                    return;
                }
                // Render to offscreen SVG, rasterize, then print PNG — never raw SVG
                const tmpSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                tmpSvg.style.cssText = 'position:absolute;left:-9999px;top:-9999px;width:300px;height:80px;';
                document.body.appendChild(tmpSvg);
                const ready = () => {
                    try {
                        JsBarcode(tmpSvg, barcode, BC_OPTS);
                    } catch (e) {
                        document.body.removeChild(tmpSvg);
                        toast('Invalid barcode value', 'error');
                        return;
                    }
                    svgToCanvasPng(tmpSvg, (png) => {
                        document.body.removeChild(tmpSvg);
                        if (!png) {
                            toast('Could not render barcode', 'error');
                            return;
                        }
                        const win = window.open('', '_blank');
                        if (!win) {
                            toast('Pop-up blocked — allow pop-ups for printing', 'warning');
                            return;
                        }
                        win.document.write(
                            '<!DOCTYPE html><html><head>' +
                            '<style>*{margin:0;padding:0;box-sizing:border-box;}' +
                            'body{font-family:Arial,sans-serif;text-align:center;padding:20px;background:#fff;}' +
                            'h3{font-size:13px;margin-bottom:3px;}' +
                            'p{font-size:10px;color:#666;margin-bottom:8px;}' +
                            'img{display:block;margin:0 auto;max-width:300px;image-rendering:crisp-edges;}' +
                            '@media print{@page{margin:8mm;}body{padding:10px;}}' +
                            '</style></head><body>' +
                            '<h3>' + (name || '').replace(/</g, '&lt;') + '</h3>' +
                            '<p>' + barcode.replace(/</g, '&lt;') + '</p>' +
                            '<img src="' + png + '" alt="barcode"/>' +
                            '<script>window.onload=function(){window.print();window.close();}<\/script>' +
                            '</body></html>'
                        );
                        win.document.close();
                    });
                };
                // JsBarcode may not be loaded yet on warehouse page
                if (typeof JsBarcode !== 'undefined') {
                    ready();
                } else {
                    const s = document.createElement('script');
                    s.src = 'https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
                    s.onload = ready;
                    document.head.appendChild(s);
                }
            }

            function printWhQR(bc, name) {
                printWhBarcode(bc, name);
            }

            // ════════════════════════════════════════════
            // MARKET BASKET ANALYSIS
            // ════════════════════════════════════════════
            function loadBasketAnalysis() {
                const support = (parseFloat(document.getElementById('mba-support')?.value) || 5) / 100;
                const conf = (parseFloat(document.getElementById('mba-conf')?.value) || 30) / 100;
                const resultEl = document.getElementById('mba-result');
                const statsEl = document.getElementById('mba-stats');
                if (resultEl) resultEl.innerHTML = '<div style="text-align:center;padding:30px;color:var(--text3);">🔍 Analyzing transactions…</div>';
                apiGet('get_basket_analysis', {
                    min_support: support,
                    min_conf: conf,
                    limit: 25
                }).then(r => {
                    if (!r?.success) {
                        toast('Error running basket analysis', 'error');
                        return;
                    }
                    const {
                        rules,
                        total_transactions,
                        total_rules,
                        message
                    } = r.data;

                    // Update stat cards
                    if (statsEl) {
                        statsEl.style.display = 'grid';
                        document.getElementById('mba-tx-count').textContent = total_transactions;
                        document.getElementById('mba-rules-count').textContent = total_rules || 0;
                        const topLift = rules.length ? rules[0].lift.toFixed(2) : '—';
                        document.getElementById('mba-top-lift').textContent = topLift;
                    }

                    if (!resultEl) return;

                    if (message || !rules.length) {
                        resultEl.innerHTML = '<div class="empty-state"><div class="empty-icon">📊</div><div class="empty-text">' +
                            (message || 'No association rules found. Try lowering the minimum support or confidence thresholds.') +
                            '</div></div>';
                        return;
                    }

                    // Build rules table
                    const rows = rules.map(rule => {
                        const liftColor = rule.lift >= 2 ? 'rgba(45,122,58,.12)' : rule.lift >= 1 ? 'rgba(244,160,36,.1)' : 'rgba(212,80,10,.08)';
                        const liftBorder = rule.lift >= 2 ? '#2d7a3a' : rule.lift >= 1 ? '#f4a024' : '#d4500a';
                        const liftLabel = rule.lift >= 2 ? '🔥 Strong' : rule.lift >= 1 ? '✅ Positive' : '⚠️ Weak';
                        return '<tr style="background:' + liftColor + ';border-left:3px solid ' + liftBorder + ';">' +
                            '<td style="font-weight:700;">' + rule.antecedent + '</td>' +
                            '<td style="text-align:center;font-size:1.1rem;">→</td>' +
                            '<td style="font-weight:700;">' + rule.consequent + '</td>' +
                            '<td style="text-align:center;font-size:.88rem;">' + (rule.support * 100).toFixed(1) + '%</td>' +
                            '<td style="text-align:center;font-size:.88rem;font-weight:600;">' + (rule.confidence * 100).toFixed(1) + '%</td>' +
                            '<td style="text-align:center;"><span style="font-weight:700;">' + rule.lift.toFixed(2) + 'x</span></td>' +
                            '<td style="text-align:center;font-size:.8rem;">' + liftLabel + '</td>' +
                            '<td style="text-align:center;font-size:.8rem;color:var(--text3);">' + rule.co_occurrences + ' orders</td>' +
                            '</tr>';
                    }).join('');

                    resultEl.innerHTML =
                        '<div style="overflow-x:auto;">' +
                        '<table style="width:100%;border-collapse:collapse;">' +
                        '<thead><tr>' +
                        '<th style="text-align:left;">If customer buys…</th>' +
                        '<th></th>' +
                        '<th style="text-align:left;">They also buy…</th>' +
                        '<th title="% of transactions containing both items">Support</th>' +
                        '<th title="% of antecedent transactions that also have consequent">Confidence</th>' +
                        '<th title="How much more likely vs random chance (>1 = positive, >2 = strong)">Lift</th>' +
                        '<th>Strength</th>' +
                        '<th>Co-occurs</th>' +
                        '</tr></thead>' +
                        '<tbody>' + rows + '</tbody>' +
                        '</table></div>' +
                        '<div style="margin-top:14px;padding:14px;background:var(--surface2);border-radius:var(--r-sm);">' +
                        '<div style="font-weight:600;font-size:.85rem;margin-bottom:6px;">💡 How to use these insights:</div>' +
                        '<div style="font-size:.8rem;color:var(--text2);line-height:1.7;">' +
                        '• <strong>Bundle deals</strong> — pair high-lift products for combo promotions<br>' +
                        '• <strong>Shelf placement</strong> — put strongly associated products near each other<br>' +
                        '• <strong>Cross-selling</strong> — suggest the consequent when a customer buys the antecedent<br>' +
                        '• <strong>Lift &gt; 2.0</strong> means customers are 2× more likely to buy those items together' +
                        '</div>' +
                        '</div>';
                });
            }

            // ════════════════════════════════════════════
            // ML PRODUCT COMBO RECOMMENDATIONS
            // ════════════════════════════════════════════
            async function loadCombos() {
                const resultEl = document.getElementById('combo-result');
                if (resultEl) resultEl.innerHTML = '<div style="text-align:center;padding:30px;color:var(--text3);">🤖 Fetching ML combo recommendations…</div>';

                const cartRaw = (document.getElementById('combo-cart')?.value || '').trim();
                const topN = parseInt(document.getElementById('combo-topn')?.value) || 5;
                const cartItems = cartRaw ? cartRaw.split(',').map(s => s.trim()).filter(Boolean) : [];

                const r = await apiPost('get_combo_recommendations', {
                    cart_items: cartItems,
                    top_n: topN
                });

                if (!resultEl) return;
                if (!r?.success) {
                    resultEl.innerHTML = '<div class="empty-state"><div class="empty-icon">⚠️</div><div class="empty-text">' +
                        (r?.error || 'Could not reach ML API. Make sure pos-ml-api.onrender.com is online.') +
                        '</div></div>';
                    return;
                }

                const data = r.data || {};
                // API returns 'recommendations'; local offline fallback returns 'combos' (also mirrored into
                // 'recommendations' server-side, but we read 'combos' first since its shape is different).
                const recs = (data.combos && data.combos.length) ? data.combos : (data.recommendations || []);
                const basedOn = data.based_on || [];
                const isLocal = data.source === 'local';

                const offlineBanner = isLocal ?
                    '<div style="background:rgba(244,160,36,.12);border:1.5px solid rgba(244,160,36,.4);border-radius:10px;padding:10px 14px;margin-bottom:12px;font-size:.83rem;color:#7a5500;">📡 <strong>Offline mode:</strong> ' +
                    (data.message || 'ML API unreachable — showing combos computed from your own sales history.') + '</div>' :
                    '';

                if (!recs.length) {
                    resultEl.innerHTML = offlineBanner + '<div class="empty-state"><div class="empty-icon">🤝</div>' +
                        '<div class="empty-text">No combo recommendations found. Make some sales transactions first, or try different cart items.</div></div>';
                    return;
                }

                const basedOnHtml = (basedOn.length && !isLocal) ?
                    '<div style="margin-bottom:12px;font-size:.82rem;color:var(--text2);">Based on: ' +
                    basedOn.map(i => '<strong>' + i + '</strong>').join(', ') + '</div>' :
                    '';

                const cards = recs.map((rec, idx) => {
                    const rank = idx + 1;

                    if (isLocal || (rec.item_a && rec.item_b)) {
                        // ── Local co-occurrence shape ──
                        const label = rec.label || (rec.item_a + ' + ' + rec.item_b);
                        const freqTag = rec.frequency !== undefined ?
                            '<span style="font-size:.75rem;font-weight:700;color:var(--accent2);background:rgba(244,160,36,.08);border-radius:6px;padding:2px 8px;">' + rec.frequency + '% of orders</span>' : '';
                        const cntTag = rec.co_occurrences !== undefined ?
                            '<span style="font-size:.75rem;color:var(--text3);">' + rec.co_occurrences + ' co-purchases</span>' : '';
                        return '<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:10px;background:var(--surface);border:1px solid var(--border);margin-bottom:8px;">' +
                            '<div style="font-size:1.5rem;font-weight:900;color:var(--text3);min-width:28px;text-align:center;">' + rank + '</div>' +
                            '<div style="flex:1;">' +
                            '<div style="font-weight:700;font-size:.95rem;">' + label + '</div>' +
                            '<div style="display:flex;gap:8px;margin-top:4px;flex-wrap:wrap;">' + freqTag + cntTag + '</div>' +
                            '</div>' +
                            '<div style="font-size:1.4rem;">🛍️</div>' +
                            '</div>';
                    }

                    // ── ML API shape ──
                    const name = rec.recommended_products ?? rec.product ?? (typeof rec === 'string' ? rec : JSON.stringify(rec));
                    const lift = rec.lift !== undefined ? parseFloat(rec.lift) : null;
                    const conf = rec.confidence !== undefined ? (parseFloat(rec.confidence) * 100).toFixed(1) + '%' : null;
                    const liftBg = lift >= 2 ? 'rgba(45,122,58,.1)' : lift >= 1 ? 'rgba(244,160,36,.08)' : 'rgba(212,80,10,.06)';
                    const liftColor = lift >= 2 ? 'var(--green)' : lift >= 1 ? 'var(--accent2)' : 'var(--danger)';
                    const liftTag = lift !== null ? '<span style="font-size:.75rem;font-weight:700;color:' + liftColor + ';background:' + liftBg + ';border-radius:6px;padding:2px 8px;">lift ' + lift.toFixed(2) + 'x</span>' : '';
                    const confTag = conf ? '<span style="font-size:.75rem;color:var(--text3);">conf ' + conf + '</span>' : '';
                    return '<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:10px;background:var(--surface);border:1px solid var(--border);margin-bottom:8px;">' +
                        '<div style="font-size:1.5rem;font-weight:900;color:var(--text3);min-width:28px;text-align:center;">' + rank + '</div>' +
                        '<div style="flex:1;">' +
                        '<div style="font-weight:700;font-size:.95rem;">' + name + '</div>' +
                        '<div style="display:flex;gap:8px;margin-top:4px;flex-wrap:wrap;">' + liftTag + confTag + '</div>' +
                        '</div>' +
                        '<div style="font-size:1.4rem;">🛍️</div>' +
                        '</div>';
                }).join('');

                resultEl.innerHTML = offlineBanner + basedOnHtml + cards +
                    '<div style="margin-top:10px;padding:10px 12px;background:var(--surface);border-radius:8px;border-left:3px solid var(--accent);font-size:.82rem;color:var(--text2);">' +
                    '💡 <strong>How to use:</strong> Bundle these products together, create combo deals, or suggest them at checkout when the base item is in cart.' +
                    '</div>';
            }

            // ════════════════════════════════════════════
            // TRANSFER WAREHOUSE → STORE
            // ════════════════════════════════════════════
            let _allProdsForTransfer = [];

            function openTransferModal() {
                // Load all products for the dropdown
                apiGet('get_products').then(r => {
                    if (!r?.success) return;
                    _allProdsForTransfer = r.data;
                    _populateTransferDropdown(-1);
                });
                document.getElementById('transfer-qty').value = '';
                document.getElementById('transfer-note').value = '';
                document.getElementById('transfer-wh-avail').textContent = '—';
                openModal('transfer-modal');
            }

            function openTransferModalFor(productId) {
                const existing = _allProdsForTransfer.length ? Promise.resolve({
                    success: true,
                    data: _allProdsForTransfer
                }) : apiGet('get_products');
                existing.then ? existing.then(r => {
                    if (!r?.success) return;
                    _allProdsForTransfer = r.data;
                    _populateTransferDropdown(productId);
                }) : null;
                // If data already loaded
                if (_allProdsForTransfer.length) _populateTransferDropdown(productId);
                else {
                    apiGet('get_products').then(r => {
                        if (!r?.success) return;
                        _allProdsForTransfer = r.data;
                        _populateTransferDropdown(productId);
                    });
                }
                document.getElementById('transfer-qty').value = '';
                document.getElementById('transfer-note').value = '';
                openModal('transfer-modal');
            }

            function _populateTransferDropdown(selectedId) {
                const sel = document.getElementById('transfer-product');
                if (!sel) return;
                const prods = _allProdsForTransfer.length ? _allProdsForTransfer : (typeof whProds !== 'undefined' ? whProds : []);
                sel.innerHTML = prods.map(p => {
                    const wq = p.warehouse_quantity !== undefined ? p.warehouse_quantity : 0;
                    return '<option value="' + p.id + '"' + (p.id == selectedId ? ' selected' : '') + '>' +
                        p.name + ' (WH: ' + wq + ')</option>';
                }).join('');
                sel.onchange = _updateTransferAvail;
                _updateTransferAvail();
            }

            function _updateTransferAvail() {
                const sel = document.getElementById('transfer-product');
                if (!sel) return;
                const pid = parseInt(sel.value);
                const prods = _allProdsForTransfer.length ? _allProdsForTransfer : (typeof whProds !== 'undefined' ? whProds : []);
                const p = prods.find(x => x.id == pid);
                const avail = p ? (p.warehouse_quantity !== undefined ? p.warehouse_quantity : 0) : 0;
                // Same case/bundle/pcs split already used on the Warehouse table itself —
                // reused here, not reimplemented, so the two displays can never drift apart.
                const units = p ? splitQtyIntoUnits(avail, p) : {
                    cases: 0,
                    bundles: 0,
                    pcs: 0
                };
                const setTxt = (id, val) => {
                    const e = document.getElementById(id);
                    if (e) e.textContent = val;
                };
                setTxt('transfer-wh-cases', units.cases || '—');
                setTxt('transfer-wh-bundles', units.bundles || '—');
                setTxt('transfer-wh-pcs', units.pcs || '—');
                const el = document.getElementById('transfer-wh-avail');
                if (el) el.textContent = avail + ' pcs';
            }

            function doTransfer() {
                const pid = parseInt(document.getElementById('transfer-product')?.value);
                const qty = parseInt(document.getElementById('transfer-qty')?.value);
                const note = document.getElementById('transfer-note')?.value.trim() || 'Transfer to store';
                if (!pid || !qty || qty < 1) {
                    toast('Select product and enter quantity', 'error');
                    return;
                }
                const btn = document.getElementById('transfer-save-btn');
                setLoading(btn, true);
                apiPost('transfer_to_store', {
                    product_id: pid,
                    qty,
                    note
                }).then(r => {
                    setLoading(btn, false);
                    if (!r?.success) {
                        toast(r?.error || 'Transfer failed', 'error');
                        return;
                    }
                    toast('✅ Transferred to store shelf!', 'success');
                    closeModal('transfer-modal');
                    _allProdsForTransfer = [];
                    if (typeof loadWhProducts === 'function') {
                        loadWhProducts();
                        loadWhLog();
                    }
                    if (typeof loadInvProds === 'function') loadInvProds();
                });
            }

            document.addEventListener('DOMContentLoaded', function() {
                dashInit();
                prodsInit();
                salesInit();
                analyticsInit();
                forecastInit();
                settingsInit();
                warehouseInit();
                checkShiftLock(); // "No Count, No Transaction" mandatory shift gate — runs on every protected page

                // ── QUIETLY WAKE UP THE ML API IN THE BACKGROUND ──
                // Render's free tier puts pos-ml-api.onrender.com to sleep after a
                // period of no traffic, and the first request after that can take
                // 20-30s to respond while it spins back up. Rather than the user
                // eating that wait the moment they actually open Forecast/Combos,
                // fire a throwaway request the instant the app itself loads — by
                // the time they navigate there, the instance has had a head start.
                // Deliberately NOT awaited — this must never block or be visible to
                // the user, success or failure. Once per browser tab per 10 minutes
                // (not on every single page click) so it doesn't add needless load.
                (function warmMlApiInBackground() {
                    const lastWarm = parseInt(sessionStorage.getItem('_mlWarmAt') || '0', 10);
                    if (Date.now() - lastWarm < 10 * 60 * 1000) return;
                    sessionStorage.setItem('_mlWarmAt', String(Date.now()));
                    // Raw fetch on purpose, NOT apiGet() — apiGet() toasts on failure
                    // and redirects to login on a 401, neither of which should ever
                    // happen to the user because of a silent background warm-up ping.
                    fetch(API_BASE + 'get_ml_stores').catch(() => {});
                })();

                // Show & init draggable scanner on dashboard only
                const sf = document.getElementById('scanner-float');
                if (sf && typeof cur_page !== 'undefined' && cur_page === 'dashboard') {
                    sf.style.display = 'block';
                    initDraggableScanner();
                }
                // Sync cart count in scanner pay button whenever cart changes
                const origRenderCart = typeof renderCart === 'function' ? renderCart : null;

                // ── CART: NO-MOUSE KEYBOARD HOTKEY NAVIGATION ──────────────────────────
                // Active only while the Cart modal is open. ↑/↓ move the highlighted row
                // (and real focus) between qty boxes; ←/→ step that row's qty by 1;
                // typing a number while a qty box is focused edits it directly (native
                // input behavior — no extra code needed); Enter/H/E/C/X drive the
                // Process Payment / Hold / Held Carts / Clear / Exit terminal actions.
                (function initCartKeyboardNav() {
                    document.addEventListener('keydown', function(e) {
                        const cartModal = document.getElementById('cart-modal');
                        if (!cartModal || !cartModal.classList.contains('open')) return;

                        const active = document.activeElement;
                        const inQtyInput = !!(active && active.classList && active.classList.contains('cart-qty-input'));
                        const inCashInput = !!(active && active.id === 'cash-input');
                        const isTypingField = !!(active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA'));

                        switch (e.key) {
                            case 'ArrowUp':
                                if (!cart.length) return;
                                e.preventDefault();
                                if (inCashInput) {
                                    // Step back up out of Cash Tendered into the last cart row.
                                    focusedCartIdx = cart.length - 1;
                                    focusCartQtyInput(cart[focusedCartIdx].product_id);
                                    renderCartFocusHighlight();
                                    break;
                                }
                                focusedCartIdx = focusedCartIdx <= 0 ? cart.length - 1 : focusedCartIdx - 1;
                                focusCartQtyInput(cart[focusedCartIdx].product_id);
                                renderCartFocusHighlight();
                                break;
                            case 'ArrowDown':
                                if (inCashInput || !cart.length) return;
                                e.preventDefault();
                                if (focusedCartIdx >= cart.length - 1) {
                                    // Done scanning/adjusting — hand off straight to Cash Tendered so
                                    // the cashier can type the amount and hit Enter with no mouse.
                                    focusedCartIdx = -1;
                                    renderCartFocusHighlight();
                                    const cashEl = document.getElementById('cash-input');
                                    if (cashEl) {
                                        cashEl.focus();
                                        cashEl.select();
                                    }
                                    break;
                                }
                                focusedCartIdx = focusedCartIdx + 1;
                                focusCartQtyInput(cart[focusedCartIdx].product_id);
                                renderCartFocusHighlight();
                                break;
                            case 'ArrowLeft':
                                if (inCashInput || focusedCartIdx < 0 || focusedCartIdx >= cart.length) return;
                                e.preventDefault();
                                changeQty(cart[focusedCartIdx].product_id, -1);
                                break;
                            case 'ArrowRight':
                                if (inCashInput || focusedCartIdx < 0 || focusedCartIdx >= cart.length) return;
                                e.preventDefault();
                                changeQty(cart[focusedCartIdx].product_id, 1);
                                break;
                            case 'Enter': {
                                e.preventDefault();
                                // Commit whatever qty was just typed before charging, in case
                                // Enter fired before the input's own change/blur handler did.
                                if (inQtyInput) {
                                    const pid = parseInt(active.id.replace('cart-qty-', ''));
                                    setQtyDirect(pid, active.value);
                                }
                                const payBtn = document.getElementById('pay-btn');
                                if (payBtn && !payBtn.disabled) processPayment();
                                break;
                            }
                            case 'h':
                            case 'H':
                                if (isTypingField) return;
                                e.preventDefault();
                                holdCurrentCart();
                                break;
                            case 'e':
                            case 'E':
                                if (isTypingField) return;
                                e.preventDefault();
                                toggleHeldCartsMenu();
                                break;
                            case 'c':
                            case 'C':
                                if (isTypingField) return;
                                e.preventDefault();
                                clearCart();
                                break;
                            case 'x':
                            case 'X':
                                if (isTypingField) return;
                                e.preventDefault();
                                closeModal('cart-modal');
                                break;
                        }
                    });

                    // Click outside the Held Carts dropdown to close it
                    document.addEventListener('click', function(e) {
                        const menu = document.getElementById('held-carts-menu');
                        const btn = document.getElementById('held-carts-btn');
                        if (!menu || menu.style.display === 'none') return;
                        if (!menu.contains(e.target) && !btn.contains(e.target)) menu.style.display = 'none';
                    });
                })();

                // ── ALL MODALS: NO-MOUSE SCROLL NAVIGATION ─────────────────────────────
                // Every other modal (Void Order, Add Product, Product History, etc.) can
                // overflow taller than the screen, and until now the only way to reach
                // the cut-off content was a mouse wheel or dragging the scrollbar. This
                // mirrors the Cart's own no-mouse philosophy for the rest of the app:
                // ↑/↓/PageUp/PageDown/Home/End scroll the open modal vertically, ←/→
                // scroll a wide table (Product History) horizontally. Skipped whenever
                // focus is in a text field so normal typing/cursor movement is never
                // hijacked, and skipped entirely for the Cart modal since its own arrows
                // already mean something else there (see initCartKeyboardNav above).
                (function initModalScrollNav() {
                    const SCROLL_KEYS = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'PageUp', 'PageDown', 'Home', 'End'];
                    document.addEventListener('keydown', function(e) {
                        if (!SCROLL_KEYS.includes(e.key)) return;
                        const active = document.activeElement;
                        const isTypingField = !!(active && (
                            (active.tagName === 'INPUT' && !['checkbox', 'radio', 'button'].includes(active.type)) ||
                            active.tagName === 'TEXTAREA' || active.tagName === 'SELECT' || active.isContentEditable
                        ));
                        if (isTypingField) return;
                        const openModals = Array.from(document.querySelectorAll('.modal-overlay.open'));
                        const top = openModals[openModals.length - 1];
                        if (!top || top.id === 'cart-modal') return;
                        const modalBody = top.querySelector('.modal');
                        if (!modalBody) return;
                        // Prefer a wide table's own horizontal-scroll wrapper for ←/→ (e.g.
                        // Product History) over the modal's outer container, which usually
                        // has no horizontal overflow of its own.
                        const tableWrap = top.querySelector('.table-wrap');
                        const STEP = 70;
                        switch (e.key) {
                            case 'ArrowUp':
                                e.preventDefault();
                                modalBody.scrollBy({
                                    top: -STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'ArrowDown':
                                e.preventDefault();
                                modalBody.scrollBy({
                                    top: STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'ArrowLeft':
                                e.preventDefault();
                                (tableWrap && tableWrap.scrollWidth > tableWrap.clientWidth ? tableWrap : modalBody).scrollBy({
                                    left: -STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'ArrowRight':
                                e.preventDefault();
                                (tableWrap && tableWrap.scrollWidth > tableWrap.clientWidth ? tableWrap : modalBody).scrollBy({
                                    left: STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'PageUp':
                                e.preventDefault();
                                modalBody.scrollBy({
                                    top: -modalBody.clientHeight * 0.85,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'PageDown':
                                e.preventDefault();
                                modalBody.scrollBy({
                                    top: modalBody.clientHeight * 0.85,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'Home':
                                e.preventDefault();
                                modalBody.scrollTo({
                                    top: 0,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'End':
                                e.preventDefault();
                                modalBody.scrollTo({
                                    top: modalBody.scrollHeight,
                                    behavior: 'smooth'
                                });
                                break;
                        }
                    });
                })();

                // ── PAGE-LEVEL SCROLL PANELS: NO-MOUSE SCROLL NAVIGATION ────────────────
                // Products (Warehouse), Recent Stock Movements (Warehouse), and Sales
                // History are no longer behind a collapse/expand toggle — they're always
                // fully visible now, which means they can run taller than the screen.
                // Each one is wrapped in a focusable .scroll-panel (tabindex="0"): Tab to
                // it, then ↑/↓/←/→/PageUp/PageDown/Home/End scroll that specific table in
                // every direction — no mouse or scrollbar needed. Skipped while typing in
                // a field so normal cursor movement is never hijacked.
                (function initScrollPanelNav() {
                    const SCROLL_KEYS = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'PageUp', 'PageDown', 'Home', 'End'];
                    document.addEventListener('keydown', function(e) {
                        if (!SCROLL_KEYS.includes(e.key)) return;
                        const active = document.activeElement;
                        const isTypingField = !!(active && (
                            (active.tagName === 'INPUT' && !['checkbox', 'radio', 'button'].includes(active.type)) ||
                            active.tagName === 'TEXTAREA' || active.tagName === 'SELECT' || active.isContentEditable
                        ));
                        if (isTypingField) return;
                        const panel = active && active.closest ? active.closest('.scroll-panel') : null;
                        if (!panel) return;
                        const STEP = 70;
                        switch (e.key) {
                            case 'ArrowUp':
                                e.preventDefault();
                                panel.scrollBy({
                                    top: -STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'ArrowDown':
                                e.preventDefault();
                                panel.scrollBy({
                                    top: STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'ArrowLeft':
                                e.preventDefault();
                                panel.scrollBy({
                                    left: -STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'ArrowRight':
                                e.preventDefault();
                                panel.scrollBy({
                                    left: STEP,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'PageUp':
                                e.preventDefault();
                                panel.scrollBy({
                                    top: -panel.clientHeight * 0.85,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'PageDown':
                                e.preventDefault();
                                panel.scrollBy({
                                    top: panel.clientHeight * 0.85,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'Home':
                                e.preventDefault();
                                panel.scrollTo({
                                    top: 0,
                                    behavior: 'smooth'
                                });
                                break;
                            case 'End':
                                e.preventDefault();
                                panel.scrollTo({
                                    top: panel.scrollHeight,
                                    behavior: 'smooth'
                                });
                                break;
                        }
                    });
                })();


                // Physical scanners act as keyboards: they type chars fast then send Enter.
                // We intercept that here and route to the correct handler per page/context.
                (function initGlobalHIDScanner() {
                    let _buf = '';
                    let _lastKey = 0;
                    let _fastStreak = 0; // consecutive keystrokes arriving faster than HID_SPEED_MS
                    const HID_SPEED_MS = 50; // chars typed faster than this = candidate scanner speed
                    const HID_MIN_LEN = 3; // minimum barcode length to accept
                    // Fields where typing is the field's own intended behavior. A real
                    // scanner's keystrokes are near-simultaneous (typically <15ms apart,
                    // consistently, for every character) — a fast human typist can dip
                    // under 50ms on an isolated keystroke but essentially never sustains
                    // it for 3+ characters in a row. Requiring a streak (see _fastStreak
                    // below) rather than a single fast gap is what keeps this list short:
                    // it's a backstop for known scan-target fields, not the sole defense.
                    const MANUAL_ENTRY_FIELD_IDS = new Set([
                        'dash-manual-bc', 'prod-scan-manual',
                        'new-cat-input', 'p-barcode',
                        'qr-cases', 'qr-bundle', 'qr-pcs',
                        'po-cases', 'po-bundle', 'po-pcs',
                    ]);
                    // Classes used for fields that repeat per-row (cart items, New Delivery
                    // line items) and so can't be matched by a single fixed id.
                    const MANUAL_ENTRY_FIELD_CLASSES = [
                        'cart-qty-input', 'nd-product-search',
                        'nd-st-cases', 'nd-st-bundle', 'nd-st-pcs',
                        'nd-wh-cases', 'nd-wh-bundle', 'nd-wh-pcs',
                    ];
                    const isManualEntryField = () => {
                        const el = document.activeElement;
                        if (!el) return false;
                        if (MANUAL_ENTRY_FIELD_IDS.has(el.id)) return true;
                        return MANUAL_ENTRY_FIELD_CLASSES.some(c => el.classList?.contains(c));
                    };

                    document.addEventListener('keydown', function(e) {
                        // Never intercept if user is typing in an input/textarea/select
                        const tag = document.activeElement?.tagName?.toLowerCase();
                        const isEditable = tag === 'input' || tag === 'textarea' || tag === 'select' ||
                            document.activeElement?.isContentEditable;

                        const now = Date.now();
                        const fast = (now - _lastKey) < HID_SPEED_MS;
                        _lastKey = now;
                        _fastStreak = fast ? _fastStreak + 1 : 0;
                        // Require 3 consecutive fast keystrokes (a real scanner's whole
                        // burst) before treating this as scanner input inside an editable
                        // field. A single quick keystroke from a fast human typist no
                        // longer counts, and only the LAST field of an Enter-driven manual
                        // entry (cart qty, category name, etc.) can even be reached this
                        // way, since scans there are meant to be read as scans anyway.
                        const looksLikeScanner = _fastStreak >= 3;

                        if (e.key === 'Enter') {
                            const code = _buf.trim();
                            _buf = '';
                            _fastStreak = 0;
                            if (!code || code.length < HID_MIN_LEN) return;

                            // If focus is inside a field meant for direct typing (manual
                            // barcode entry, cart qty, category name, etc.), only steal Enter
                            // away from that field's own handler when the keystrokes leading
                            // up to it actually looked like a scanner burst, not human typing.
                            if (isManualEntryField() && !looksLikeScanner) return;

                            e.preventDefault();
                            routeHIDScan(code);
                            return;
                        }

                        // Accumulate printable characters into the buffer. We used to refuse
                        // to buffer the very FIRST character whenever an input field had focus
                        // and it arrived "slowly" (old rule: isEditable && !fast && empty
                        // buffer = assume human, ignore it). The problem: a scanner's first
                        // keystroke *always* looks "slow" too, because the gap is measured
                        // against whatever happened before the scan even started (e.g. the
                        // idle time after clicking into the barcode field to prepare to
                        // scan) — not against the scanner's own typing speed. That silently
                        // dropped the first digit of the barcode any time someone scanned
                        // while a field (like the barcode field itself) was focused, so the
                        // saved barcode came out one character short and never matched a
                        // later full re-scan ("Not found").
                        //
                        // Fix: always buffer the character. Only retroactively drop it if a
                        // SECOND character in a row also arrives slowly while a field is
                        // focused — two slow keystrokes back-to-back really is human typing.
                        // This still resets on every slow keystroke, so sustained normal
                        // typing never accumulates into a false "scan".
                        if (e.key.length === 1) {
                            if (isEditable && _buf.length === 1 && !fast) {
                                _buf = '';
                            }
                            // Once we're confident a fast scan is under way (a sustained
                            // 3-keystroke-or-more burst, not just one quick keystroke), stop
                            // it from ALSO being typed natively into whatever field happens to
                            // be focused — e.g. a cart quantity box. This is what let a second
                            // scan of an already-in-cart product silently overwrite its
                            // quantity field with the raw barcode digits (which then got
                            // clamped down to "whole stock available") instead of just
                            // incrementing by 1. Requiring a streak — rather than a single
                            // fast gap — is what keeps a fast human typist's own input intact.
                            if (isEditable && looksLikeScanner && _buf.length >= 1) {
                                e.preventDefault();
                            }
                            _buf += e.key;
                        } else if (e.key !== 'Shift') {
                            // Non-printable key that isn't Shift = probably human; reset buffer
                            if (!fast) _buf = '';
                        }
                    });

                    function routeHIDScan(barcode) {
                        // Normalise: strip leading/trailing whitespace
                        barcode = barcode.replace(/^\s+|\s+$/g, '');
                        if (!barcode) return;

                        // 0. Scanning the barcode printed on a receipt (format ORD-XXXXXX) jumps
                        // straight into the Void flow: openVoidOrderModal(prefillRef) already
                        // auto-verifies the code and lands on item selection, so the cashier
                        // never has to type or click Verify — scan, tick items, get an admin
                        // to confirm. Checked before every other scan target since the format
                        // is specific enough to never collide with a real product barcode.
                        if (/^ORD-[A-Z0-9]{4,}$/i.test(barcode)) {
                            openVoidOrderModal(barcode.toUpperCase());
                            return;
                        }

                        // 1. If the New Delivery modal is open, fill whichever line item's
                        // product search box currently has focus — deliberately NOT "always
                        // add a new line", so the person controls exactly which row a scan
                        // lands in when several rows are already open. Falls back to
                        // _ndFocusedRowId (the last row that was actually tapped/typed in)
                        // if document.activeElement isn't the field at this exact instant —
                        // a scanner burst can land right as a suggestion-list tap or an
                        // on-screen keyboard event momentarily shifts focus away from it.
                        const ndModal = document.getElementById('new-delivery-modal');
                        if (ndModal && ndModal.classList.contains('open')) {
                            const active = document.activeElement;
                            let targetRowId = null;
                            if (active && active.classList && active.classList.contains('nd-product-search')) {
                                targetRowId = active.closest('.nd-item')?.id;
                            } else if (_ndFocusedRowId && document.getElementById(_ndFocusedRowId)) {
                                targetRowId = _ndFocusedRowId;
                            }
                            if (targetRowId) {
                                apiGet('get_product_by_barcode', {
                                    barcode
                                }).then(r => {
                                    if (!r?.success) {
                                        toast('Product not found: ' + barcode, 'error');
                                        return;
                                    }
                                    const p = r.data;
                                    if (!whProds.find(x => x.id == p.id)) whProds.push(p);
                                    const itemId = parseInt(targetRowId.replace('nd-item-', ''));
                                    _ndSelectProduct(itemId, p.id);
                                    toast('✅ Scanned: ' + p.name, 'success');
                                });
                                return;
                            }
                            toast('Tap a product field first, then scan', 'warning');
                            return;
                        }

                        // 2. If product modal is open (add/edit) → fill barcode field
                        const prodModal = document.getElementById('prod-modal');
                        if (prodModal && prodModal.classList.contains('open')) {
                            const inp = document.getElementById('p-barcode');
                            if (inp) {
                                inp.value = barcode;
                                inp.dispatchEvent(new Event('input'));
                                toast('Barcode scanned into field', 'success');
                            }
                            return;
                        }

                        // 3. On the Warehouse page with nothing else already open, scanning a
                        // product barcode almost always means "log a delivery for this" —
                        // open New Delivery, drop the scanned product straight into its
                        // first line item, and prefill Supplier/Reference from the
                        // product's own saved supplier (if it has one).
                        if (cur_page === 'warehouse' && !document.querySelector('.modal-overlay.open')) {
                            apiGet('get_product_by_barcode', {
                                barcode
                            }).then(r => {
                                if (!r?.success) {
                                    toast('Product not found: ' + barcode, 'error');
                                    return;
                                }
                                const p = r.data;
                                if (!whProds.find(x => x.id == p.id)) whProds.push(p);
                                openNewDeliveryModal();
                                _ndSelectProduct(1, p.id); // openNewDeliveryModal always seeds row #1
                                const supplierEl = document.getElementById('nd-supplier');
                                if (supplierEl && p.supplier) supplierEl.value = p.supplier;
                                toast('✅ Scanned into New Delivery: ' + p.name, 'success');
                            });
                            return;
                        }

                        // 4. Default → add to cart (works on dashboard from anywhere)
                        apiGet('get_product_by_barcode', {
                            barcode
                        }).then(r => {
                            if (!r?.success) {
                                toast('Product not found: ' + barcode, 'error');
                                return;
                            }
                            const p = r.data;
                            if (!allProds.find(x => x.id == p.id)) allProds.push(p);
                            const wasEmpty = cart.length === 0;
                            const addQty = scanUnitQty(p);
                            addToCart(p.id, addQty);
                            updateScanCartCount();
                            toast('✅ Added: ' + p.name + (addQty > 1 ? ' ×' + addQty : ''), 'success');
                            // First scan of a new sale — pop the Cart open automatically so the
                            // cashier can go straight to keyboard hotkeys with zero mouse clicks.
                            if (wasEmpty) {
                                const cartModalEl = document.getElementById('cart-modal');
                                if (cartModalEl && !cartModalEl.classList.contains('open')) openModal('cart-modal');
                            }
                        });
                    }

                    // Expose so other code can trigger a scan programmatically if needed
                    window.triggerHIDScan = routeHIDScan;
                })();

                // ── GLOBAL KEYBOARD SHORTCUTS (page-aware) ─────────────────────────────
                // The Cart already has its own dedicated key handler (initCartKeyboardNav,
                // above) for when the Cart modal itself is open. This handler covers the
                // rest of the app: one key per page for the action a cashier/owner reaches
                // for most on that screen — most importantly "V" for Void, on both the
                // Dashboard and the Sales page, per request. Never fires while typing in a
                // field, while any modal is already open (so it can't fire "underneath"
                // a modal and do something unexpected), or alongside Ctrl/Cmd/Alt combos
                // (so browser/OS shortcuts are never hijacked).
                (function initGlobalShortcuts() {
                    const SHORTCUTS = {
                        dashboard: [{
                                key: 'v',
                                label: 'V',
                                desc: 'Void an order',
                                action: () => openVoidOrderModal()
                            },
                            {
                                key: 'o',
                                label: 'O',
                                desc: 'Open Cart',
                                action: () => openModal('cart-modal')
                            },
                            {
                                key: '/',
                                label: '/',
                                desc: 'Focus product search',
                                action: () => document.getElementById('search-inp')?.focus()
                            },
                        ],
                        products: [{
                                key: 'n',
                                label: 'N',
                                desc: 'Add a new product',
                                action: () => openAddModal()
                            },
                            {
                                key: '/',
                                label: '/',
                                desc: 'Focus product search',
                                action: () => document.getElementById('prod-search')?.focus()
                            },
                        ],
                        warehouse: [{
                                key: 'n',
                                label: 'N',
                                desc: 'New stock movement',
                                action: () => openMoveModal()
                            },
                            {
                                key: 'p',
                                label: 'P',
                                desc: 'Print all barcodes',
                                action: () => openPrintAllModal()
                            },
                            {
                                key: 'h',
                                label: 'H',
                                desc: 'Product history',
                                action: () => openHistoryModal()
                            },
                            {
                                key: '/',
                                label: '/',
                                desc: 'Focus warehouse search',
                                action: () => document.getElementById('wh-search')?.focus()
                            },
                        ],
                        sales: [{
                                key: 'v',
                                label: 'V',
                                desc: 'Void an order',
                                action: () => openVoidOrderModal()
                            },
                            {
                                key: '/',
                                label: '/',
                                desc: 'Focus by date filter',
                                action: () => document.getElementById('date-range-btn')?.click()
                            },
                        ],
                    };
                    // Inside the Cart itself, once it's open: H=Hold, E=Held carts, C=Clear,
                    // X=Close, Enter=Charge, arrows=navigate/adjust qty (see
                    // initCartKeyboardNav above) — listed here too so "?" shows the whole
                    // picture even though that handler runs separately.
                    const CART_SHORTCUTS = [{
                            label: 'H',
                            desc: 'Hold current cart'
                        },
                        {
                            label: 'E',
                            desc: 'Show held carts'
                        },
                        {
                            label: 'C',
                            desc: 'Clear cart'
                        },
                        {
                            label: 'X',
                            desc: 'Close cart'
                        },
                        {
                            label: '↑ / ↓',
                            desc: 'Move between cart lines'
                        },
                        {
                            label: '← / →',
                            desc: 'Adjust highlighted line qty'
                        },
                        {
                            label: 'Enter',
                            desc: 'Charge / confirm'
                        },
                    ];

                    function currentShortcuts() {
                        return SHORTCUTS[cur_page] || [];
                    }

                    document.addEventListener('keydown', function(e) {
                        const active = document.activeElement;
                        const isTypingField = !!(active && (
                            active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' ||
                            active.tagName === 'SELECT' || active.isContentEditable
                        ));
                        if (isTypingField) return;
                        if (e.ctrlKey || e.metaKey || e.altKey) return;

                        if (e.key === '?') {
                            e.preventDefault();
                            showShortcutsHelp();
                            return;
                        }

                        // Every other shortcut is suppressed while any modal is open — the
                        // Cart's own handler covers the Cart modal; other modals (Add
                        // Product, Void Order, etc.) are plain forms and shouldn't have a
                        // page-level shortcut fire underneath them.
                        if (document.querySelector('.modal-overlay.open')) return;

                        const match = currentShortcuts().find(s => s.key === e.key.toLowerCase());
                        if (match) {
                            e.preventDefault();
                            match.action();
                        }
                    });

                    // Builds/opens a small help overlay listing whatever shortcuts apply to
                    // the page currently open, plus the Cart's own set for reference — no
                    // static HTML needed, it's assembled the first time it's used.
                    window.showShortcutsHelp = function() {
                        let modal = document.getElementById('shortcuts-help-modal');
                        if (!modal) {
                            modal = document.createElement('div');
                            modal.id = 'shortcuts-help-modal';
                            modal.className = 'modal-overlay';
                            modal.innerHTML = '<div class="modal" style="max-width:380px;">' +
                                '<div class="modal-header"><span class="modal-title">⌨️ Keyboard Shortcuts</span><button class="modal-close" onclick="closeModal(\'shortcuts-help-modal\')">✕</button></div>' +
                                '<div id="shortcuts-help-body"></div>' +
                                '</div>';
                            document.body.appendChild(modal);
                            modal.addEventListener('click', e => {
                                if (e.target === modal) closeModal('shortcuts-help-modal');
                            });
                        }
                        const row = (label, desc) =>
                            '<div style="display:flex;align-items:center;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--border);">' +
                            '<kbd style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;padding:2px 8px;font-size:.78rem;font-weight:700;">' + label + '</kbd>' +
                            '<span style="font-size:.83rem;color:var(--text2);">' + desc + '</span></div>';
                        let html = '<div style="font-size:.72rem;font-weight:700;color:var(--text3);text-transform:uppercase;margin:10px 0 4px;">This Page</div>';
                        const pageList = currentShortcuts();
                        html += pageList.length ? pageList.map(s => row(s.label, s.desc)).join('') : '<div style="font-size:.82rem;color:var(--text3);padding:6px 0;">No shortcuts on this page</div>';
                        html += '<div style="font-size:.72rem;font-weight:700;color:var(--text3);text-transform:uppercase;margin:14px 0 4px;">Inside the Cart</div>';
                        html += CART_SHORTCUTS.map(s => row(s.label, s.desc)).join('');
                        html += row('?', 'Show this help');
                        document.getElementById('shortcuts-help-body').innerHTML = html;
                        openModal('shortcuts-help-modal');
                    };

                    // Small persistent discovery button — bottom-left, clear of the toast
                    // stack, pending-sync badge, and scanner float which all live on the
                    // right side. Only shown on pages that actually have shortcuts.
                    if (currentShortcuts().length) {
                        const helpBtn = document.createElement('button');
                        helpBtn.type = 'button';
                        helpBtn.title = 'Keyboard shortcuts (?)';
                        helpBtn.textContent = '⌨️ ?';
                        helpBtn.style.cssText = 'position:fixed;bottom:22px;left:20px;z-index:500;background:var(--surface);color:var(--text2);border:1.5px solid var(--border);font-weight:700;font-size:.82rem;padding:9px 14px;border-radius:99px;box-shadow:var(--shadow-lg);cursor:pointer;';
                        helpBtn.onclick = () => window.showShortcutsHelp();
                        document.body.appendChild(helpBtn);
                    }
                })();

                // ────────────────────────────────────────────────────────────────────────
            });

            // ════════════════════════════════════════════════
            // SERVICE WORKER (real same-origin worker: sw.php)
            // Caches product photos & logo ON THE DEVICE after first view —
            // instant image loading, even offline. The previous inline
            // blob-URL worker was silently rejected by every browser, so
            // none of this ever actually ran until now.
            // ════════════════════════════════════════════════
            (function() {
                if (!('serviceWorker' in navigator)) return;
                if (location.protocol !== 'https:' && location.hostname !== 'localhost') return; // SW needs HTTPS (or localhost)
                navigator.serviceWorker.register('sw.php', { scope: './' }).catch(() => {});
            })();
        </script>
        </body>

</html>